insert into public.peliculas (tmdb_id, media_type, titulo, titulo_tmdb, titulo_original, anio, direccion, sinopsis, poster_path, backdrop_path, vote_average, trailer_youtube, listas, pagina_libro, donde_ver, cruce, candidatos) values
(775, 'movie', 'Viaje a la Luna', 'El viaje a la Luna', 'Le Voyage dans la Lune', 1902, 'Georges Méliès', 'El profesor Barbenfouillis y cinco de sus colegas de la Academia de Astronomía viajan a la Luna a bordo de un cohete propulsado por un cañón gigante. Una vez sobre la superficie lunar, los audaces exploradores afrontan los muchos peligros que ocultan las cuevas del misterioso satélite.', '/l58KDN46lKx5RPzu1encomzSuJU.jpg', '/g67r1eiQD3ERSEQFCFkSn7TeGw5.jpg', 7.9, 'JEGIyo-dKmA', array['1001']::text[], 26, null, 'segura', null),
(5698, 'movie', 'Asalto y robo de un tren', 'Asalto y robo de un tren', 'The Great Train Robbery', 1903, 'Edwin S. Porter', 'Un grupo de forajidos prepara un asalto a un tren en el Oeste.', '/wRw5Ur4FJYJHqie3EI6PWKORF99.jpg', '/99uGRUGS2qxNvPARiM8dkuTrUnW.jpg', 7.0, 'In3mRDX0uqk', array['1001']::text[], 28, null, 'segura', null),
(618, 'movie', 'El nacimiento de una nación', 'El nacimiento de una nación', 'The Birth of a Nation', 1915, 'D.W. Griffith', 'Clásico del cine mudo que narra los acontecimientos más importantes de la creación de los Estados Unidos de América: la guerra civil, el asesinato de Lincoln, etc. Ha sido tachada de racista por su glorificación del Ku Klux Klan, pero tiene el mérito de ser la primera película que cuenta una historia de modo coherente: hasta ese momento una película era un conjunto de escenas con muy poca relación entre sí. Obtuvo un enorme éxito en su tiempo.', '/jEdxMrvfu7qkAHy2jE0i2aJCwDH.jpg', '/4H4RAeeykpi0ijvu3wYgV346y06.jpg', 5.9, 'a9UPOkIpR0A', array['1001']::text[], 30, null, 'segura', null),
(29082, 'movie', 'Los vampiros', 'Los vampiros', 'Les Vampires', 1915, 'Louis Feuillade', 'París es presa de un terror invisible contra el que la policía no puede hacer nada: una siniestra organización que siembra el caos y la muerte. El intrépido periodista Philippe Guérande y su compañero inician una larga cruzada con el propósito de acabar con los crímenes del Gran Vampiro e Irma Vep, su peligrosa cómplice.', '/6EeLmuGlay7L6kt6hQQR6PdFhgl.jpg', '/2m95WiiqOQNfJQ2MWa5wlsOApGz.jpg', 7.0, 'Qf-s-jPsm4E', array['1001']::text[], 32, null, 'segura', null),
(3059, 'movie', 'Intolerancia', 'Intolerancia', 'Intolerance: Love''s Struggle Throughout the Ages', 1916, 'D.W. Griffith', 'Clásico del cine mudo que muestra a través de varios episodios históricos las injusticias provocadas por la intolerancia religiosa y social. La idea inicial de Griffith era narrar las sangrientas huelgas de 1912 en EE.UU. (un huelguista es acusado de la muerte de su patrón), pero después decidió rodar tres episodios más: "La caída de Babilonia, "La Pasión de Cristo" y "La noche de San Bartolomé" (sangriento episodio de las luchas entre hugonotes y católicos que tuvo lugar en París en 1572). De presupuesto y recursos desmesurados para la época -una sola escena reunió a 15.000 extras y 250 carros- aún hoy sigue asombrando por su espectacularidad.', '/vPDRFUDY2wP7rLJUXSj1XkbszFf.jpg', '/5s5Vau1tCvoQaaTTTGk4Qux8CcH.jpg', 7.1, 'f0yEkRCpCmw', array['1001']::text[], 34, null, 'segura', null),
(234, 'movie', 'El gabinete del doctor Caligari', 'El gabinete del doctor Caligari', 'Das Cabinet des Dr. Caligari', 1920, 'Robert Wiene', 'Sentado en un banco de un parque, Francis anima a su compañero Alan para que vayan a Holstenwall, una ciudad del norte de Alemania, a ver el espectáculo ambulante del doctor Caligari. Un empleado municipal que le niega al doctor el permiso para actuar, aparece asesinado al día siguiente. Francis y Alan acuden a ver al doctor Caligari y a Cesare, su ayudante sonámbulo, que le anuncia a Alan su porvenir: vivirá hasta el amanecer.', '/xehDbRVWuS31FBU73AUIoiVePIe.jpg', '/sLq72hBx8Xs2IISVsZJqgjOd31b.jpg', 7.9, '6_uvMK0dbMY', array['1001']::text[], 36, null, 'segura', null),
(899, 'movie', 'Lirios rotos', 'Lirios rotos', 'Broken Blossoms or The Yellow Man and the Girl', 1919, 'D.W. Griffith', 'La obra maestra más trágica, poética y melodramática de Griffith Historia sobre una joven que vive en el barrio londinense de Limehouse, que se encuentra atrapada en un ambiente de violencia, en el que su padre, un rudo y malhumorado boxeador ,aficionado a la bebida, la maltrata sin cesar. Testigo de todo ello, es un joven y noble tendero inmigrante chino, que se enamorará de ella y tratará de ayudarla y darle cobijo.', '/njwFIUL76zaRmPemnrZVmmTSCjz.jpg', '/3DW3xHM7FgdE8XzpODbEfvlR9qR.jpg', 6.9, 'kF6B9_Pwgpw', array['1001']::text[], 38, null, 'segura', null),
(31509, 'movie', 'Las dos tormentas', 'Las dos tormentas', 'Way Down East', 1920, 'D.W. Griffith', 'Anna Moore es una joven que va a visitar a Bostón a su acaudalada tía para que ayude a su familia a salir de la pobreza, pero una vez allí un hombre rico la engaña con un matrimonio falso para poder aprovecharse de ella. Cuando Anna se queda embarazada se destapa el engaño y es abandonada a su suerte.', '/bVEKrrA0dRKMrNJpgBY8gdHBwdJ.jpg', '/pG5mCbGpgq9im4vcEQufMIMU8FT.jpg', 6.9, '12WdOsJJSM8', array['1001']::text[], 39, null, 'segura', null),
(77621, 'movie', 'Within Our Gates', 'Puertas adentro', 'Within Our Gates', 1920, 'Oscar Micheaux', 'Micheaux coloca en el centro de su melodrama a una mulata que sufre el linchamiento de su familia y está a punto de ser violada por un terrateniente sureño. En realidad, la narrativa principal se ocupa de los esfuerzos de la protagonista, Sylvia, por encontrar financiación en Boston para la escuela sureña en la que trabaja. Aparte de los amoríos varios, y de una subtrama gangsteril, el núcleo de la película es el tema racial.', '/36MR5nOWUZypLY3i32LCjdqxXOQ.jpg', '/eGhQXfGeNdJfywH6ZmjRwN3f1X8.jpg', 6.1, 'kD_FwBz3JY8', array['1001']::text[], 40, null, 'segura', null),
(58129, 'movie', 'La carreta fantasma', 'La carreta fantasma', 'Körkarlen', 1921, 'Victor Sjöström', 'Es Nochevieja. Tres borrachos evocan una leyenda según la cual si un gran pecador es la última persona que muere al terminar el año, entonces tendrá que conducir durante un año entero la Carreta Fantasma que recoge las almas de los muertos. David Holm, uno de los tres borrachos, muere cuando suena la última campanada de la medianoche...', '/cViRi9KUS06qfDKG89BuDoXa2hn.jpg', '/zMqJoVJXQPvkjZ1SZ03e4EuKMfm.jpg', 7.7, 'DUX2w7TFNHQ', array['1001']::text[], 41, null, 'segura', null),
(49452, 'movie', 'La souriante madame Beudet', 'La sonriente Madame Beudet', 'La Souriante Madame Beudet', 1923, 'Germaine Dulac', 'El filme nos narra la historia de Madame Beudet, una mujer moderna afrancesada a la que le encanta tocar el piano obras de compositores melenudos, leer novelas y modernas revistas; está casada con un empresario textil muy ordinario y rudo que además aburre a su esposa al tener diferentes intereses culturales a los de ella, como ir al teatro a ver Fausto.', '/u3VxEQ2rXMNE6aAozCABG3ziVU3.jpg', '/8M0AmkFWK4lnbNeqa3poxohDk7l.jpg', 6.0, null, array['1001']::text[], 42, null, 'segura', null),
(42511, 'movie', 'Las dos huérfanas', 'Las dos huérfanas', 'Orphans of the Storm', 1921, 'D.W. Griffith', 'Francia, en vísperas de la Revolución francesa. Henriette y Louise se han criado juntas como hermanas. Cuando la plaga que se lleva la vida de sus padres causa la ceguera de Louise, ambas deciden viajar a París en busca de una cura, pero se separan cuando un aristócrata lujurioso se cruza en su camino.', '/gbBzFuiVnuSPYZRXRArILc3Ywz3.jpg', '/hC8i1b3rvz3omOD9PIqV3ziXvA8.jpg', 6.8, 'wDSBEqabQdA', array['1001']::text[], 42, null, 'segura', null),
(5998, 'movie', 'El doctor Mabuse', 'Dr. Mabuse, el jugador', 'Dr. Mabuse, der Spieler', 1922, 'Fritz Lang', 'La primera versión cinematográfica del Dr. Mabuse consta de dos partes: “El gran jugador” y “El infierno”. El doctor Mabuse es un villano que no se siente atraído por los bienes materiales, sino por el placer que le proporciona jugar con el destino de los hombres.', '/k9wjyqFDjfs5acuKqJCr8Vcnywd.jpg', '/sHIwzZ0GBE3Y9vMdQWtsFtc5duV.jpg', 7.7, 'MWZwOH2EKb8', array['1001']::text[], 43, null, 'probable', '[{"tmdb_id": 5998, "titulo": "Dr. Mabuse, el jugador", "original": "Dr. Mabuse, der Spieler", "anio": 1922, "votos": 220, "poster_path": "/k9wjyqFDjfs5acuKqJCr8Vcnywd.jpg", "sim": 0.545}]'::jsonb),
(669, 'movie', 'Nanuk el esquimal', 'Nanuk, el esquimal', 'Nanook of the North', 1922, 'Robert Flaherty', 'Documental sobre la dura vida de los esquimales que viven en la región de Hudson, Canadá.', '/iaeBAKdHq46Xuivl7ENuLasnWFN.jpg', '/1Zgfk1raynguQf9Pvcmx9M5dyDN.jpg', 7.1, 'bkilXJiCfng', array['1001']::text[], 44, null, 'segura', null),
(653, 'movie', 'Nosferatu, el vampiro', 'Nosferatu', 'Nosferatu, eine Symphonie des Grauens', 1922, 'F. W. Murnau', 'Año 1838. En la ciudad de Wisborg viven felices el joven Hutter y su mujer Ellen, hasta que el oscuro agente inmobiliario Knock decide enviar a Hutter a Transilvania para cerrar un negocio con el conde Orlok. Se trata de la venta de una finca de Wisborg, que linda con la casa de Hutter. Durante el largo viaje Hutter pernocta en una posada, donde hojea un viejo tratado sobre vampiros que encuentra en su habitación. Una vez en el castillo, es recibido por el siniestro conde. Al día siguiente, Hutter amanece con dos pequeñas marcas en el cuello, que interpreta como picaduras de mosquito. Una vez firmado el contrato, descubre que el conde es, en realidad, un vampiro. Al verle partir hacia su nuevo hogar, Hutter teme por Ellen.', '/z45rXmIF0zl4uxRc5XcSfz6hYO6.jpg', '/cA9iGtvjRGJHzDBfrq48l0eyCvA.jpg', 7.6, 'e_xpuux5nO0', array['1001']::text[], 46, null, 'segura', null),
(57283, 'movie', 'La brujería a través de los tiempos', 'La brujería a través de los tiempos', 'Häxan', 1922, 'Benjamin Christensen', 'Mezclando el documental y la ficción dramática, la película descubre la relación de los hombres de la Edad Media (su actitud y la proliferación de brujos y brujas) con algunas situaciones actuales. Un repaso al mundo del ocultismo, la magia negra y la brujería, a través de varios siglos, para dibujar un panorama fascinante y estremecedor.', '/yZ6Ne52mj9trTbveig142Mik8UW.jpg', '/gZwQip2KQRDNZZOEDe0Yi25tW9Z.jpg', 7.6, '4RoCKIaE2Eg', array['1001']::text[], 48, null, 'segura', null),
(35227, 'movie', 'Esposas frívolas', 'Esposas frívolas', 'Foolish Wives', 1922, 'Erich von Stroheim', 'Un vividor se hace pasar en Montecarlo por un respetable conde ruso, e intenta seducir a una distinguida dama norteamericana que pasa sus vacaciones con su marido, un destacado diplomático. Jean Renoir declaró que ver esta película fue determinante en su futura carrera como cineasta.', '/GEaYMjWKGgADCu11gOPQSCMJyc.jpg', '/9VR9nofT0dCP30b7WLMkuhykikM.jpg', 6.5, 'O_AK_9TVwvI', array['1001']::text[], 49, null, 'segura', null),
(701, 'movie', 'La ley de la hospitalidad', 'La ley de la hospitalidad', 'Our Hospitality', 1923, 'Buster Keaton, John G. Blystone', 'Los Canfield y los McKay han heredado una enemistad que ha pasado de padres a hijos durante muchas generaciones. Pero, por caprichos del destino, Willie McKay (Buster Keaton) coge un tren en Nueva York, en el que conoce a Virginia Canfield (Natalie Talmadge)...', '/cAEdL6RzfDSbPO51izl01Njzikx.jpg', '/265pOIZG5xsX1I2AnLqzQoNFOL5.jpg', 7.5, '1BWMJ06xDN0', array['1001']::text[], 49, null, 'segura', null),
(28963, 'movie', 'El ladrón de Bagdad', 'El ladrón de Bagdad', 'The Thief of Bagdad', 1924, 'Raoul Walsh', 'Abú, un ladronzuelo que actúa por las calles de Bagdad, es detenido y encarcelado. Comparte la celda con el príncipe Ahmad, legítimo heredero del trono de Bagdad, a quien el Gran Visir Jaffar ha encarcelado para arrebatarle el poder.', '/mBefG2BlUkqbCkYgWcJOC9dvkvE.jpg', '/cuMvdjZVYKeCLBtWFc2FDiNAsUR.jpg', 7.3, 'msVH7dZkB8o', array['1001']::text[], 50, null, 'segura', null),
(50182, 'movie', 'La rueda', 'La rueda', 'La Roue', 1923, 'Abel Gance', 'La película se abre con un espectacular choque de trenes montado a partir de cortes muy rápidos, tan revolucionario en su tiempo como la llegada del tren a la estación filmada por Lumière en 1895. El ferroviario Sisif salva a Norma del choque y la educa como si fuera hija suya. Pero tanto él como su hijo Elie se enamoran de ella. Entonces Sisif decide casarla con un hombre rico, pero ella está enamorada de Elie. Son claras las referencias a la tragedia griega (Sisif es Sísifo y acabará ciego a causa del deseo incestuoso). La metáfora central de la película es la rueda: la rueda del destino, la rueda del deseo y la rueda de la misma película... (FILMAFFINITY)', '/5qk2x7UTxQaVQcCWrSE0PiKlydU.jpg', '/tJfcI6A2sSfbSjxscDWFUOHJcRD.jpg', 7.3, 'KP4AoOJ6b1o', array['1001']::text[], 50, null, 'segura', null),
(44967, 'movie', 'La huelga', 'La huelga', 'Стачка', 1925, 'Сергей Эйзенштейн', 'Rusia zarista. Los obreros de una importante empresa están descontentos y, después de una reunión, deciden ir a la huelga. El director de la empresa informa de la situación a los responsables políticos y éstos envían a la policía para abortar la huelga. La tensión se dispara cuando un obrero se suicida al ser acusado injustamente de un robo.', '/qsULy0fRUwqvrX4JJhGrqKXpeNa.jpg', '/bMvuciIEQKzgz0Xt7cwm2oR3nVR.jpg', 7.4, '3UQMg3saU4Q', array['1001']::text[], 51, null, 'segura', null),
(1405, 'movie', 'Avaricia', 'Avaricia', 'Greed', 1924, 'Erich von Stroheim', 'Un supuesto dentista se casa con una mujer a la que le ha tocado la lotería. El frustrado novio de ésta le acusa de no tener licencia para ejercer como tal. A causa de ello, el matrimonio vive pobremente, pero la mujer ahorra compulsivamente. La avaricia y los celos conducirán a una tragedia. Existen dos versiones: la censurada, de dos horas y media, y la completa, de cuatro horas.', '/eur2vc2BGiOocBuBLVPXySO7lRh.jpg', '/zc5vjonSbXUUazuQSi0R2bUfWNP.jpg', 7.3, 'MGjSpPgJAoA', array['1001']::text[], 52, null, 'segura', null),
(992, 'movie', 'El moderno Sherlock Holmes', 'El moderno Sherlock Holmes', 'Sherlock Jr.', 1924, 'Buster Keaton', 'Película sobre el mundo del cine, Keaton es un proyeccionista que sueña con ser un detective cuando, milagrosamente, se encuentra dentro de la película que está proyectando. Allí intentará salvar a su amada de las garras del villano. Una de las más aclamadas cintas de cine mudo llena de gags visuales y con un portentoso Buster Keaton.', '/1G9r3rqtbFAQuyWKOZm4Y5J5s7Q.jpg', '/tSipsYTp565LkopntX1lZNLPYHP.jpg', 8.0, 'JSEK1NUPrGA', array['1001']::text[], 54, null, 'segura', null),
(5991, 'movie', 'El último', 'El último', 'Der letzte Mann', 1924, 'F. W. Murnau', 'Un portero de un lujoso hotel, es bruscamente degradado a mozo de los lavabos. Privado de su antiguo trabajo y del uniforme que le identifica, intenta ocultar su nueva condición, pero su vida se desintegra lentamente.', '/r23jNChGtptT7elVDbBaBH6TwsK.jpg', '/sTyt7e2PB5nfY02reL1iZUYPbly.jpg', 7.8, 'd7rPS1TQ67I', array['1001']::text[], 56, null, 'segura', null),
(32600, 'movie', 'Siete ocasiones', 'Siete ocasiones', 'Seven Chances', 1925, 'Buster Keaton', 'El agente de bolsa Jimmy Shannon está cercano a la bancarrota cuando un abogado le presenta el testamento de su abuelo legándole 7 millones de dólares. Pero para poder heredar ese dinero deberá casarse antes de las 7 de la tarde de su 27 cumpleaños... ¡Y eso es hoy!', '/fH9woIxzqVtyv6S711vSVlS12eA.jpg', '/jWID4Frsol1gIWK6tB4vrCcBxcd.jpg', 7.5, '4Qlq0y36iQQ', array['1001']::text[], 56, null, 'segura', null),
(964, 'movie', 'El fantasma de la ópera', 'El fantasma de la ópera', 'The Phantom of the Opera', 1925, 'Rupert Julian', 'En los sótanos de la Ópera de París vive oculto el misterioso Eric, el hombre de voz de ángel y rostro desfigurado de demonio, que acecha entre pared y pared a la hermosa soprano Christine Daeé, a la que desea catapultar hasta la cima de la fama; pero cuando se entera de que la cantante está prometida al apuesto vizconde Raoul, se vuelve loco de celos.', '/fJZyzUEO5bCigFdlPEK522AiBnc.jpg', '/6FSs7jMimg1PBYdhZtPNQhtKtEc.jpg', 7.1, 'HQzE6_6qYhk', array['1001']::text[], 57, null, 'segura', null),
(643, 'movie', 'El acorazado Potemkin', 'El acorazado Potemkin', 'Броненосец Потёмкин', 1925, 'Сергей Эйзенштейн', 'Basada en hechos reales ocurridos en 1905, narra como la tripulación del acorazado Príncipe Potemkin de Táurida se cansan del tratamiento vejatorio e injusto de los oficiales. El detonante de la situación es la carne podrida que éstos quieren que los marineros se coman. Con este motín comienza el reguero revolucionario por Odesa y toda Rusia.', '/olQ0vHFCK5TzRyNkkT2aJgG2gLz.jpg', '/3RH61Z7BP3f215936PJBEG2qQrT.jpg', 7.6, '19Jh9PVIRP4', array['1001']::text[], 58, null, 'segura', null),
(962, 'movie', 'La quimera del oro', 'La quimera del oro', 'The Gold Rush', 1925, 'Charlie Chaplin', 'Aventuras de un solitario buscador de oro en Alaska, donde se topa con varios personajes rudos, y se enamora de la hermosa Georgia, a la que trata de conquistar.', '/jU1KhFlRm7UTURXjW4vQNzQ4GQj.jpg', '/66h0ReXG6DVOKtdVCRwMduAia9P.jpg', 8.0, 'wXrGsMrDEzA', array['1001']::text[], 60, null, 'segura', null),
(3060, 'movie', 'El gran desfile', 'El gran desfile', 'The Big Parade', 1925, 'King Vidor', 'Jim es un niño rico que nunca ha trabajado. Cuando estalla la Primera Guerra Mundial, Jim, presionado por su novia, se alista junto a otros dos jóvenes, Bull y Slim. Cuando llegan a Francia se dan cuenta de que la guerra no es lo que esperaban. Película muda cuya estética la convertió enseguida en todo un clásico del séptimo arte.', '/vE71pA5O2v23E3CLrhOMPRsg8zH.jpg', '/xBpk9twRcwZzNPWk5VHj9OC2M5g.jpg', 7.6, 'P_-BvxzdOr4', array['1001']::text[], 61, null, 'segura', null),
(19, 'movie', 'Metrópolis', 'Metrópolis', 'Metropolis', 1927, 'Fritz Lang', 'En una megalópolis del año 2000, los obreros están condenados a vivir recluidos en un gueto subterráneo, donde se encuentra el corazón industrial de la ciudad. Sin embargo, incitados por un robot, se rebelan contra la clase dominante y amenazan con destruir la ciudad exterior. Freder (Gustav Frölich), el hijo del soberano de Metrópolis, y María, una muchacha de origen humilde, intentarán evitar la destrucción apelando a los sentimientos y al amor.', '/fCWd45ybxghuvaeSMcBsLFKY6PG.jpg', '/eeMoFKxjjiCi6iep2GEZtSAMYIr.jpg', 8.1, 'YEotzg8Q9DA', array['1001']::text[], 62, null, 'segura', null),
(631, 'movie', 'Amanecer', 'Amanecer', 'Sunrise: A Song of Two Humans', 1927, 'F. W. Murnau', 'Un granjero convive felizmente en el campo con su esposa. Pero la aparición de una seductora mujer de la ciudad hace que comience a enamorarse de ésta, y a pensar que su mujer es un estorbo que se interpone en la felicidad entre él y su nueva y sofisticada amante.', '/djFel2Tq4LhlDARtNTU6nRHA2mE.jpg', '/hKrrCigPFmhv1bg5IJl9nzjEaN4.jpg', 7.8, 'PCgbFay53BA', array['1001']::text[], 64, null, 'segura', null),
(961, 'movie', 'El maquinista de la General', 'El maquinista de La General', 'The General', 1926, 'Clyde Bruckman, Buster Keaton', 'A pesar de querer alistarse, durante la Guerra de Secesión Johnny Gray (Buster Keaton) es destinado a la retaguardia. Todo cambia cuando un comando enemigo le roba las dos cosas que más ama: Anabelle Lee y "La General", una locomotora.', '/9jcJ6loloQiifZssTtUDkK7j7dG.jpg', '/mzox4HbcV9W42MH2dB1QsdDVGo3.jpg', 7.9, 'eEVWb9NcSuY', array['1001']::text[], 66, null, 'segura', null),
(27503, 'movie', 'Garras humanas', 'Garras humanas', 'The Unknown', 1927, 'Tod Browning', 'Alonzo es una de las atracciones del circo gitano de Zanzi. Aunque es manco, arroja hábilmente con los pies cuchillos contra Nanon, la bella hija de Zanzi. A la joven no le gusta que los hombres la manoseen, en especial Malabar, el hombre forzudo. Por eso se siente muy a gusto con Alonzo, pero éste no es quien dice ser.', '/v0LzQs4ijKWrzUhOmvjfutJWAyc.jpg', '/5T4hHFzhv5BiwyBjuIoWZM6t20A.jpg', 7.5, '0ZPxz_gwOvk', array['1001']::text[], 67, null, 'segura', null),
(697, 'movie', 'Octubre', 'Octubre', 'Октябрь', 1928, 'Сергей Эйзенштейн, Григорий Александров', 'Reconstrucción de los acontecimientos ocurridos desde Febrero hasta Octubre de 1917. Una película en la que, siguiendo la filosofía comunista, no había personajes principales. La habilidad de Eisenstein y su experiencia se ve en los rápidos movimientos y en el ritmo en el montaje, así como en la construcción de intensas secuencias que no fueron bien entendidas por las tempranas generaciones rusas. El estreno se retrasó hasta 1928 debido a la presión de algunos grupos influyentes y, además, se cortaron algunas escenas. Aparecen en el filme muchos de los protagonistas de la revolución: los Guardias Rojos, los soldados y los marineros.', '/2sNZPybGgux2keFKxZuKuedrS3d.jpg', '/lcFVMnRPEVpvRDpXlxGfpuz0ik3.jpg', 6.9, 'tqwLwEhUtrE', array['1001']::text[], 68, null, 'segura', null),
(939, 'movie', 'El cantor de jazz', 'El cantor de Jazz', 'The Jazz Singer', 1927, 'Alan Crosland', 'Primer film sonoro. La Warner Bros. Pictures, que por entonces pasaba problemas financieros, fue el primer estudio en sacar un filme sonoro, que alternaba la voz y canciones de Al Jolson con subtítulos. Por supuesto, e independientemente de la calidad artística del filme, se convirtió en un gran éxito de taquilla.', '/zYxe070bHAihohoZlV2uHDJCHqD.jpg', '/515FMUnY7irFM0zsMKPvclMUUnJ.jpg', 6.1, 'YP00IQ60ZP0', array['1001']::text[], 70, null, 'segura', null),
(883726, 'movie', 'El hermano pequeño', 'El hermano pequeño', 'El hermano pequeño', 1999, 'Enrique Urbizu', 'Leo Minués, who used to be a classmate of Carvalho, is found dead the same day he had to testify in a case of corruption and someone asks Carvalho to investigate it. He accepts the case and finds out that Leo was collecting illegal funds for his political party. From that moment, a number of signs appear. This allows Carvalho to discover that Mínguez had made a list of the people involved in the case of corruption. Some videotapes appear, which makes things even more complicated, and Carvalho finds himself walking on shifting land, surrounded by celebrities in the highest spheres. Why did Mínguez die? Who has got the list?', '/tWkDBfnqhrv7yEufDWc4NPKQDiz.jpg', null, 8.0, null, array['1001']::text[], 71, null, 'dudosa', '[{"tmdb_id": 883726, "titulo": "El hermano pequeño", "original": "El hermano pequeño", "anio": 1999, "votos": 1, "poster_path": "/tWkDBfnqhrv7yEufDWc4NPKQDiz.jpg", "sim": 1.0}, {"tmdb_id": 926889, "titulo": "Mi hermano pequeño", "original": "Un petit frère", "anio": 2022, "votos": 27, "poster_path": "/tYHJSqNDtQUqP7IPhsALXaZ3jzG.jpg", "sim": 0.909}, {"tmdb_id": 236279, "titulo": "Little Brother Rat", "original": "Little Brother Rat", "anio": 1939, "votos": 9, "poster_path": "/9FTgK5mxWIDiiDM7dzVDp3tDNFK.jpg", "sim": 0.242}]'::jsonb),
(42536, 'movie', 'Napoleón', 'Napoleón', 'Napoléon', 1927, 'Abel Gance', 'El golpe de estado del 18 Brumario de 1799, que significó el fin de la Revolución Francesa, puso el poder en manos de Bonaparte, el más prestigioso de los generales franceses, sobre todo después de sus brillantes campañas en Italia y en Egipto. Desde 1799, Napoleón no sólo fomentó la difusión de las ideas revolucionarias, sino que, además, se lanzó a la conquista de Europa. En 1804 se autoproclamó emperador de Francia con el nombre de Napoleón I.', '/xBH75ETXlS61z6PgwtlMt2p8sYC.jpg', '/z9G36L2LuvtXWKiXq9hyHHEZMB6.jpg', 7.9, '6504eRh5h6M', array['1001']::text[], 71, null, 'segura', null),
(3061, 'movie', 'Y el mundo marcha', 'Y el mundo marcha', 'The Crowd', 1928, 'King Vidor', 'Un joven solitario impulsado por la ambición y el idealismo se enfrenta a la vida en el Nueva York de principios del siglo XX. Las duras condiciones que impone esta realidad desmitifican el mítico sueño americano.', '/dIWFeE6cvVHXxHTGip6lrRDFo5M.jpg', '/gU6ZJQbMLOKPURvkmh3vNOuW5Ew.jpg', 7.6, 'WyMwGPyZ5t0', array['1001']::text[], 72, null, 'segura', null),
(885, 'movie', 'Los muelles de Nueva York', 'Los muelles de Nueva York', 'The Docks of New York', 1928, 'Josef von Sternberg', 'Toda la historia transcurre en menos de un día, y en sólo tres escenarios: un bar del puerto, una pensión y los muelles de la ciudad de Nueva York. Bill Connolly es fogonero en un barco, y tiene una única noche libre en tierra. Mientras camina por los muelles, una muchacha se arroja al agua. Bill la rescata, y poco a poco ambos se sienten atraídos el uno hacia el otro. (FILMAFFINITY)', '/rCMZpfPAHeuy02nMCttEX3OJt4B.jpg', '/uLgeOKqBF7PIn9Dz3oa5TSY8k3s.jpg', 7.0, 'UAQjUBB6p10', array['1001']::text[], 73, null, 'segura', null),
(626, 'movie', 'Un perro andaluz', 'Un perro andaluz', 'Un chien andalou', 1929, 'Luis Buñuel', 'Un perro andaluz es un clásico del cine de vanguardia subrealista, resultado de la cooperación entre el director Luis Buñuel y Salvador Dalí. La película cambió la forma en que se rodaban las películas.. La escena más famosa es la de un hombre al que le están cortando el ojo con un cuchillo.', '/nlgxiSXyIq08XHWuGwxYnpLSKgP.jpg', '/jQywhaFDVLPlFw864Bgw5eNtWfi.jpg', 7.4, 'BVbTEVfLksU', array['1001']::text[], 74, null, 'segura', null),
(780, 'movie', 'La pasión de Juana de Arco', 'La pasión de Juana de Arco', 'La Passion de Jeanne d''Arc', 1928, 'Carl Theodor Dreyer', 'Guerra de los Cien Años (siglos XIV y XV). En 1431, Juana de Arco, después de haber conducido a las tropas francesas a la victoria, es arrestada y acusada de brujería. Ella declara haber recibido de Dios la misión de salvar a Francia, pero es procesada y condenada a morir en la hoguera.', '/yhuXslS2FumUzpsd7qNxQEMDsnC.jpg', '/uyYwhxRnXGuGWoCxiAdINlRExud.jpg', 8.0, 'Iz3XmfNzrNs', array['1001']::text[], 75, null, 'segura', null),
(25768, 'movie', 'El héroe del río', 'El héroe del río', 'Steamboat Bill, Jr.', 1928, 'Charles Reisner, Buster Keaton', 'Los propietarios de dos barcos fluviales compiten por el control del transporte de mercancías por el río Mississippi. Bill, uno de ellos, espera la llegada de su hijo Willie (Buster Keaton), que ha estado estudiando en la ciudad, para que le ayude en el negocio. Pero Willie se ha convertido en un petimetre inexperto y, además, se enamora de la hija del rival de su padre, lo que agudiza las tensiones entre los dos propietarios.', '/zygJMsmXxeyDc1N67OCZc8xtq4I.jpg', '/kmZjw9hbo8ErovofQvPB21HRyRf.jpg', 7.6, '4a9VXNW0jjE', array['1001']::text[], 76, null, 'segura', null),
(84273, 'movie', 'Tempestad sobre Asia', 'Tempestad en Asia', 'Потомок Чингисхана', 1928, 'Всеволод Пудовкин', 'Ambientado en Siberia y el Tibet durante la ocupación inglesa de esas tierras, Tormenta Sobre Asia cuenta la historia de un cazador local que es confundido con un descendiente del legendario Genghis Khan. Entonces los invasores deciden usarlo como títere político, sin saber que el cazador tiene sus propias ideas al respecto.', '/eCFQjZtAC1GLmhbQ2zO5OeQNzAA.jpg', '/lblZfPwOR8kRltqVvELTcVZ8Qwq.jpg', 6.5, null, array['1001']::text[], 76, null, 'segura', null),
(543, 'movie', 'La muchacha de Londres', 'Chantaje', 'Blackmail', 1929, 'Alfred Hitchcock', 'Londres, 1929. Frank Webber, un detective de Scotland Yard muy ocupado, parece estar más interesado en su trabajo que en Alice White, su novia. Sintiéndose ignorada, Alice acepta salir con un elegante artista de educadas maneras que la invita a visitar su lujoso apartamento.', '/c36SLyefz8CwsnU5yANJqwUNWU3.jpg', '/3fWwpoAVj3mhgQxTnv2O0F1ElAM.jpg', 6.5, 'w1kWUWNPJa8', array['1001']::text[], 77, null, 'probable', '[{"tmdb_id": 543, "titulo": "Chantaje", "original": "Blackmail", "anio": 1929, "votos": 295, "poster_path": "/c36SLyefz8CwsnU5yANJqwUNWU3.jpg", "sim": 0.37}]'::jsonb),
(26317, 'movie', 'El hombre de la cámara', 'El hombre de la cámara', 'Человек с киноаппаратом', 1929, 'Дзига Вертов', 'Un cámara deambula con una cámara colgada del hombro, documentando la vida urbana con una deslumbrante inventiva.', '/t54yc1AU8KszWGPnEv3rHDTIYcH.jpg', '/xPuGtHPc1aADsfXds87noXVz2Hh.jpg', 7.9, 'BtTlgxtoqhg', array['1001']::text[], 78, null, 'segura', null),
(905, 'movie', 'La caja de Pandora', 'La caja de Pandora (Lulú)', 'Die Büchse der Pandora', 1929, 'G.W. Pabst', 'Lulú (Louise Brooks) es mujer ambiciosa y sin moral que usa a los hombres a su voluntad. Desinhibida y atractiva, el aprovechamiento de sus encantos conllevará también sus peligros. Obra mayor del expresionismo que encumbró a Louise Brooks, una joya del cine mudo que adaptó magistralmente la obra teatral "Lulu" de Wedeking.', '/pPUr6mtHlOVlgQjg2xeJgZZEgn2.jpg', '/y3WwIEEDcbT88MxjCjM8mlBEF04.jpg', 7.5, 'A1kZaoHqEuU', array['1001']::text[], 80, null, 'segura', null),
(228, 'movie', 'El ángel azul', 'El ángel azul', 'Der blaue Engel', 1930, 'Josef von Sternberg', 'Adaptación cinematográfica de la novela "Profesor Unrath" de Heinrich Mann. Narra la tragedia de un severo profesor que una noche va a "El Ángel Azul", un cabaret de mala fama, para llevarse de allí a sus alumnos, que acuden al local seducidos por los encantos de la cantante Lola-Lola (Dietrich). Sin embargo, el profesor Rath, un solterón de 50 años, acaba cayendo en las redes de la cabaretera. A partir de entonces, su vida será un descenso a los infiernos de la humillación y de la degradación moral.', '/e1V8tvvE5ZUzxZc4JBXudnonKsB.jpg', '/jLvlD6ABDESFfYl3F1TqCoiBaig.jpg', 7.3, 'Lw6GJiGNO74', array['1001']::text[], 82, null, 'segura', null),
(5729, 'movie', 'La edad de oro', 'La edad de Oro', 'L''Âge d''or', 1930, 'Luis Buñuel', 'Después de un prólogo documental sobre las costumbres del alacrán, unos bandidos descubren a un grupo de arzobispos orando en un acantilado. La fundación de la Imperial Roma, celebrada en el sitio donde oraban los clérigos, se ve interrumpida por los lances amorosos de una pareja que es separada. El hombre es conducido a prisión pero logra escapar y se refugia en casa de su amada. Durante una fiesta, la pareja intenta consumar su pasión sin éxito. Finalmente, los sobrevivientes de una criminal orgía, entre los que se encuentra el duque de Blangis, salen del castillo de Selliny. (FILMAFFINITY)', '/eh8DUhYeXjGXMLnBQDkl2qPNmod.jpg', '/9sm4hWWjbLVVRhsokPaa1toqHe7.jpg', 6.8, 'Q14oKtsd-Zw', array['1001']::text[], 84, null, 'segura', null),
(46594, 'movie', 'La tierra', 'Tierra', 'Земля', 1930, 'Олександр Довженко', 'Un viejo campesino ucraniano se dispone a morir sobre la tierra en la que ha trabajado toda su vida. Su nieto, Vasil, decide entonces que el consejo de la villa debe comprar un tractor para compartirlo entre los granjeros, que unidos vencerán a las dificultades de la naturaleza y a la opresión de los ricos terratenientes. (FILMAFFINITY)', '/aJAcgn5h7AGHcSX7iByc84gF5kp.jpg', '/5EHNInARZmBhOnwl3kiDfhCYTvC.jpg', 6.7, '8wXzFIDMLT0', array['1001']::text[], 86, null, 'segura', null),
(27899, 'movie', 'Hampa dorada', 'Hampa dorada', 'Little Caesar', 1931, 'Mervyn LeRoy', 'La carrera criminal de Little Caesar, alias ''Rico'', empezó con pequeños robos y terminó con el título de jefe de una banda de peligrosos mafiosos. Rico mueve a un grupo de mafiosos criminales del campo a la gran ciudad y se une a la pandilla de Sam Vettori con su amigo Joe Massara, después se convierte en el líder y se acerca a Pete Montana. Sin embargo, cuando ha alcanzado la más alta cima una traición le hará caer.', '/9OV4TuQl8LH8uxNKDAJ8j2WsHKF.jpg', '/fG5sKoSaTiySmGaqFjNcGXo4Gtt.jpg', 6.9, 'pAM2UDuQIjw', array['1001']::text[], 88, null, 'segura', null),
(143, 'movie', 'Sin novedad en el frente', 'Sin novedad en el frente', 'All Quiet on the Western Front', 1930, 'Lewis Milestone', 'Mítica película antibélica que plasma los sentimientos, sensaciones y desilusiones de un grupo de jóvenes estudiantes que son enviados al frente en la Primera Guerra Mundial (1914-1918). Es una adaptación de la novela homónima del escritor alemán Erich María Remarque. Su estreno provocó enfrentamientos entre nazis y comunistas.', '/whhnoAEoobX7dasproRpBipHXJT.jpg', '/yeQGyB8MjpX8KR7rUrP0E3gaviC.jpg', 7.8, 'Qeh3DlBEjAc', array['1001']::text[], 89, null, 'segura', null),
(31514, 'movie', 'Viva la libertad', 'Viva la libertad', 'À nous la liberté', 1931, 'René Clair', 'Dos presidiarios deciden llevar a la práctica un plan para fugarse. Pero, cuando están a punto de alcanzar la libertad, son descubiertos. Uno de ellos decide sacrificarse por el otro, que llegará a convertirse en un gran empresario.', '/tusBGAoOWr5ujBHawTW1Dhp3yxD.jpg', '/naHXHsdkizGec3ndo3kwcwamLos.jpg', 7.0, '6PZkEo6xnGc', array['1001']::text[], 89, null, 'segura', null),
(32317, 'movie', 'El millón', 'El millón', 'Le Million', 1931, 'René Clair', 'Michel, un artista parisino, está siendo acosado por numerosos acreedores impacientes por recuperar su dinero. Para empeorar las cosas, cuando está abrazando a la mujer cuyo retrato está pintando, es sorprendido por su novia Béatrice. De repente, Michel se entera de que tiene el boleto ganador de la lotería holandesa. Pero cuando se va a recuperar el billete del bolsillo de su chaqueta, se encuentra con que Báatrice ha dado la chaqueta a un desconocido que estaba necesitado. Ahora todo el mundo tiene un gran interés en la búsqueda de esa chaqueta. (FILMAFFINITY)', '/aDHQndUlJHdbZylY2vjs5XygxSP.jpg', '/130w48OEfsipXXvBfVo6J8KTcFm.jpg', 6.8, null, array['1001']::text[], 90, null, 'segura', null),
(977, 'movie', 'Tabú', 'Tabú', 'Tabu: A Story of the South Seas', 1931, 'F. W. Murnau', 'Última película de Murnau, que empezó como una colaboración para escribir y dirigir conjuntamente con el famoso documentalista Robert J. Flaherty, aunque por diversos problemas sólo la firmó Murnau. Rodada en Tahití y Bora-Bora retrata en forma casi de documental, al igual que "Nanook of the North" hacía con los esquimales, las costumbres y modo de vida de la gente del pacífico sur.', '/2z881OOYbgpOEO1H7qpsRn0DDqn.jpg', '/jLtiBuYhQoqAEACLyyhO3mo4JHx.jpg', 7.1, 'BmHQjE_YCGw', array['1001']::text[], 91, null, 'segura', null),
(138, 'movie', 'Drácula (1931)', 'Drácula', 'Dracula', 1931, 'Tod Browning', 'El conde Drácula abandona los Cárpatos y se traslada a Londres, llevándose como sirviente a un contable. Una vez instalado, se enamora de una joven que ya está prometida. Empieza a a visitarla por las noches y va bebiendo su sangre poco a poco para convertirla así en su esposa. Pero el malestar que sufre la joven alerta a su familia, que busca la ayuda del doctor Van Helsing.', '/zf7eGmr4l9whGIKzEpLvaoNtn9I.jpg', '/cemjdP7HrUyJAry85vRT19Hidbi.jpg', 7.2, 'M5zL-jCgvUA', array['1001']::text[], 92, null, 'probable', '[{"tmdb_id": 138, "titulo": "Drácula", "original": "Dracula", "anio": 1931, "votos": 1438, "poster_path": "/zf7eGmr4l9whGIKzEpLvaoNtn9I.jpg", "sim": 1.0}, {"tmdb_id": 39259, "titulo": "Drácula", "original": "Drácula", "anio": 1931, "votos": 144, "poster_path": "/goLWA36jUdpxhFOMMbYyt3Zh0ii.jpg", "sim": 1.0}, {"tmdb_id": 438498, "titulo": "Opening Night", "original": "Opening Night", "anio": 1931, "votos": 4, "poster_path": null, "sim": 0.0}, {"tmdb_id": 342085, "titulo": "Hot News Margie", "original": "Hot News Margie", "anio": 1931, "votos": 3, "poster_path": "/ohJmomuPTB98lGIv0HbmHejZxdy.jpg", "sim": 0.0}]'::jsonb),
(3035, 'movie', 'Frankenstein', 'El doctor Frankenstein', 'Frankenstein', 1931, 'James Whale', 'El doctor Henry Von Frankenstein acomete un experimento tenebroso: construir, a partir de fragmentos de cadáveres, un nuevo ser humano. Con la ayuda de su criado Fritz, se adentra durante la noche en los cementerios de la localidad para arrancar a los cadáveres las partes que necesita. Lo que ignora es que el cerebro que ha utilizado en su experimento había pertenecido a un criminal.', '/t0r1I6Qv2KCAcZHuygCQyQpUuTX.jpg', '/wFbPbJ9uRDpjY7micBTeolgkOA4.jpg', 7.5, 'EEH5MZCewPQ', array['1001']::text[], 94, null, 'segura', null),
(17687, 'movie', 'El enemigo público', 'El enemigo público', 'The Public Enemy', 1931, 'William A. Wellman', 'Relato del auge y caída de Tom (James Cagney), un criminal de poca monta que asciende rápidamente gracias a la Ley Seca. Con la colaboración de su mejor amigo y cómplice (Edward Woods) Tom, seducido por el poder y el dinero, se involucra en turbios negocios.', '/pGaUO2qCliCNZ20oEZfmarud5Bz.jpg', '/oXLaGV0VOqQhXdUmQpm6KGsSpu1.jpg', 7.3, 'ECEcNXe4x8w', array['1001']::text[], 95, null, 'segura', null),
(901, 'movie', 'Luces de la ciudad', 'Luces de la ciudad', 'City Lights', 1931, 'Charlie Chaplin', 'Un pobre vagabundo (Charles Chaplin) pasa mil y un avatares para conseguir dinero y ayudar a una pobre chica ciega (Virginia Cherill) de la que se ha enamorado.', '/15bnFY02iqWB6jN0sjxsxMNrmWS.jpg', '/Ma7mQsldFCaQpsZbm8zolgLfmV.jpg', 8.2, '7vl7F8S4cpQ', array['1001']::text[], 95, null, 'segura', null),
(832, 'movie', 'El vampiro de Düsseldorf', 'M, el vampiro de Düsseldorf', 'M - Eine Stadt sucht einen Mörder', 1931, 'Fritz Lang', 'Un asesino de niñas tiene atemorizada a toda la ciudad. La policía lo busca frenética y desesperadamente, deteniendo a cualquier persona mínimamente sospechosa. Por su parte, los jefes del hampa, furiosos por las redadas que están sufriendo por culpa del asesino, deciden buscarlo ellos mismos.', '/drwll2kXZpmRYBEtWMWZbHcFkJF.jpg', '/5Pk1rGAtyblh9Xaq72T7ARCQSDQ.jpg', 8.1, 'nsVproWjN6c', array['1001']::text[], 96, null, 'segura', null),
(26614, 'movie', 'La golfa', 'La golfa', 'La Chienne', 1931, 'Jean Renoir', 'Narra la desdichada vida del cajero de una empresa que se enamora de Lulú. Aunque su amor no es correspondido, él está dispuesto a hacer cualquier cosa por ella. En 1945, Fritz Lang se basó en la misma historia para hacer la película “Perversidad”.', '/8LrxwVefTxDnOf9jnG6e29V6jMq.jpg', '/hiaZPun8bezhRcY8rFJEtRE8PG.jpg', 7.3, null, array['1001']::text[], 98, null, 'segura', null),
(779, 'movie', 'La bruja vampiro', 'La bruja vampiro', 'Vampyr - Der Traum des Allan Grey', 1932, 'Carl Theodor Dreyer', 'Un errante obsesionado con lo sobrenatural llega hasta una posada en la que una adolescente débil y muy enferma se está transformando lentamente en un vampiro.', '/rzLsS8d1PJQhb0Ni9RjTaqyQ0ca.jpg', '/rg3hBiQbDet8uNQkgfbpk7306p8.jpg', 7.2, 'acZJwgwmk4w', array['1001']::text[], 99, null, 'segura', null),
(31532, 'movie', 'Ámame esta noche', 'Ámame esta noche', 'Love Me Tonight', 1932, 'Rouben Mamoulian', 'Encantador y romántico musical que marcó el paso de muchos de los posteriores. Un sastre de París y una princesa se enamoran en esta obra maestra con el gran Maurice Chevalier.', '/yl1L77wB6g3Ke81KlbBF1IebxPd.jpg', '/tl1m11MJhHfSJHg9m5CCIlJvkNj.jpg', 6.6, 'go_hj2t_zAY', array['1001']::text[], 100, null, 'segura', null),
(48365, 'movie', 'Boudu salvado de las aguas', 'Boudu salvado de las aguas', 'Boudu sauvé des eaux', 1932, 'Jean Renoir', 'Boudu es un vagabundo que se tira al Sena con intención de suicidarse, pero un librero Parisiense, Edouard Lestingois le rescata y le acoge en su casa. Boudu es adoptado por la familia, que intenta convertirlo en un señor respetable.', '/mV3Pyvsf1S0l0u4UOiWMFlw5JFj.jpg', '/f2xs9gITz87n72jm6b04o6SZPqr.jpg', 6.9, 'etAwZ9ZILAQ', array['1001']::text[], 101, null, 'segura', null),
(29740, 'movie', 'Soy un fugitivo', 'Soy un fugitivo', 'I Am a Fugitive from a Chain Gang', 1932, 'Mervyn LeRoy', 'Retrato desolador de la injusticia y el sufrimiento humanos causados por el sistema penal de los Estados Unidos vigente tras la I Guerra Mundial.', '/5u0ojCGUJO1aRmhv3EmlcOlKJpO.jpg', '/nWLMIG4xY4MO2ESGoVfoVemu2a5.jpg', 7.8, '24R9vDcviKQ', array['1001']::text[], 101, null, 'segura', null),
(195, 'movie', 'Un ladrón en la alcoba', 'Un ladrón en la alcoba', 'Trouble in Paradise', 1932, 'Ernst Lubitsch', 'Lily (Miriam Hopkins), una carterista que se hace pasar por condesa, conoce en Venecia al famoso ladrón Gaston Monescu (Herbert Marshall), quien a su vez se hace pasar por barón, y se enamoran. Gaston roba al aristócrata François Fileba y huye con Lily antes de que le descubran. Casi un año después, en París, Gaston roba un bolso con diamantes incrustados a la viuda Mariette Colet, pero se lo devuelve y la cautiva de tal forma que lo contrata como secretario.', '/FBxuoLRD3Biyul14unT5m3PYNS.jpg', '/8xFIubJoxyidKaGjO1dc0btC9e7.jpg', 7.4, 'Rf5o1eUORos', array['1001']::text[], 102, null, 'segura', null),
(877, 'movie', 'Scarface, el terror del hampa', 'Scarface, el terror del Hampa', 'Scarface', 1932, 'Howard Hawks', 'Tony Camonte (Paul Muni), un pistolero de origen italiano, ignorante y sin escrúpulos, es el lugarteniente de Johnny Lovo (Osgood Perkins), el hampón más poderoso del South End de Chicago. Ambicioso y cruel, Camonte, que por una cicatriz que le cruza el rostro recibe el apelativo de Cara cortada, elimina poco a poco a los rivales de su jefe hasta que, con la ayuda de su amigo Gino Rinaldo (George Raft), le arrebata el poder también a él y se convierte en el amo de la ciudad. Tras un mes de vacaciones en Florida, descubre que su hermana Cesca (Ann Dvorak), por la que siente un amor confuso y arrebatado, es la amante de Gino.', '/5LhpEbHsJEF63FS5vdwcaRmQlVv.jpg', '/bIv1kaxb7tsiZYPO27PHfVb5eSF.jpg', 7.4, 'XRmWftEjit0', array['1001']::text[], 104, null, 'segura', null),
(875, 'movie', 'El expreso de Shangai', 'El expreso de Shanghai', 'Shanghai Express', 1932, 'Josef von Sternberg', 'Lily se encuentra en el tren de Shanghai con su antiguo amor, el capitán Harvey. Durante el largo trayecto, rodeados de un grupo de personajes muy variopinto y lleno de vicisitudes, incluyendo el asalto al tren por un grupo de rebeldes, se darán cuenta de que nunca habían dejado de amarse.', '/xXBSLdkAvqMp9JfZpJx1W4tobJz.jpg', '/yGBAQcQVauUGNWGgWHxG4ihNCOp.jpg', 7.0, 'i86Hc6AAVt4', array['1001']::text[], 105, null, 'probable', null),
(136, 'movie', 'La parada de los monstruos', 'La parada de los monstruos', 'Freaks', 1932, 'Tod Browning', 'En un circo lleno de seres deformes, tullidos y personas con diversas amputaciones, Hans, uno de los enanos, hereda una fortuna. A partir de ese momento, Cleopatra, una bella contorsionista, intentará seducirlo para hacerse con su dinero. Para lograr su objetivo, traza un plan contando con la complicidad de Hércules, el forzudo del circo...', '/2FfobmyEH4rLACOeAqA8L7VJGEC.jpg', '/r18vpGFsNf6n984x4KdJmAAWKkP.jpg', 7.8, 'GjzvvYX8hmk', array['1001']::text[], 106, null, 'segura', null),
(84337, 'movie', 'Mi chica y yo', 'Mi chica y yo', 'Me and My Gal', 1932, 'Raoul Walsh', 'Un policía y una camarera se enamoran; el único problema es que él tendrá que ayudar y proteger a la hermana de su novia, que está liada con un gángster.', '/pAPxl1vECf3hmyX1W4juWd2Fzil.jpg', '/iYROnjvGVliseRF4TKMvkZP2mdL.jpg', 6.4, null, array['1001']::text[], 107, null, 'segura', null),
(44494, 'movie', 'Zéro de conduite', 'Cero en conducta', 'Zéro de conduite : Jeunes diables au collège', 1933, 'Jean Vigo', 'Obra maestra donde Jean Vigo (muerto a los 29 años con tan sólo cuatro películas en su haber) retrata sus recuerdos infantiles a través de la historia de cuatro jóvenes estudiantes franceses que, sujetos a un estricto régimen escolar, deciden rebelarse contra la institución. Filme prohibido en Francia en su estreno por su presunto mensaje antipatriótico.', '/roGO5tIIHcgzpjc96o0wk0VvzQb.jpg', '/9pB6CO85B6vwwgZtBKkvyISd3Lq.jpg', 6.9, null, array['1001']::text[], 107, null, 'segura', null),
(3062, 'movie', 'La Calle 42', 'La calle 42', '42nd Street', 1933, 'Lloyd Bacon', 'Julian Marsh, un exitoso productor de Broadway, a pesar de su delicada salud, produce un nuevo espectáculo, financiado por un hombre rico que está enamorado de la actriz principal, Dorothy Brock , aunque ella no le corresponde. Cuando la víspera del estreno Dorothy se lesiona, es sustituida por una chica del coro.', '/q4UEd8BL74zVsOOaJkKVMLMmdTg.jpg', '/5a5lJCew2hGBcd6abdMkomr9mos.jpg', 7.0, 'f2OaJv0NBB8', array['1001']::text[], 108, null, 'segura', null),
(28432, 'movie', 'Desfile de candilejas', 'Desfile de candilejas', 'Footlight Parade', 1933, 'Lloyd Bacon', 'Chester Kent está agotado y acorralado, se le han acabado las ideas y tiene solo unos días para preparar tres musicales para un productor de Hollywood. Para empeorar la situación tiene un espía que le entrega sus nuevas ideas a sus rivales. Su secretaria, Nan Prescott, está enamorada de él y junto con el resto de su leal equipo le ayudarán a salir adelante.', '/i0ZQHJG4U90N3WJKQRULQews2JS.jpg', '/a3cPv2bi7UEnK7PGqPIYhigtpm9.jpg', 6.8, 'EIv4A53jH6s', array['1001']::text[], 110, null, 'segura', null),
(31511, 'movie', 'Vampiresas', 'Vampiresas 1933', 'Gold Diggers of 1933', 1933, 'Mervyn LeRoy', 'En plena época de la Gran Depresión, Dick Powell es un compositor de canciones que se rebela contra sus adinerados padres para poder casarse con la corista Ruby Keeler. Musical de la Warner con espectaculares coreografías de Busby Berkeley. Obtuvo excelentes críticas.', '/yRkSKnMFqGLAb2x364ONE0vaNGj.jpg', '/oK4zUOQdGF0qIa05urUfCGaFzrK.jpg', 7.2, 'n7LcBOOqgZo', array['1001']::text[], 110, null, 'segura', null),
(43595, 'movie', 'Lady Lou', 'Lady Lou', 'She Done Him Wrong', 1933, 'Lowell Sherman', 'Lady Lou es una mujer a finales del siglo XIX que se ha hecho a sí misma. Un día conoce a un apuesto joven, pero aunque enamorada, no está dispuesta a dejarse intimidar y decide llevar la voz cantante.', '/m1p8uAD4VXXLYqktFkRryT4Lz5z.jpg', '/mzSpJ0ne8YiGLYd3UIssneTV9mJ.jpg', 5.9, '2XYOlrhiSkY', array['1001']::text[], 111, null, 'segura', null),
(3063, 'movie', 'Sopa de ganso', 'Sopa de ganso', 'Duck Soup', 1933, 'Leo McCarey', 'Un imaginario país en bancarrota requiere el apoyo económico de una acaudalada viuda (Margaret Dumont) para salir adelante. Como condición para extender el financiamiento, la acreedora exige que el excéntrico Rufus T. Firefly (Groucho Marx) tome las riendas de la nación. Deseando sacar partida de la crisis, el ambicioso embajador de una potencia vecina (Louis Calhern) hará cuanto sea posible para desprestigiar al nuevo líder y para ello echará mano de dos inusuales espías (Harpo y Chico Marx).', '/7LPGjvmMZkzaSey0KfOZ40ESzd2.jpg', '/nVpp3ZcIFtJJ3fJp65eJczehIN8.jpg', 7.3, 'MSMTkUYyKYU', array['1001']::text[], 112, null, 'segura', null),
(31526, 'movie', 'La reina Cristina de Suecia', 'La reina Cristina de Suecia', 'Queen Christina', 1934, 'Rouben Mamoulian', 'Suecia, siglo XVII. Durante la guerra de los Treinta Años (1618-1648) muere, en la batalla de Lutzen, el rey Gustavo Adolfo de Suecia. Hereda el trono su hija Cristina, que desde la infancia se entrega en cuerpo y alma a los problemas de estado, lo que la lleva a renunciar al matrimonio con el principe Carlos Gustavo, héroe nacional y el pretendiente preferido por todos. Sin embargo, Cristina se enamora profundamente de Don Antonio, Conde de Pimentel y embajador del rey de España en Suecia.', '/k3Axfospj5MutnI400Bb2sHz4oZ.jpg', '/e6YpCECKNPMBonp425jmHgd6D44.jpg', 6.9, 'icS3e2IFxBk', array['1001']::text[], 114, null, 'segura', null),
(91, 'movie', 'Las Hurdes (Tierra sin pan)', 'Las Hurdes (Tierra sin pan)', 'Las Hurdes', 1933, 'Luis Buñuel', 'Cortometraje documental que hace un retrato de Las Hurdes (Cáceres), una de las regiones más pobres y menos desarrolladas de la España de 1932. La insalubridad, la miseria y la falta de oportunidades provocan la emigración de los jóvenes y la soledad de quienes se quedan en esta desolada región extremeña.', '/y8Kw4K2pTooe96fobQTz0RJEq9o.jpg', '/aaRbO3m3L3yVg2L73QLYvgP23hj.jpg', 7.1, 'vfztwAybbzM', array['1001']::text[], 114, null, 'segura', null),
(244, 'movie', 'King Kong', 'King Kong', 'King Kong', 1933, 'Merian C. Cooper, Ernest B. Schoedsack', 'Un equipo de cine va a rodar una película a la misteriosa isla de Teschio, al este de Sumatra. Allí descubren la existencia de una civilización prehistórica y de una tribu ancestral que secuestra a la atractiva Ann, la actriz protagonista, para ofrecerla en sacrificio ritual a King, un gigantesco gorila.', '/wlRhyQOC67Q9dxqd2Fpsh64kFHh.jpg', '/lYfHa1AtkUMtplrKx7SRLHpwonW.jpg', 7.6, 'I8P7RzqOU_M', array['1001']::text[], 115, null, 'segura', null),
(43128, 'movie', 'Compañeros de juerga', 'Compañeros de juerga', 'Sons of the Desert', 1933, 'William A. Seiter', 'Stan y Ollie se comprometen a asistir a una convención de los “Hijos del Desierto” que coincide con un viaje a las montañas planeado por el matrimonio Hardy. Ollie simula una enfermedad que exige un viaje por mar. Mientras él y Stan disfrutan de la convención, el barco tropieza con una catástrofe.', '/3VcVf8RPKRAJp83NVlu7FUURoMY.jpg', '/aX476hnJ3qbDs6nwWgcUeBACGlL.jpg', 7.1, 'jXf_GgrLGAM', array['1001']::text[], 116, null, 'segura', null),
(34187, 'movie', 'La amargura del general Yen', 'La amargura del general Yen', 'The Bitter Tea of General Yen', 1933, 'Frank Capra', 'Shanghai, China, década de 1920. En medio de una sangrienta guerra civil, el general Yen, un despiadado señor de la guerra, rescata a Megan Davis —que estaba a punto de casarse con un misionero— de una muerte segura en medio del caos.', '/wP54GIcviOJgDpdrgnyM8zvXwRE.jpg', '/AjXjoawu5zLE9GiRWZ9fd20G9Aa.jpg', 6.3, null, array['1001']::text[], 116, null, 'segura', null),
(28001, 'movie', 'It''s a Gift', 'It''s a Gift', 'It''s a Gift', 1934, 'Norman Z. McLeod', 'After he inherits some money, Harold Bissonette ("pronounced bis-on-ay") decides to give up the grocery business, move to California and run an orange grove. Despite his family''s objections and the news that the land he bought is worthless, Bissonette packs up and drives out to California with his nagging wife Amelia and children.', '/3DlYiSh3S7A9GO15gUu7zg92bD0.jpg', '/1NIYYTBeSBiZFJXEl7R0dRsJEVD.jpg', 6.4, 'tlWmHy1knOc', array['1001']::text[], 117, null, 'segura', null),
(39266, 'movie', 'El triunfo de la voluntad', 'El triunfo de la voluntad', 'Triumph des Willens', 1935, 'Leni Riefenstahl', 'Alemania, año 1934. Adolf Hitler acababa de llegar al poder un año antes. En Nuremberg el partido nacionalsocialista celebra un triunfalista y patriótico congreso en el que se exaltan los valores raciales y patrios del pueblo ario alemán.', '/AoYPbqJcXgqxvJjMzuqFUAuONIR.jpg', '/x57PAMkSURMbNZUk25lecXkJEWu.jpg', 6.9, null, array['1001']::text[], 118, null, 'segura', null),
(43904, 'movie', 'L''Atalante', 'L''Atalante', 'L''Atalante', 1934, 'Jean Vigo', 'La joven esposa de un viejo marinero está harta de su monótona vida en la barcaza “L''Atalante”. Después de dejarse llevar por la artificiosa vida de la ciudad, dejando a su marido sumido en la desesperación, regresa con él amargamente decepcionada.', '/vpaY2ajGa7C7CC8gnsdZltJlVS.jpg', '/dFbCil5MUoRX2s4u2XcK7knJpT.jpg', 7.5, 'hq024oIC25I', array['1001']::text[], 120, null, 'segura', null),
(23024, 'movie', 'El juez Priest', 'El juez Priest', 'Judge Priest', 1934, 'John Ford', 'El juez William "Billy" Priest vive en una patriótica y muy confederada región sureña. Allí, viudo y muy dedicado a su trabajo, Priest se enfrentará al caso más difícil de su carrera. Mientras, también tendrá que ejercer de casamentero con su tímido sobrino.', '/zYRyprQjrJl7zLfXGTb41Gdp1Tf.jpg', '/2OhwfIKb0zvt5JGgmc24tATyE2J.jpg', 6.4, null, array['1001']::text[], 121, null, 'segura', null),
(24106, 'movie', 'Satanás', 'Satanás', 'The Black Cat', 1934, 'Edgar G. Ulmer', 'Una pareja en viaje de luna de miel, viajan en tren por las tierras de Budapest con destino a Wiesegrad, para después dirigirse a Gombos. Debido a un error de la ferroviaria, deben de aceptar hospedar en su vagón privado a un huésped, el doctor Vitus Werdegast, psiquiatra. Aunque a regañadientes, y para evitar que el intruso se quede en el pasillo toda la noche, aceptan. Una vez juntos, el doctor Vitus les dice que va a Wiesegrad a ver a un viejo amigo, pero por la expresión de su rostro no parece tener muy buenas intenciones. Durante el transcurso del viaje, la joven pareja se queda dormida, momento que aprovecha el doctor para acariciar la cabeza de la desposada. Pero el marido lo ha observado todo.', '/nn5MfgKnrp649elZ9xTOae8SdMB.jpg', '/ww1gZ8vVCjmtyO2zkhcsRB7v6Tf.jpg', 6.7, 'qpdP7zliaeA', array['1001']::text[], 121, null, 'segura', null),
(3078, 'movie', 'Sucedió una noche', 'Sucedió una noche', 'It Happened One Night', 1934, 'Frank Capra', 'Peter Warren, es un periodista desempleado que se topa con Ellie, la hija de un millonario que huyó del barco de Alexander Andrews, su padre, porque no acepta al hombre con el que ella se quiere casar. Peter ve la oportunidad de conseguir una buena historia, pero varios hechos acaban por crear un vínculo entre ellos.', '/yFpfjnVzKhUhw29OW3iF5d0ANN1.jpg', '/hmiC0MsI0PDd1TJXC62xyw0tX0s.jpg', 7.8, 'FUAxNS_31So', array['1001']::text[], 122, null, 'segura', null),
(3529, 'movie', 'La cena de los acusados', 'La cena de los acusados', 'The Thin Man', 1934, 'W.S. Van Dyke', 'Un conocido inventor neoyorquino es acusado de varios asesinatos. Cuando llegan a la ciudad un famoso detective y su mujer y se enteran del asunto, ella, movida por el espíritu de aventura, trata de convencer a su marido para que acepte el caso.', '/bSTwEucUoveVCm4lhpDCZNbKKYf.jpg', '/b1bMEMtuiHBX23tfQU5ybNpakVf.jpg', 7.5, 'F2vlPkv0tQU', array['1001']::text[], 124, null, 'segura', null),
(16905, 'movie', 'El capitán Blood', 'El capitán Blood', 'Captain Blood', 1935, 'Michael Curtiz', 'Inglaterra, siglo XVII. Bajo el reinado de Jacobo I, primer monarca de la dinastía de los Estuardo, son constantes los enfrentamientos entre la Corona y el Parlamento. El doctor Peter Blood, un hombre entregado por entero a sus pacientes, vive al margen de los problemas políticos. Pero su actitud cambia cuando, injustamente acusado de traición, es enviado como esclavo a las Indias Occidentales. Dotado de una gran habilidad y astucia, consigue escapar y se convierte en el temible pirata Capitán Blood.', '/vbwgiQATN1hW0jw5PGTTwNnEXxb.jpg', '/gVCUB5cYjZVzNyBS46Q6RXLfmSr.jpg', 7.3, '4HmoyQcoBd0', array['1001']::text[], 126, null, 'segura', null),
(12311, 'movie', 'Rebelión a bordo', 'La tragedia de la Bounty', 'Mutiny on the Bounty', 1935, 'Frank Lloyd', 'En 1789, en los Mares del Sur, la tripulación del buque británico Bounty decide rebelarse contra el tiránico y cruel capitán Bligh. El motín lo encabeza el primer oficial, que defiende los intereses de la tripulación y abandona al capitán en un bote.', '/AppEu29Ck2dF12FBSBjJmSGgBkg.jpg', '/OBvT7h7Vt6qKGXJBNLDFnRhJEW.jpg', 7.4, 'OcYAmV833D0', array['1001']::text[], 126, null, 'probable', '[{"tmdb_id": 12311, "titulo": "La tragedia de la Bounty", "original": "Mutiny on the Bounty", "anio": 1935, "votos": 414, "poster_path": "/AppEu29Ck2dF12FBSBjJmSGgBkg.jpg", "sim": 0.432}]'::jsonb),
(37719, 'movie', 'Una noche en la ópera', 'Una noche en la ópera', 'A Night at the Opera', 1935, 'Sam Wood', 'Los Hermanos Marx en la alta sociedad. A dos amantes que actúan en la ópera se les impide estar juntos porque no aceptan al hombre como tenor. Utilizando varios trucos típicos de los Hermanos Marx, logran que el tenor principal se ausente, y de esta manera el joven amante tendrá su oportunidad.', '/sHI2jFUFMrUOK0M277notbRSWty.jpg', '/d7YwLX0PnX8vsaaQq9bz93jczGw.jpg', 7.4, 'UY9C9MpoIn4', array['1001']::text[], 127, null, 'segura', null),
(60287, 'movie', 'Los 39 escalones', '39 escalones', 'The Thirty Nine Steps', 1978, 'Don Sharp', 'Es el año 1914 y Richard Hannay, ingeniero de minas que está visitando Gran Bretaña por un corto tiempo antes de regresar a Sudáfrica, se sorprende cuando uno de sus vecinos, el coronel Scudder, irrumpe en sus habitaciones una noche y le cuenta una historia de que el durmiente de Prusia Los agentes planean pre-comenzar la Primera Guerra Mundial asesinando a un ministro de Asuntos Exteriores visitante. Sin embargo, Scudder es asesinado y Hannay es incriminada por los "durmientes". Huyendo a Escocia, Hannay intenta limpiar su nombre y detener a los agentes con la ayuda de Alex Mackenzie, pero no solo es perseguido por el Jefe Supt Lomas por la muerte de Scudder, sino también por los agentes encabezados por Appleton que ha logrado esconderse un puesto de alta posición en el gobierno británico ...', '/nxOc0D4SAsJmTw5U34RQOdgZTzP.jpg', '/k9XrJkxjMxlYjNvMIIwjhqn0TQH.jpg', 6.7, 'v_E365Wh0HM', array['1001']::text[], 128, null, 'dudosa', '[{"tmdb_id": 60287, "titulo": "39 escalones", "original": "The Thirty Nine Steps", "anio": 1978, "votos": 46, "poster_path": "/nxOc0D4SAsJmTw5U34RQOdgZTzP.jpg", "sim": 1.0}, {"tmdb_id": 16877, "titulo": "Los 39 escalones", "original": "The 39 Steps", "anio": 2008, "votos": 28, "poster_path": "/8N537ufRENaGUEJR0JTrRoK93rR.jpg", "sim": 1.0}]'::jsonb),
(229, 'movie', 'La novia de Frankenstein', 'La novia de Frankenstein', 'Bride of Frankenstein', 1935, 'James Whale', 'Después de la huida del monstruo creado por el doctor Frankenstein, el siniestro Dr. Praetorius propone al científico la creación de una compañera para el monstruo.', '/7FZPVHG3Llotb1rUzHWouSzevYV.jpg', '/hrED8MSOn4xJP9Cpk7WomUcFKGI.jpg', 7.5, 'gJoE3AIHTjU', array['1001']::text[], 129, null, 'segura', null),
(3080, 'movie', 'Sombrero de copa', 'Sombrero de copa', 'Top Hat', 1935, 'Mark Sandrich', 'Jerry Travers, un astro de la comedia musical americana, llega a Londres y se instala en la habitación del productor de su obra, Horace Hardwick. El azar le hace conocer a la bella modelo Dale Tremont, que se aloja en la habitación de abajo. Ella le toma, erróneamente, por Hardwick y, al enterarse que está casado (en realidad, y aunque no lo sabe, con una amiga suya, Madge), le rechaza y viaja con su jefe, el modisto Alberto Beddini, a Venecia, donde, por despecho, se casará con él.', '/ljT8X75UuihrQJgxDRvQ5fRejz4.jpg', '/9riMLH4EOw6PZzeCDnPlIGSyiEu.jpg', 7.2, 'FZUwE1n5zsE', array['1001']::text[], 130, null, 'segura', null),
(43878, 'movie', 'Un día en el campo', 'Una partida de campo', 'Partie de campagne', 1946, 'Jean Renoir', 'Una familia pasa un domingo a orillas del Sena. Mientras los hombres duermen la siesta, unos jóvenes remeros invitan a la madre y a la hija a dar un paseo en barca; un paseo que se convertirá en algo más que una inocente excursión fluvial. Mediometraje de 40 minutos basado en un relato de Guy de Maupassant, en el que Renoir hace un homenaje a su padre, el pintor impresionista Pierre Auguste Renoir. Sus cuadros son mostrados en el film para suscitar una reflexión sobre las relaciones entre cine y pintura.', '/hxyp4j54g1C8hZLAZLSQcRH03Cz.jpg', '/pOyo0alLklzMIeOkdFpooqQPh13.jpg', 7.3, '8Yhr7ye4GXc', array['1001']::text[], 130, null, 'probable', null),
(3082, 'movie', 'Tiempos modernos', 'Tiempos modernos', 'Modern Times', 1936, 'Charles Chaplin', 'Charlot, obrero de una fábrica, enloquece con la cadena de montaje y sobrevive como puede a la crisis junto a una joven huérfana.', '/f3uOJseH4oPEo0Sq7WyQ6IwMG4l.jpg', '/kSlO1pHpwQfPQdgVPr7dJiJNtJ8.jpg', 8.3, 'NNznUyDmSFc', array['1001','clasicos']::text[], 131, null, 'segura', null),
(20325, 'movie', 'En alas de la danza', 'En alas de la danza', 'Swing Time', 1936, 'George Stevens', 'John "Lucky" Garnett (Fred Astaire) es un destacado bailarín que llega tarde a su boda con Margaret Watson (Betty Furness). El padre de esta le reta a que vuelva a pedir la mano de su hija cuando haya ganado la astronómica cantidad de 25.000 dólares. Para ello John se traslada a Nueva York, en compaía de su amigo Everett "Pop" Cardetti (Victor Moore), donde conoce a Penélope "Penny" Carroll (Ginger Rogers). La relación entre ambos se irá estrechando hasta el nivel de que acabarán enamorándose.', '/fBKbNvUSwy672gkw3a5piqVRZAp.jpg', '/berFcW4jty3bPar7SVPIyIcqru9.jpg', 6.8, 'TgimMImX-VE', array['1001']::text[], 132, null, 'segura', null),
(13562, 'movie', 'Al servicio de las damas', 'Al servicio de las damas', 'My Man Godfrey', 1936, 'Gregory La Cava', 'Una alocada chica de la alta sociedad, su hermana y sus ricos amigos se divierten con un extravagante juego de caza que consiste en recoger todo tipo de desechos. En un lugar del East River, zona azotada por la Gran Depresión, encuentran a Godfrey, un ingenioso y mordaz vagabundo. Este curioso personaje acompaña a las hermanas a una fiesta, donde pronuncia un discurso sobre el carácter inhumano del juego. Después acepta trabajar como mayordomo en la casa familiar. En realidad, Godfrey esconde un secreto sobre su pasado.', '/taZ7yc7FNjLaLKb9GVOaIMFLk8W.jpg', '/96cNUk1Uj8fQcmbOTnpBauUdqzC.jpg', 7.6, '6zkZd9GkxWc', array['1001']::text[], 133, null, 'segura', null),
(24807, 'movie', 'El secreto de vivir', 'El secreto de vivir', 'Mr. Deeds Goes to Town', 1936, 'Frank Capra', 'Un ingenuo joven de provincias (Gary Cooper) va a Nueva York para hacerse cargo de una herencia de veinte millones de dólares. Allí se enamora de una chica encantadora (Jean Arthur), sin saber que es la periodista que lo ridiculiza en sus artículos.', '/7mGcvgXyFn73xWGtnWeJdyIyC93.jpg', '/4HndddVOLbvifowXjNpdkkF8Q71.jpg', 7.5, 'eOu8pem4Huk', array['1001']::text[], 134, null, 'segura', null),
(43874, 'movie', 'Margarita Gautier', 'La dama de las camelias', 'Camille', 1936, 'George Cukor', 'La vida en Paris en 1847 es tan animada como el champagne y tan implacable como la siguiente mañana gris. En la guarida del juego y las veladas lujosas, hombres mezquinos ejercen su voluntad y las mujeres se convierten en cortesanas regocijándose de placer.', '/crd3B8ESUHhYYLZMnX8p86snOcs.jpg', '/ecHSq4vcOcSatl6kBzxpcEpaQQf.jpg', 7.0, 'wSshWjTKd6Y', array['1001']::text[], 135, null, 'probable', '[{"tmdb_id": 43874, "titulo": "La dama de las camelias", "original": "Camille", "anio": 1936, "votos": 160, "poster_path": "/crd3B8ESUHhYYLZMnX8p86snOcs.jpg", "sim": 0.27}]'::jsonb),
(12684, 'movie', 'Sabotaje', 'Sabotaje', 'Sabotage', 1936, 'Alfred Hitchcock', 'Karl Anton Verloc y su esposa poseen un pequeño cine en un tranquilo suburbio de Londres donde viven aparentemente felices. Pero la Sra. Verloc no sabe que su marido tiene un secreto que afectará a su relación y amenazará la vida de su hermano adolescente.', '/vp7WIWBvDPKMWYpYVPTXLxgAAkK.jpg', '/hdl5cBE9zx5vBKuJ3RUQW0o1yEf.jpg', 6.7, '178s548EjM4', array['1001']::text[], 135, null, 'segura', null),
(31507, 'movie', 'Desengaño', 'Desengaño', 'Dodsworth', 1936, 'William Wyler', 'Samuel Dodsworth es un magnate de la industria del automóvil, el típico hombre de negocios que empezando desde abajo ha llegado a la cima del éxito. Él y su esposa deciden pasar una segunda luna de miel en Europa, pero durante el viaje descubre que ella le es infiel, y su mundo empieza a tambalearse. En tal circunstancia, conoce a una mujer que le devuelve la fe en el amor y lo convence de que vale la pena vivir. Gracias a ella, pondrá todos los medios a su alcance para salvar su matrimonio, pero quizá sea demasiado tarde.', '/dBnvJIw0DAS9SO4u8USiLhcfJU6.jpg', '/aE9zfMnG4kGBf4SEyUZ5ehPsb6K.jpg', 7.1, 'zrMuDl7vaTI', array['1001']::text[], 136, null, 'segura', null),
(3596, 'movie', 'La vida futura', 'La vida futura', 'Things to Come', 1936, 'William Cameron Menzies', 'A mitad de los años treinta, la Segunda Guerra Mundial no ha estallado todavía, pero parece sentirse en el aire que se respira. Cuando llegue, acontecimiento inexorable para los futurólogos, supondrá una conmoción que dará origen a un futuro de desastres en el que se impondrá como única forma de gobierno la más feroz de las dictaduras', '/67fJfpsZctHlZiPbnQxg55F6jRC.jpg', '/wa6uAXC6ei0BwaDiShwLjbMCLfe.jpg', 6.4, 'wemRBFFbhKI', array['1001']::text[], 137, null, 'segura', null),
(16515, 'movie', 'Capitanes intrépidos', 'Capitanes intrépidos', 'Captains Courageous', 1937, 'Victor Fleming', 'Harvey, el hijo arrogante y malcriado de un padre poco cariñoso, cae por la borda de un barco de vapor transatlántico y es rescatado por un barco de pesca en el Gran Banco de Terranova. Harvey trata de convencerles para que lo lleven a tierra alardeando de su riqueza ante la tripulación, aunque nadie le toma en serio. El capitán le ofrece un trabajo mal pagado hasta que regresen a puerto. El duro trabajo como uno más de la tripulación convierte al joven en un hombre maduro y considerado.', '/rsXZmQjSZyZQgETa2AYYQEbBnj8.jpg', '/2eKw8s2m2MZv0fLrmavNDZUS4BE.jpg', 7.4, 'fP19-5_EULo', array['1001']::text[], 138, null, 'segura', null),
(65642, 'movie', 'Le roman d''un tricheur', 'Memorias de un tramposo', 'Le Roman d''un tricheur', 1936, 'Sacha Guitry', 'Comedia sobre las memorias de un hombre al que el destino obliga a ser un caradura. Su manera de ganarse la vida, las mujeres que se cruzan en su camino, siempre para torcérselo... (FILMAFFINITY)', '/nSJ5wRn1eoSGeGDwZHN2I6Rtfbn.jpg', '/m2FA2TCgTTgrH3tRAtoo3e8Yyq5.jpg', 7.5, null, array['1001']::text[], 138, null, 'segura', null),
(30992, 'movie', 'Canción de medianoche (Ye ban ge sheng)', 'Canción de medianoche', '夜半歌声', 1937, '馬徐維邦', 'En esta versión china de El fantasma de la ópera, el misterioso Song Danping aterroriza al recién reconstruido teatro de la ópera y a su joven estrella.', '/apt39HzH02jZnEPL4Zekw311aU2.jpg', '/u93FqFmVwCFT8tEHgSZBO7htdQv.jpg', 6.0, null, array['1001']::text[], 139, null, 'segura', null),
(777, 'movie', 'La gran ilusión', 'La gran ilusión', 'La Grande Illusion', 1937, 'Jean Renoir', 'Primera Guerra Mundial (1914-1918). Una obra maestra del cine mundial sobre la camaradería y las relaciones humanas que retrata el día a día de unos prisioneros franceses en un campo de concentración alemán durante la Primera Guerra Mundial. Cuando llegan al campo dos oficiales de la aviación francesa, son informados por sus compañeros de barracón de que están excavando un túnel para poder escapar de allí.', '/oU882MmvJ6ZI03UA8Oz3SFKwDlX.jpg', '/xjl0yrBwzO1ZOEK8CuIDsD4Ti33.jpg', 7.9, 'vcO8rEjoG0c', array['1001']::text[], 140, null, 'segura', null),
(43278, 'movie', 'La vida de Émile Zola', 'La vida de Emile Zola', 'The Life of Emile Zola', 1937, 'William Dieterle', 'Biografía del famoso escritor francés Emile Zola, que incide especialmente en su participación en el famoso "Caso Dreyfuss", que puso en jaque al ejército francés.', '/xGFEL96K9zVvg2v1oQpKz4zEL91.jpg', '/qsqFiqjdscd0j4jjI45CP9GgtfC.jpg', 6.7, 'bTStzVavGpo', array['1001']::text[], 141, null, 'segura', null),
(43865, 'movie', 'Stella Dallas', 'Stella Dallas', 'Stella Dallas', 1937, 'King Vidor', 'Stella, una chica de familia humilde, se casa con el adinerado Steve. Al poco tiempo, tienen una hija y todo parece ir bien, pero las grandes diferencias de educación harán mella en su matrimonio y finalmente se separan. Pasados unos años, Stella renuncia a su hija en favor de Steve para que la niña se críe en un mejor ambiente.', '/spcGWnz05deoY7gAl0EvrBelzPa.jpg', '/qh5Yo1GdWp7maimAJwuBwQgf8Sb.jpg', 6.9, 'xZMf_kDxMKg', array['1001']::text[], 141, null, 'segura', null),
(41059, 'movie', 'Make Way for Tomorrow', 'Dejad paso al mañana', 'Make Way for Tomorrow', 1937, 'Leo McCarey', 'Un anciano matrimonio reúne a sus dos hijos para comunicarles que están arruinados y los van a desahuciar en un plazo muy breve. Sus vidas tomarán un nuevo rumbo.', '/qDju9eIilLWCvC1aFflOkt7EEwf.jpg', '/2TPV4B6gQZ3rOoJh9YlnGmSVAR3.jpg', 7.5, 'AeKsY3Kg2OU', array['1001']::text[], 142, null, 'segura', null),
(408, 'movie', 'Blancanieves y los siete enanitos', 'Blancanieves y los siete enanitos', 'Snow White and the Seven Dwarfs', 1938, 'David Hand', 'La malvada madrastra de la princesa Blancanieves decide deshacerse de ella porque no puede soportar que la belleza de la joven sea superior a la de ella. Sin embargo, Blancanieves consigue salvarse y se refugia en la cabaña de los siete enanitos. A pesar de todo, su cruel madrastra consigue encontrarla y la envenena con una manzana. Pero la princesa no está muerta, sólo dormida, a la espera de que un príncipe azul la rescate.', '/b2ZPP3bZqDOzqTHr1TlFIFPWP48.jpg', '/4yWayBvwl9gHXaWrDrAslxjL7mh.jpg', 7.1, 'CcWD5hI44WI', array['1001']::text[], 143, null, 'segura', null),
(14675, 'movie', 'La pícara puritana', 'La pícara puritana', 'The Awful Truth', 1937, 'Leo McCarey', 'Jerry y Lucy Warriner están a punto de divorciarse y luchan por la custodia de su perro, Mr. Smith. Antes de que el divorcio se haga oficial, Jerry decide volver con Lucy, pero se entera de que ella va a casarse con un hombre que se ha hecho rico gracias al petróleo. Jerry contraataca anunciando su compromiso con la aristocrática Barbara Vance.', '/x71I58fRwkFynz3BeIU4aLPgqMt.jpg', '/hkYHYp6IrVbDE39ffoGofTIsVj5.jpg', 7.2, 'FeRYj5IeBug', array['1001']::text[], 144, null, 'segura', null),
(1976, 'movie', 'Jezabel', 'Jezabel', 'Jezebel', 1938, 'William Wyler', 'Pocos años antes de la guerra de secesión, la bella, impulsiva y temperamental sureña Julie Marsden (Bette Davis) hace una entrada memorable en el Gran Baile de Debutantes del Olympus. En una época en la que se esperaba que las mujeres solteras vistieran de blanco prístino, ella insiste tercamente en llevar un inadecuado, pecaminoso e incendiario vestido rojo. Su propósito es despertar los celos de su prometido, el banquero Preston Dillard (Henry Fonda), pero sólo consigue destruir sus oportunidades con él. Preston se va al Norte y finalmente decide casarse con otra, sin su conocimiento.  Tres años después, Preston vuelve, y una determinada y arrepentida Julie se disculpa humildemente ante Preston,  pidiéndole que la ame como ella le ama. Preston la rechaza.', '/fqK6FXrKOfonxHCzALnftkZ9lM6.jpg', '/iedio5AiyYPM4AqxoTq2f7QRebd.jpg', 7.0, 'SQJJyYGQqek', array['1001']::text[], 145, null, 'segura', null),
(26252, 'movie', 'Pépé le Moko', 'Pépé le Moko', 'Pépé le Moko', 1937, 'Julien Duvivier', 'Pépé le Moko, uno de los delincuentes más buscados de Francia, se esconde en el barrio de la Casbah de Argel. Sabe que la policía le esperará si intenta salir de la ciudad. Cuando Pépé conoce a Gaby, una hermosa mujer de París que se ha perdido en la Casbah, se enamora de ella.', '/A29uSYxPYvUyewxjjzekUdpyZav.jpg', '/rk0JRAkxRy0ABBiasvZucLQ0qlB.jpg', 7.2, '8Lh-1-G9tzQ', array['1001']::text[], 145, null, 'segura', null),
(10907, 'movie', 'Robin de los bosques', 'Robin de los Bosques', 'The Adventures of Robin Hood', 1938, 'Michael Curtiz, William Keighley', 'Robin de Locksey regresa a Inglaterra tras combatir contra los infieles en las Cruzadas, pero Juan sin Tierra, el hermano del Rey Ricardo I, ha usurpado el trono y gobierna como un tirano, por lo que el noble sajón decide refugiarse en el bosque de Sherwood y luchar contra él para devolverle la corona a Ricardo.', '/bCXYN015wb10UTPgXZxcd2RAjBI.jpg', '/yjnfM8QmrXQkWl8dUimsDGl73el.jpg', 7.5, 'bU6rh7nRDgY', array['1001']::text[], 146, null, 'segura', null),
(13696, 'movie', 'Ángeles con caras sucias', 'Ángeles con caras sucias', 'Angels with Dirty Faces', 1938, 'Michael Curtiz', 'Un sacerdote presencia impotente cómo los niños marginados de su parroquia sucumben a las malas influencias de un criminal que fue compañero suyo de la infancia. Sin embargo, con el tiempo los dos hombres siguieron caminos muy diferentes: uno abrazó el sacerdocio y el otro se convirtió en un gángster.', '/4fVtXV9ERGSej3sSCyyQtE1rmBp.jpg', '/scHIDomz6Irdf4pQt53Q6pqdSk1.jpg', 7.5, 'z5qzZJ7K_B8', array['1001']::text[], 146, null, 'segura', null),
(685, 'movie', 'Olimpíada', 'Olympia 2 - Festival de la belleza', 'Olympia - Fest der Schönheit', 1938, 'Leni Riefenstahl', 'Segunda parte de Olympia, un documental sobre los Juegos Olímpicos de 1936 en Berlín de la directora alemana Leni Riefenstahl. La película se proyectó en los cines en 1938 y de nuevo en 1952, tras la caída del régimen nazi.', '/fVAVcdBqAI4HXhVIRCvKbYM6Jrq.jpg', '/hbL5vWtqJrPCrLEcgQLT5lj2a8G.jpg', 6.7, null, array['1001']::text[], 147, null, 'probable', '[{"tmdb_id": 685, "titulo": "Olympia 2 - Festival de la belleza", "original": "Olympia - Fest der Schönheit", "anio": 1938, "votos": 83, "poster_path": "/fVAVcdBqAI4HXhVIRCvKbYM6Jrq.jpg", "sim": 0.4}, {"tmdb_id": 677, "titulo": "Olympia 1 - Festival de las naciones", "original": "Olympia - Fest der Völker", "anio": 1938, "votos": 128, "poster_path": "/zYQCM8qItmRu2eCmAVm8qGRov6.jpg", "sim": 0.438}]'::jsonb),
(43844, 'movie', 'El pan y el perdón', 'El pan y el perdón', 'La Femme du boulanger', 1938, 'Marcel Pagnol', 'En este pequeño pueblo provenzal se instala un nuevo panadero, Aimable. Su esposa Aurelie es hermosa y mucho más joven que él. Ella parte con un pastor la noche después de que Aimable produce sus primeros panes. Aimable está tan afligido que ya no puede trabajar. Por lo tanto, los aldeanos, que inicialmente se rieron de sus cuernos, se toman el asunto muy en serio (quieren el pan) y organizan un plan para encontrar a Aurelie y llevarla de regreso a la panadería.', '/mqpG83Y9opUp2ZjcPEoimD5nWTi.jpg', '/kmgdPpZpgCgPY5F2cFf8YrutmeL.jpg', 7.3, 'WsPZwPY-860', array['1001']::text[], 148, null, 'segura', null),
(900, 'movie', 'La fiera de mi niña', 'La fiera de mi niña', 'Bringing Up Baby', 1938, 'Howard Hawks', 'David Huxley (Cary Grant) es un paleontólogo tímido y despistado que está a punto de acabar la laboriosa reconstrucción del esqueleto de un brontosaurio, al que sólo le falta una clavícula intercostal. También está a punto de casarse con su anodina secretaria. En un partido de golf con el abogado de una solterona millonaria, potencial mecenas del museo para el que trabaja, Huxley conoce a Susan Vance (Katharine Hepburn), una joven adinerada y caprichosa que hará lo posible para que no culmine ninguno de sus dos proyectos: se dedicará a manipular a Huxley para seducirlo con un estilo muy peculiar: le abolla el coche, le desgarra el smoking, esconde su ropa, le rompe las gafas y por si fuera poco, lo embauca para que cuide a un joven leopardo llamado "Baby".', '/g3RIOKbxuiJ16hfz73KwmEfaSag.jpg', '/fzJgCQh2NBnUYlms8EGyr4bPNz3.jpg', 7.5, 'Qlf6gHD-YEM', array['1001']::text[], 149, null, 'segura', null),
(995, 'movie', 'La diligencia', 'La diligencia', 'Stagecoach', 1939, 'John Ford', 'Personajes muy variopintos emprenden un largo, duro y peligroso viaje en diligencia. Entre ellos, un fuera de la ley en busca de venganza, una prostituta a la que han echado del pueblo, un jugador, un médico, la mujer embarazada de un militar y un sheriff. Las relaciones entre ellos serán difíciles y tensas. Además, durante el viaje, tendrán que afrontar el ataque de una partida de indios apaches.', '/wHXgVEfvkExGzm5qNFcYKTTSY0W.jpg', '/7SYNEG50fKODsTP6h9phYM3BueV.jpg', 7.6, 'OE-VWDsdkwM', array['1001']::text[], 150, null, 'segura', null),
(46069, 'movie', 'La historia del último crisantemo (Zangiku monogatari)', 'Historia del último crisantemo', '残菊物語', 1939, 'Kenji Mizoguchi', 'En el Tokyo de 1885, Kikunosuke Onoue, hijo de un importante actor, descubre, desolado, que es aplaudido únicamente por ser el heredero de su padre y que, en realidad, el público se mofa de sus interpretaciones. La única persona que se atreve a ser sincera con él es Otoku, la niñera de los hijos de su hermano. pero precisamente por ello es despedida, y a Kikunosuke le prohiben verla por temor a los rumores que se desatarían por su relación con una sirvienta.', '/iFm7qGu6gJrcWZr7tMo6Bi4QnDT.jpg', '/jl8Te0ZZXxO6iBuQmZgZSZqqCnd.jpg', 7.8, 'Jw9lbIfMSEg', array['1001']::text[], 152, null, 'segura', null),
(32610, 'movie', 'Los hijos de la farándula', 'Los hijos de la farándula', 'Babes in Arms', 1939, 'Busby Berkeley', 'Dos jóvenes se proponen triunfar en el mundo del espectáculo: son Mickey Moran (Mickey Rooney), talentoso músico y cantante, hijo de un artista veterano, y Patsi Barton (Judy Garland), una joven cantante', '/g9vv00vJkA1pVeC8jV7LszrXXgf.jpg', '/aBid3Ug0ZHiFwqtVXNKETxviVkd.jpg', 6.4, 'tg5o_rEuVR0', array['1001']::text[], 152, null, 'segura', null),
(3083, 'movie', 'Caballero sin espada', 'Caballero sin espada', 'Mr. Smith Goes to Washington', 1939, 'Frank Capra', 'Jefferson Smith, un joven ingenuo e idealista, que parece fácilmente manipulable, es nombrado senador. Ignora que en Washington tendrá que vérselas con políticos y empresarios sin escrúpulos que le harán perder la fe. Sin embargo, gracias a su secretaria, una joven que conoce muy bien los entresijos de la política, protagoniza en el Senado una espectacular y maratoniana intervención en la que, además de defender apasionadamente la democracia, pone en evidencia una importante trama de corrupción.', '/ywTpPCVvKCXBEKdS0eyP2isDhuE.jpg', '/letCnM0ahMs6TgWgLfIaHT7KtSK.jpg', 7.8, 'bXoF7w6IWAc', array['1001']::text[], 153, null, 'segura', null),
(630, 'movie', 'El mago de Oz', 'El mago de Oz', 'The Wizard of Oz', 1939, 'Victor Fleming', 'La huérfana Dorothy Gale vive una vida sencilla en Kansas con su tía Emma Clara Blandick, su tío Henry y tres pintorescos peones: Hunk, Zeke y Hickory. Un día la severa vecina Miss Gulch es mordida por el perro de Dorothy, Toto. Miss Gulch se lo lleva, por orden del sheriff, a pesar de las apasionadas protestas de tía Emma y el tío Henry. Toto escapa y regresa junto a Dorothy, la cual se alegra momentáneamente, pero pronto se da cuenta de que Miss Gulch regresará. Decide llevarse a Toto y fugarse en busca de una vida mejor ''en algún lugar sobre el arco iris''.', '/ymUY2iIm8IuSYuIX1SsABgPyB48.jpg', '/g1OvTd1eF346vmx8qsJnjaiooZ6.jpg', 7.6, 'b_A2twyZevo', array['1001']::text[], 154, null, 'segura', null),
(43828, 'movie', 'Arizona', 'Arizona', 'Destry Rides Again', 1939, 'George Marshall', 'Tom Destry, hijo de un legendario pacificador de la frontera, es un joven pacífico que rechaza todo tipo de violencia, por lo que es objeto de toda clase de burlas cuando recorre a caballo la ciudad de Bottleneck, el feudo personal de Kent. Las burlas aumentan cuando Destry nombra sheriff al borracho Wash Dimsdale. Esta actitud cambia cuando resulta que Destry, a pesar de odiar las armas, es un buen tirador. Mientras tanto, Frenchy, la cantante del saloon y novia de Kent, que se siente ofendida ante la indiferencia que Destry muestra hacia ella, jura poner en ridículo al nuevo sheriff.', '/417hr3afzrztItanwdpvgJDah8G.jpg', '/7Gy9bSYod5QolabzAm4Ol1P6wHZ.jpg', 7.2, '0pI-iBxGqTo', array['1001']::text[], 156, null, 'segura', null),
(43832, 'movie', 'Solo los ángeles tienen alas', 'Sólo los ángeles tienen alas', 'Only Angels Have Wings', 1939, 'Howard Hawks', 'En un país sudamericano, situado en los Andes, mientras Cary Grant dirige un servicio de transporte aéreo de mercancías, Jean Arthur es una corista que está allí de vacaciones.', '/gDHbi3xXfIFr5s2L13XE99xxzV.jpg', '/wq7KVxUAYH06cHuReBcV0Sx2kFv.jpg', 7.3, 'Cu-LBgeDJlA', array['1001']::text[], 157, null, 'segura', null),
(770, 'movie', 'Lo que el viento se llevó', 'Lo que el viento se llevó', 'Gone with the Wind', 1939, 'Victor Fleming', 'Scarlett O''Hara, hija de un terrateniente del sur de Estados Unidos, atraviesa la Guerra de Secesión y la reconstrucción entre amores y supervivencia.', '/vEMSjJbenWci9TrxxtAPPtk3Mzj.jpg', '/4FHcxMtVruMr7ltU2cItWssLjTP.jpg', 7.9, 'h2oX0zQA67U', array['1001','clasicos']::text[], 158, null, 'segura', null),
(27053, 'movie', 'Le jour se lève', 'Amanece (Al despertar el día)', 'Le jour se lève', 1939, 'Marcel Carné', 'Perseguido por la policía, François (Jean Gabin) se refugia en una casa. Mientras está rodeado, va recordando cómo los conflictivos hechos de los últimos días lo han conducido hasta la apurada situación en la que se encuentra; su pasión por la florista Françoise (Jacqueline Laurent), su compleja relación con la prostituta Clara (Arletty) y el asesinato de Valentin (Jules Berry), un extraño personaje relacionado con ambas mujeres.', '/jfWl08q4UUg1YB7goa69miodP65.jpg', '/9gEEeK9hwkxS1fEtYEAohahAWxq.jpg', 7.6, '6W4lacJZ2Z8', array['1001']::text[], 160, null, 'segura', null),
(24965, 'movie', 'Gunga Din', 'Gunga Din', 'Gunga Din', 1939, 'George Stevens', 'Cutter, MacChesney y Ballantine, tres sargentos del ejército británico unidos por una estrecha amistad, son enviados a una zona montañosa de la India para averiguar las causas de la extraña interrupción de las comunicaciones telegráficas. Los tres vivirán, en compañía de Gunga Din, su porteador de agua, diversas aventuras que les enfrentarán a los temibles tags, una secta de adoradores de la diosa Kali. Descubrirán, además, un templo escondido, serán apresados y torturados y salvarán al ejército de caer en una trampa mortal.', '/8fLcAvzN6t4kkE5HPRqpe5HHRYE.jpg', '/e2bbVKWvsci9ZvIA773EozFkEHd.jpg', 6.5, '1wIMA9FRFLU', array['1001']::text[], 161, null, 'segura', null),
(1859, 'movie', 'Ninotchka', 'Ninotchka', 'Ninotchka', 1939, 'Ernst Lubitsch', 'Los camaradas Iranoff, Buljanoff y Kopalski han sido enviados a París para obtener dinero para el Gobierno ruso mediante la venta de las joyas confiscadas a la gran duquesa Swana, que vive en la capital francesa. Los tres camaradas se instalan en un hotel de lujo mientras los tribunales franceses deciden quién es el verdadero propietario de las joyas. El Gobierno ruso envía a Nina ''Ninotchka'' Ivanovna Yakushova a arreglar las cosas.', '/fAnREAZKearjfXD2cm6QhKKK7Av.jpg', '/AjYX2r2dn1s31A8fDaPPiYRrZ6L.jpg', 7.5, 'OhCCG5qSC1I', array['1001']::text[], 161, null, 'segura', null),
(776, 'movie', 'La regla del juego', 'La regla del juego', 'La Règle du jeu', 1939, 'Jean Renoir', '1939, París y Sologne. Un aviador, enamorado de una mujer de mundo, no respeta la regla del juego que consiste en salvar las apariencias en una sociedad dividida fundamentalmente en dos clases: los señores y los criados.', '/jQSb3RG1I68GuNNYxVE09FK21kF.jpg', '/8lRULNwlOIQ5Jg8puE2g7gjk32j.jpg', 7.5, 'oRH7oaBQuaY', array['1001']::text[], 162, null, 'segura', null),
(3084, 'movie', 'Cumbres borrascosas', 'Cumbres borrascosas', 'Wuthering Heights', 1939, 'William Wyler', 'Perdido en medio de una tormenta de nieve en un rocoso páramo inglés, un extranjero se topa con Cumbres Borrascosas, la lúgubre mansión del misterioso Heathcliff, un hombre tan torturado por un amor frustrado que ha perdido el deseo de vivir. Mientras la tormenta ruge en el exterior, el fatigado caminante escucha fascinado la triste historia del desesperado amor de Heathcliff y Cathy. Cuando Heathcliff volvió a buscarla, después de una larga ausencia intentando hacer fortuna, Cathy ya se había casado con un joven de la alta sociedad. El desengaño destrozó el alma de Heathcliff, pero no logró apagar el fuego de una pasión inextinguible que arderá en sus entrañas por toda la eternidad.', '/rnTneXb0oGh6yatXgPcn7ApYAge.jpg', '/z7aF8AG12QpirHEvKffN0R0HL6M.jpg', 7.2, 'XmuMd4FnnYo', array['1001']::text[], 164, null, 'segura', null),
(3085, 'movie', 'Luna nueva', 'Luna nueva', 'His Girl Friday', 1940, 'Howard Hawks', 'Hildy Johnson, la mejor reportera del periódico Morning Post, anuncia que va a dejar el periodismo para casarse y dedicarse a su familia y a las labores del hogar. Pero Walter Burns, el editor del periódico y ex-marido de Hildy, no puede aceptarlo, por lo que se sirve de toda clase de tretas para retenerla en el periódico y, de paso, intentar reconquistarla.', '/d13ByB7PTdWAkWscSO6HA6N6vkE.jpg', '/ihoQaiMFAz4YCTAaSIsQjRknsNH.jpg', 7.4, 'yRMDR2KKugo', array['1001']::text[], 164, null, 'segura', null),
(596, 'movie', 'Las uvas de la ira', 'Las uvas de la ira', 'The Grapes of Wrath', 1940, 'John Ford', 'Tom Joad regresa a su hogar tras cumplir condena en prisión, pero la ilusión de volver a ver a los suyos se transforma en frustración al ver cómo los expulsan de sus tierras. Para escapar al hambre y a la pobreza, la familia no tiene más remedio que emprender un larguísimo viaje lleno de penalidades con la esperanza de encontrar una oportunidad en California, la tierra prometida.', '/xwWtL3H1dOiDxToKTOIYHK3QUgu.jpg', '/r7AcmVk6kGhdFdesViGaI3dEHWd.jpg', 7.8, 'e8C_eK2ra3s', array['1001']::text[], 165, null, 'segura', null),
(223, 'movie', 'Rebeca', 'Rebeca', 'Rebecca', 1940, 'Alfred Hitchcock', 'Al poco tiempo de perder a su esposa Rebeca, el aristócrata inglés Maxim De Winter conoce en Montecarlo a una joven humilde, dama de compañía de una señora americana. De Winter y la joven se casan y se van a vivir a la mansión inglesa de Manderley, residencia habitual de De Winter. Pronto la señora Winter se da cuenta de que no puede borrar en su marido el recuerdo de su difunta esposa.', '/mJV2zrflpTaAcFgfgQc2VJboZ0Y.jpg', '/46p36NyMO6f25YtSqSYiwz4mKbW.jpg', 7.9, 'cJok8CPtHRw', array['1001']::text[], 165, null, 'segura', null),
(756, 'movie', 'Fantasía', 'Fantasía', 'Fantasia', 1940, 'Samuel Armstrong, James Algar, Bill Roberts', 'Una colección de interpretaciones animadas de grandes obras de música clásica. En ''El Aprendiz de Brujo'' (P. Dukas), Mickey Mouse, discípulo de un mago, se mete en un gran embrollo, pues sus conocimientos de magia son muy limitados. ''La Consagración de la Primavera'' (Stravinsky) cuenta la historia de la evolución, desde los seres unicelulares hasta la extinción de los dinosaurios. ''La Danza de las Horas'' (Ponchielli) es un fragmento de un ballet cómico interpretado por elefantes, hipopótamos, cocodrilos y avestruces. ''Una Noche en el Monte Pelado'' de Mussorgsky y el ''Ave Maria'' de Schubert describen el enfrentamiento entre la oscuridad y la luz.', '/s1616SHvNWKHEC52tE1CleDgXFt.jpg', '/lyzI5uFJC2E7sIYCCdaU0oZkDw2.jpg', 7.4, 'eD8U083gQmY', array['1001']::text[], 166, null, 'segura', null),
(981, 'movie', 'Historias de Filadelfia', 'Historias de Filadelfia', 'The Philadelphia Story', 1940, 'George Cukor', 'Historias de Filadelfia es una comedia protagonizada por Cary Grant, Katherine Hepburn y James Stewart. Tracy Lord (Katherine Hepburn) es idolatrada por todo el mundo y debe mantener a su siniestro ex-marido, un periodista alcohólico, y su futuro marido contentos.', '/lsVyk2qzL6snKpAtrvZU2DfGar3.jpg', '/xQcZeezcuaQ59yLJn6pBTRhOqFG.jpg', 7.5, '4f2jCffBrck', array['1001']::text[], 167, null, 'segura', null),
(32196, 'movie', 'Dance, Girl, Dance', 'Baila, muchacha, baila', 'Dance, Girl, Dance', 1940, 'Dorothy Arzner', 'Judy O''Brien forma parte de un grupo de baile y aspira a dedicarse al ballet clásico. Bubbles, compañera suya deja el grupo para centrarse en la comedia. Cuando el grupo se deshace, Bubbles le ofrece a Judy un ingrato trabajo: ser la telonera de su espectáculo.', '/m2POaEpxsBeF1tXOTYgmlaDRMnm.jpg', '/bKWBwEoZfhSqKPpz9NFJGFgyUyI.jpg', 6.4, null, array['1001']::text[], 169, null, 'segura', null),
(10895, 'movie', 'Pinocho', 'Pinocho', 'Pinocchio', 1940, 'Hamilton Luske, Ben Sharpsteen, Jack Kinney', 'Un anciano llamado Geppetto fabrica una marioneta de madera a la que llama Pinocho, con la esperanza de que se convierta en un niño de verdad. El Hada Azul hace realidad su deseo y da vida a Pinocho, pero conserva su cuerpo de madera. Pepito Grillo, la conciencia de Pinocho, tendrá que aconsejarlo para que se aleje de las situaciones difíciles o peligrosas hasta conseguir que el muñeco se convierta en un niño de carne y hueso.', '/sAluF7lNc4Mv3qxx1mmOgsfbr0C.jpg', '/ikpwuaK0yzNhXO24OeB7cKulhZE.jpg', 7.1, '_xHYzf_rdGU', array['1001']::text[], 169, null, 'segura', null),
(989, 'movie', 'The Mortal Storm', 'Tormenta mortal', 'The Mortal Storm', 1940, 'Frank Borzage', 'Victor Roth es un profesor universitario que vive tranquilamente con su familia en un pequeño pueblo del sur de los Alpes alemanes. Pero, cuando Hitler llega al poder (1933), los Roth, como todas las familias de origen judío, se ven obligados a separarse. Además Roth ve cómo su carrera se arruina y cómo sus hijos varones apoyan el nacionalsocialismo. En cambio, su hija Freya (Sullavan) y su prometido Martin (Stewart) ven con claridad meridiana que la única salida es huir del país.', '/1AN4WG7Son2XdDbgPB2bnM3KNND.jpg', '/zqgzF9zkDlLqVARJGgoMSugb1at.jpg', 7.4, 'ZGU_trhNuOs', array['1001']::text[], 170, null, 'segura', null),
(911, 'movie', 'Detective a la fuerza', 'Detective a la fuerza', 'The Bank Dick', 1940, 'Edward F. Cline', 'Divertida comedia, de la que W. C. Fields tuvo el control casi absoluto. Aparte de ser el protagonista, el actor firmó el guión con el curioso seudónimo de Mahatma Kane Jeeves. En realidad la trama es completamente disparatada, casi mera excusa para acumular gags sobre el personaje de Egbert Sousé, una especie de ''alter ego'' de Fields, o al menos de la imagen que tenía de él el gran público. El actor da vida a un borrachín, que por casualidad detiene a un atracador de bancos. A partir de ahí nace una fulgurante carrera de detective, prácticamente a su pesar, pues él incluso intenta participar en una estafa. (FILMAFFINITY)', '/3XrqHTrJpTaUeyqXqb4fVacYWpf.jpg', '/erqri6EuFfDNZg2kPjk33IPKfGq.jpg', 6.5, 'vpBRMlo9CH0', array['1001']::text[], 171, null, 'segura', null),
(15, 'movie', 'Ciudadano Kane', 'Ciudadano Kane', 'Citizen Kane', 1941, 'Orson Welles', 'Tras la muerte de un magnate de la prensa, un periodista intenta descifrar el sentido de su última palabra entrevistando a quienes lo conocieron.', '/w7V0bv38Z0q0DgHmMfcGM4WRNTv.jpg', '/ruF3Lmd4A8MHbnEBE6lxPMbsHGL.jpg', 8.0, 'fAcLNMkzfTE', array['1001','clasicos']::text[], 172, null, 'segura', null),
(3086, 'movie', 'Las tres noches de Eva', 'Las tres noches de Eva', 'The Lady Eve', 1941, 'Preston Sturges', 'Durante un viaje en un trasatlántico, Charles Pike, un soltero millonario experto en serpientes que vuelve de la jungla, se enamora de Jean Harrington, una jugadora profesional que, junto con su padre, hace trampas con las cartas. Jean, que también se ha enamora de Charlie, decide abandonar el juego pero, cuando Charlie se entera de cuál es su medio de vida, rompe su compromiso con ella. Jean, dolida, intenta vengarse. La oportunidad se presenta cuando Los Harrington se encuentran con un estafador amigo suyo. Entonces Jean decide hacerse pasar por su sobrina: Lady Eve Sidwich. Charlie conoce en una fiesta a Lady Eve y queda anonadado por su parecido con Jean.', '/sxQ00JeZ7kSZGr3NM3hHmHeSwaJ.jpg', '/7nL4SLErtTIU9lO1ZZMNIJYH0XD.jpg', 7.3, 'lj9ilqIyCUk', array['1001']::text[], 174, null, 'segura', null),
(13666, 'movie', 'El hombre lobo', 'El hombre lobo', 'The Wolf Man', 1941, 'George Waggner', 'Tras varios años en Estados Unidos, el hijo de un noble inglés regresa a la mansión de su padre en Gales. Una noche que asiste a una feria zíngara es mordido por un lobo y su vida comienza a cambiar cuando teme ser el responsable de las muertes que se están produciendo en la localidad.', '/3g8NALLvHFeN9yGXoRKrrhVp6RW.jpg', '/hwMWJ8G5173SGCHzrm0mVjvESaY.jpg', 7.0, 'GeKQL7ddgMo', array['1001']::text[], 175, null, 'segura', null),
(963, 'movie', 'El halcón maltés', 'El halcón maltés', 'The Maltese Falcon', 1941, 'John Huston', 'Un detective privado es abordado por una misteriosa mujer, que dice estar amenazada. Pero tanto el perseguidor como el hombre encargado de su protección aparecen muertos. Todo parece girar alrededor de una estatua de un halcón de valor incalculable.', '/zFs0brybfDHNwpfXQVyjFyam8uw.jpg', '/5lMm0MmAviP6DF45nxBVOT9LCwK.jpg', 7.7, 'Yv-BPuqhW9U', array['1001']::text[], 176, null, 'segura', null),
(11360, 'movie', 'Dumbo', 'Dumbo', 'Dumbo', 1941, 'Ben Sharpsteen, Bill Roberts, Samuel Armstrong', 'Las cigüeñas llegan, como todos los años, hasta un pintoresco circo para repartir los bebés a sus respectivas mamás. La señora Dumbo, una elefanta, descubre que su bebé tiene unas orejas enormes; todas sus compañeras se ríen de él, pero la señora Dumbo lo defiende siempre, hasta el punto de ser encerrada por enfrentarse a todo aquel que se mofe de su retoño. El pequeño Dumbo, maltratado y ridiculizado por todos sus compañeros, sólo cuenta con la ayuda de un minúsculo ratoncito llamado Timothy, que decide hacer de él una estrella del circo.', '/xXBX2G5dc2WUZslcWuAXYKvYKoI.jpg', '/eEKpOowAkVAF3sKJKqY2h4h12GV.jpg', 7.0, 'sie0ataCDHg', array['1001']::text[], 178, null, 'segura', null),
(16442, 'movie', 'El sargento York', 'El Sargento York', 'Sergeant York', 1941, 'Howard Hawks', 'Alvin C. York es un joven y trabajador campesino que vive en una de las numerosas granjas de los montes de Cumberland, en el estado de Tennessee. Sólo tiene un defecto: la bebida. Alvin está enamorado de una muchacha, cuya familia de clase alta impide el matrimonio. Basada en hechos reales.', '/b88yi9w5hYHD6GyguJsSMdnZPJ4.jpg', '/i4nVONDi6brdbG8K8J1NmMrD0NJ.jpg', 7.2, '6xw4I67VP_U', array['1001']::text[], 178, null, 'segura', null),
(27725, 'movie', 'El último refugio', 'El último refugio', 'High Sierra', 1941, 'Raoul Walsh', 'Roy Earle sale de prisión antes de cumplir condena gracias a su buena conducta y a la fianza depositada por Big Mac, jefe de la banda a la que perteneció. Poco después, un miembro de la banda le comunica que Big Mac, que prepara un nuevo golpe, le espera en California. Roy, pese a su intención de cambiar de vida, decide acudir a la cita. En su viaje a través del país, entabla amistad con una humilde familia de granjeros, cuya nieta, Vilma, conquista su corazón.', '/8oL0cvnHtrz11XBsDgG4igycBp8.jpg', '/6AcvQvapwSI0fw2j9fVUxMOkwNB.jpg', 7.1, 'X-oPLZYOCcM', array['1001']::text[], 179, null, 'segura', null),
(16305, 'movie', 'Los viajes de Sullivan', 'Los viajes de Sullivan', 'Sullivan''s Travels', 1941, 'Preston Sturges', 'Estrenada primero en Portugal el 5 de Diciembre 1941.  Obsesionado con la idea de rodar una película sobre la miseria y el sufrimiento, el director de cine John L. Sullivan convence a los ejecutivos del estudio para que le permitan recorrer el país disfrazado de vagabundo antes de empezar a rodar. Después de trabajar como peón para una viuda que espera de él algo más que cortar leña, huye de su casa, pero el camión que lo recoge lo lleva de vuelta a Hollywood. Sintiéndose completamente frustrado, Sully entra en una cafetería, donde conoce a una actriz rubia, que, entusiasmada con su proyecto, decide acompañarlo en su aventura.', '/5S8po5Rd9ELgwrt8P4DKr5vGBje.jpg', '/7E4b9mXU9psvGbqCbI0aGEGI1oO.jpg', 7.4, 'kIrdtdpPQHY', array['1001']::text[], 180, null, 'segura', null),
(43266, 'movie', 'Qué verde era mi valle', '¡Qué verde era mi valle!', 'How Green Was My Valley', 1941, 'John Ford', 'En un pequeño pueblo de Gales, un padre y sus cinco hijos trabajan en las minas de carbón y la vida cotidiana fluye pacíficamente. Sin embargo, sus condiciones de trabajo son cada vez más difíciles y los hijos deciden dar un golpe, en contra de la opinión de su padre.', '/5xCFo2NunmfRUtQyiZIqCT7krTJ.jpg', '/ucQESsrG63LsA5HD70aaPxEyORk.jpg', 7.3, 'Aq7yCJG7Dew', array['1001']::text[], 182, null, 'segura', null),
(32847, 'movie', 'La extraña pasajera', 'La extraña pasajera', 'Now, Voyager', 1942, 'Irving Rapper', 'Charlotte Vale, una mujer de mediana edad que pertenece a una familia acomodada de Boston, vive reprimida y totalmente controlada por su dominante e insensible madre. Gracias a la ayuda de un amable psiquiatra, Charlotte consigue recuperar la autoestima y superar sus miedos. Además, se vuelve mucho más extrovertida y empieza a sentirse incluso atractiva. Dispuesta a disfrutar de su nueva vida, hace un crucero por América del Sur y en el barco conocerá a un apuesto arquitecto infelizmente casado.', '/iqGhTDyGGuU1c54G1N2uzkfVOR7.jpg', '/lAqTraujV7MQUnMZ78XD07Tv5lQ.jpg', 7.4, '0cr2sS2WN7w', array['1001']::text[], 183, null, 'segura', null),
(32255, 'movie', 'Un marido rico', 'Un marido rico', 'The Palm Beach Story', 1942, 'Preston Sturges', 'Inexplicablemente, un novio y una novia no pueden asistir a su propia boda porque se lo impiden sus dobles, que son los que se casan. Seis años más tarde, el administrador del piso de Park Avenue de Tom y Gerry Jeffers enseña la casa, aunque todavía viven en ella, a otros posibles inquilinos, ya que ellos se han retrasado en el pago del alquiler. Gerry se siente frustrada porque su marido, un arquitecto que intenta sacar adelante sus proyectos, no permite que ella utilice su belleza para conseguir que alguien se los financie. Entonces, Gerry conoce accidentalmente a John D. Hackensacker III, uno de los hombres más ricos del mundo.', '/fK5LKq0Tiytk4cwsft5KhfQ1W0M.jpg', '/2b999zCG0DGjePd9fpA2keMspey.jpg', 7.0, '7p_wafSdMLI', array['1001']::text[], 183, null, 'segura', null),
(289, 'movie', 'Casablanca', 'Casablanca', 'Casablanca', 1942, 'Michael Curtiz', 'En plena Segunda Guerra, el dueño de un bar en Casablanca vuelve a cruzarse con la mujer que lo dejó en París. Ella necesita su ayuda para escapar junto a su marido, un líder de la resistencia.', '/a7EjycGNSYw6QqJqDooD9eQGZ4r.jpg', '/87wqeMeUeMRLjsE1IWNKJcPlpuC.jpg', 8.1, 'nqlROp1TIgo', array['1001','clasicos']::text[], 184, null, 'segura', null),
(198, 'movie', 'Ser o no ser', 'Ser o no ser', 'To Be or Not to Be', 1942, 'Ernst Lubitsch', 'Las tropas de Hitler invaden Varsovia. En la ciudad, una compañía de teatro que iba a representar una obra, se ve obligada a sustituirla por Hamlet. Mientras, la esposa del actor principal empieza a flirtear con un apuesto oficial.', '/p0bk9raiEpR2Qm0nE9kk3F3YO7v.jpg', '/28vvMlh490bxipmhkbYTQissiof.jpg', 7.8, 'DM4PxOf3OxY', array['1001']::text[], 186, null, 'segura', null),
(25508, 'movie', 'La mujer pantera', 'La mujer pantera', 'Cat People', 1942, 'Jacques Tourneur', 'Oliver conoce a Irena durante una visita al zoo, se enamoran y acaban contrayendo matrimonio. Durante el convite, una misteriosa mujer aparece y afirma ser pariente de Irena. Ella comienza desde entonces a comportarse de manera extraña. Por ello, Oliver solicita la ayuda del doctor Judd, un psiquiatra, mientras confía sus temores a Alice, una amiga. Los celos de Irena complicarán aún más la situación, poniendo en peligro la vida de Alice.', '/cTCZwzbLnrkap7uG3gsZmOc7mNl.jpg', '/dAE4x4BgauvsRkErmLg1L05LNAV.jpg', 6.9, 'w-MIQyzBWHs', array['1001']::text[], 187, null, 'segura', null),
(965, 'movie', 'El cuarto mandamiento', 'El cuarto mandamiento', 'The Magnificent Ambersons', 1942, 'Orson Welles', 'A finales del siglo XIX, la mansión Amberson es la más fastuosa de Indianápolis. Cuando su dueña, la bellísima Isabel, es humillada públicamente, aunque de forma involuntaria por su pretendiente Eugene Morgan, lo abandona y se casa con el torpe Wilbur Minafer. Su único hijo, George, crecerá demasiado consentido y malcriado. Años más tarde, Eugene regresa a la ciudad con su hija Lucy, de quien se enamora el engreído George.', '/vTDBlSw5lPLJi6JI7JjARNmCnZ0.jpg', '/pkD7zVlHpBoORTtupteZxiOxaG4.jpg', 7.3, 'ylPT4SV8WDE', array['1001']::text[], 188, null, 'segura', null),
(3087, 'movie', 'Yanqui Dandy', 'Yanqui Dandy', 'Yankee Doodle Dandy', 1942, 'Michael Curtiz', 'La biografía del bailarín de vodevil George M. Cohan, creador del himno norteamericano ”Over There”, sirvió de base para este musical donde Cagney pudo demostrar sus grandes dotes para el baile. La obra, aunque se trata de una comedia, tiene un importante trasfondo de propaganda bélica ya que está realizada en plena Segunda Guerra Mundial.', '/cqLLIyJFjLr6jGOxWVEHG11WGzB.jpg', '/dskxBjNFZsn6ThCZ7vAqd5UueEl.jpg', 7.0, 'ionMhYBMpek', array['1001']::text[], 190, null, 'segura', null),
(27040, 'movie', 'Meshes of the Afternoon', 'Un falso despertar', 'Meshes of the Afternoon', 1943, 'Maya Deren, Alexander Hammid', 'Una mujer (interpretada por la propia Maya Deren) explora sus propias imágenes interiores, a través de un sueño, donde los objetos ordinarios de su vida diaria consiguen un misterio sobrecogedor. Deren (1917-1961) explicó que quería "plasmar en la película la sensación que experimenta un ser humano sobre un incidente, más que grabar el incidente con precisión". Codirigido con su marido, el director de fotografía Alexander Hammid, "Meshes of the Afternoon", a través de sus múltiples lecturas y reinterpretaciones, pronto se erigió como uno de los films experimentales más importantes de todos los tiempos, y convirtió a Maya Deren en la voz preeminente del "avant-garde cinema" de los Estados Unidos en los años 40 y 50, influyendo en directores como Jean Cocteau, Luis Buñuel o David Lynch. El film lo adquirió el MoMA -The Museum of Modern Art- de Nueva York.', '/yHjEjRU81RcxKFNU5hhiPYMzlsu.jpg', '/otRHDr3aMJboh9N4AMbuKKnlHYL.jpg', 7.6, '98eh_4z4hfA', array['1001']::text[], 191, null, 'segura', null),
(84656, 'movie', 'Fires Were Started', 'Fires Were Started', 'Fires Were Started', 1943, 'Humphrey Jennings', 'Un nuevo hombre se incorpora a las filas de una brigada de bomberos de Londres durante la Segunda Guerra Mundial. Pronto conocerá a sus compañeros e intenta disfrutar del tiempo libre cuando llega su primera alarma y debe unirse al grupo para acudir a un almacén situado en la calle Trinidad, cerca de los puertos, donde las explosiones están haciendo mucha mella. (FILMAFFINITY)', '/A5qsYacdvEZhbLfiz4qtdoYeG6V.jpg', '/fWna0d9qWw0W1zZjnGhjHH5ympY.jpg', 6.1, null, array['1001']::text[], 192, null, 'segura', null),
(25037, 'movie', 'Coronel Blimp', 'Vida y muerte del Coronel Blimp', 'The Life and Death of Colonel Blimp', 1943, 'Emeric Pressburger, Michael Powell', 'En plena Segunda Guerra Mundial (1939-1945), un anciano militar británico rememora su larga y excitante vida. Su larga amistad con un colega alemán o su desobediencia a las ordenanzas para ayudar a una bella compatriota en apuros sólo son dos episodios de una experiencia personal inolvidable. (FILMAFFINITY)', '/wpgTu7hZhQyyQypCf3MgayWk5y.jpg', '/ojYxYkbO939H9OSayf5IKvbFA6i.jpg', 7.5, '5Y2-YdWbvAw', array['1001']::text[], 193, null, 'probable', '[{"tmdb_id": 25037, "titulo": "Vida y muerte del Coronel Blimp", "original": "The Life and Death of Colonel Blimp", "anio": 1943, "votos": 283, "poster_path": "/wpgTu7hZhQyyQypCf3MgayWk5y.jpg", "sim": 0.591}]'::jsonb),
(41996, 'movie', 'Perfidia', 'Perfidia', 'The Man in Grey', 1943, 'Leslie Arliss', 'Un marqués se casa con una joven sólo por el título, a la vez que ama a otra. La joven acabará enamorándose de un amigo menos afortunado, pero todo se complica más aún por las insidias de su cruel marido y la pérfida amante.', '/l1inNGjMJFyKQBF4NEf9Omm0dPE.jpg', '/mfpEeay0jKf84zgx1wjkLnW9WyD.jpg', 6.1, 'bvDdJI9-7os', array['1001']::text[], 193, null, 'segura', null),
(20945, 'movie', 'La séptima víctima', 'La séptima víctima', 'The Seventh Victim', 1943, 'Mark Robson', 'Mary (Kim Hunter), una joven provinciana, decide ir a Nueva York para buscar a su hermana Jacqueline (Jean Brooks), que ha desaparecido. Con la ayuda de su ex marido (Tom Conway) y de un prestigioso psiquiatra, Mary descubre horrorizada que la desaparición de su hermana está relacionada con una secta satánica. (FILMAFFINITY)', '/qwBDEDDwaXNjaCr7huxkvrj8Pza.jpg', '/jbYovrQd2gHckrBmkyGCkWd6UEa.jpg', 6.4, 'P9H7rUJi7NQ', array['1001']::text[], 194, null, 'segura', null),
(27130, 'movie', 'Yo anduve con un zombi', 'Yo anduve con un zombie', 'I Walked with a Zombie', 1943, 'Jacques Tourneur', 'Vudú, zombies y magia negra se combinan en una isla misteriosa en este clásico de terror de serie B dirigido por Jacques Tourneur ("La mujer pantera"). Una producción de Val Lewton para uno de los títulos míticos del género.', '/jcM6n8tv8WHxxg32ZF4s0VvgCm7.jpg', '/bCyK6eETwA6kzxLxDDuwJ3l7Wdw.jpg', 6.8, 'R0NhhvTNND0', array['1001']::text[], 194, null, 'segura', null),
(980, 'movie', 'Incidente en Ox-Bow', 'Incidente en Ox-Bow', 'The Ox-Bow Incident', 1943, 'William A. Wellman', 'El asesinato de un ranchero rompe la aparente tranquilidad de un pueblo del oeste americano. Ausente el sheriff, los hombres del pueblo deciden formar una partida para encontrar a los culpables.', '/wEBu9jZCXSSdZjt01EVGisdnD87.jpg', '/dmmiwTfk4AraKkK8DwmrXYas5rS.jpg', 7.7, 'hKd34tmlqko', array['1001']::text[], 195, null, 'segura', null),
(21734, 'movie', 'La sombra de una duda', 'La sombra de una duda', 'Shadow of a Doubt', 1943, 'Alfred Hitchcock', 'A casa de sus familiares, en el tranquilo pueblo de Santa Rosa, llega un día el encantador tío Charlie, un seductor criminal que viaja de Filadelfia a California y al que la justicia va pisando los talones. Su sobrina Charlie, a pesar de que no sabe nada de sus actividades, no tardará en sospechar que su tío es el misterioso asesino de viudas al que la policía anda buscando.', '/kF40hCjwn5X1GbT57d2xIALeGHF.jpg', '/1p78xI6mywlqhb3tfw6oTJt7X3t.jpg', 7.5, 'd9p3xKsckgY', array['1001']::text[], 196, null, 'segura', null),
(5155, 'movie', 'Ossessione', 'Obsesión', 'Ossessione', 1943, 'Luchino Visconti', 'Giovanna (Clara Calamai) es una hermosa joven malcasada con el viejo propietario de un restaurante. Su sórdida vida cambiará con la aparición de un vagabundo que se convierte en su amante y al que inducirá a matar a su marido. Adaptación de la novela de James Cain "El cartero siempre llama dos veces".', '/dZtbu1ObXnfO0RcM5RghIrfcHQd.jpg', '/6efjJuY8dUUSmMZ3ERS4CNXEp1j.jpg', 7.5, null, array['1001']::text[], 197, null, 'segura', null),
(909, 'movie', 'Cita en San Luis', 'Cita en St. Louis', 'Meet Me in St. Louis', 1944, 'Vincente Minnelli', 'Año 1903. El matrimonio Smith, afincado en San Luis, tiene cuatro preciosas hijas. Una de ellas, Esther, de diecisiete años, se enamora de un vecino que acaba de instalarse en la ciudad. Sin embargo; la familia, y especialmente Esther, tienen un enorme disgusto cuando su padre les anuncia que deben trasladarse a vivir a Nueva York por motivos de trabajo.', '/4sF93iwhPTJ7KiiQMm6L1KxzOQX.jpg', '/fQ93o3wVSIe0dXMLTVTBHoqWwew.jpg', 7.0, 'dLNa7mp0wWo', array['1001']::text[], 198, null, 'segura', null),
(22584, 'movie', 'Tener y no tener', 'Tener y no tener', 'To Have and Have Not', 1945, 'Howard Hawks', 'Segunda Guerra Mundial. Harry Morgan y su compañero Eddie son dos marineros que están en la isla de Martinica, esperando inútilmente que algún barco los contrate. Al final, se verán obligados a trabajar para la Resistencia.', '/fJwEC7BXCWNlqNlovZXImLRhpSI.jpg', '/uYRnUnBE4kk5ocvyBckRfMAsZpJ.jpg', 7.4, '0UlUzhnehvc', array['1001']::text[], 200, null, 'segura', null),
(1939, 'movie', 'Laura', 'Laura', 'Laura', 1944, 'Otto Preminger', 'El detective Mark McPherson investiga el asesinato de Laura, una elegante y seductora mujer que aparece muerta en su apartamento. McPherson elabora un retrato mental de la joven a partir de las declaraciones de sus allegados. El sugestivo retrato de Laura, que cuelga de la pared de su apartamento, también le ayuda en esta tarea.', '/onzDw0Iy9RIqXnS0Yi04gtNMwdh.jpg', '/d5HjGve67GkNC9lWpzZVKSotLlT.jpg', 7.6, 'KgGtRJY516E', array['1001']::text[], 201, null, 'segura', null),
(22638, 'movie', 'Enrique V', 'Enrique V', 'The Chronicle History of King Henry the Fifth with His Battell Fought at Agincourt in France', 1944, 'Laurence Olivier', 'Guerra de los Cien Años. Tras una vida disoluta, Enrique V (1413-1422) hereda el trono de Inglaterra y toma conciencia de sus responsabilidades. En 1415 reúne un ejército de 30.000 hombres y reanuda la guerra contra los franceses. Ese mismo año los derrota en la batalla de Azincourt y, a continuación, ocupa Normandía y París.', '/2jogXpl5YZUJx8DFPsKW4c14ifv.jpg', '/zNca9BKPRMC1WtQYVJ619bqdaOZ.jpg', 6.7, 'NWzXHWzwHMM', array['1001']::text[], 202, null, 'segura', null),
(13528, 'movie', 'Luz que agoniza', 'Luz que agoniza', 'Gaslight', 1944, 'George Cukor', 'En la Inglaterra victoriana, una bella mujer (Ingrid Bergman) se casa con un famoso pianista (Charles Boyer). La felicidad desaparece cuando en la casa, donde años atrás se cometió un asesinato, la mujer empieza a oír extraños e inexplicables ruidos; mientras tanto, su marido la atormenta hasta hacerla creer que se está volviendo loca.', '/qP6fvUzqvdKioZ1IcgPPIylolJa.jpg', '/k8sH3RyFg1G4fHN0k9QNoHk8i4E.jpg', 7.5, 'pnGdlnH2BDY', array['1001']::text[], 202, null, 'segura', null),
(9797, 'movie', 'Iván el Terrible', 'Iván el Terrible', 'Иван Грозный', 1944, 'Сергей Эйзенштейн', 'Al inicio de su reinado, Iván el Terrible afronta la traición de la aristocracia e incluso de sus amigos más cercanos  mientras busca unir al pueblo ruso.', '/dfqqiPnlCt3f3tjoQn5FqFDTluJ.jpg', '/ohn9zA2dUbVuo4ajx32Em97qvMr.jpg', 7.3, 'JcJkHCihTmE', array['1001']::text[], 203, null, 'segura', null),
(996, 'movie', 'Perdición', 'Perdición', 'Double Indemnity', 1944, 'Billy Wilder', 'MacMurray es un vendedor de seguros que, en connivencia con Barbara Stanwyck, elabora un plan para asesinar al marido de ella y quedarse con el dinero de su seguro. Obra cumbre del género, uno de los ejercicios de suspense más fascinantes de todos los tiempos.', '/wiFsjxbmlyP7O8PMASPh18ftRez.jpg', '/byQdu1nzQLI9t1VeoP1xuQfru3L.jpg', 8.1, '9oxVkwB05rU', array['1001']::text[], 204, null, 'segura', null),
(1834, 'movie', 'Historia de un detective', 'Historia de un detective', 'Murder, My Sweet', 1944, 'Edward Dmytryk', 'Esta intriga policiaca narra las aventuras de Philip Marlowe, un detective privado de Los Ángeles que resuelve todo tipo de misterios. Cuando el exconvicto Moose se pone en contacto con él sobre lo que parece un caso de lo más rutinario, una serie de pistas falsas aparecen en escena acusando al protagonista de unos crímenes que no ha cometido. Sin embargo, todas las pruebas clarifican su intervención en el terrible homicidio… ¿Conseguirá Philip resolver el enrevesado enigma?', '/cHKWAR79WmObB3wIUJbMxj7JzV6.jpg', '/mIcj44rCT7TBWGV7wjMnusBbFte.jpg', 7.2, 'PHRDGxSL2o4', array['1001']::text[], 206, null, 'segura', null),
(4174, 'movie', 'Recuerda', 'Recuerda', 'Spellbound', 1945, 'Alfred Hitchcock', 'Una psiquiatra trata de ayudar al hombre que ama a resolver un asesinato enterrado en su subconsciente.', '/vd0dwEA9U4VXwatVhWi0i37XTLs.jpg', '/iDtiGyfcFx868bZKWqLOfDuXQrz.jpg', 7.4, 'HIBaGIUbXqI', array['1001']::text[], 207, null, 'segura', null),
(84701, 'movie', 'The Battle of San Pietro', 'The Battle of San Pietro', 'The Battle of San Pietro', 1945, 'John Huston', 'Esta película documental trata sobre la batalla de San Pietro, un pequeño pueblo de Italia. Más de 1.100 soldados estadounidenses murieron al intentar tomar este lugar, que bloqueó el camino de las fuerzas aliadas de los alemanes.', '/8JmUoqqdHKfbMUcRKHdca5x6fIU.jpg', '/ziDIqBWRSWtP13YkRvCfoGBCTWb.jpg', 6.1, null, array['1001']::text[], 207, null, 'segura', null),
(3309, 'movie', 'Alma en suplicio', 'Alma en suplicio', 'Mildred Pierce', 1945, 'Michael Curtiz', 'Tras el abandono de su marido, Mildred Pierce demuestra que puede llevar una vida independiente, pero no logra ganarse la aprobación de su hija consentida.', '/tgda61QeFb67YG4G6lpSYy7Op1H.jpg', '/iWAijx2874J0QgNVXwqW24IMRai.jpg', 7.6, 'KoOr_OoHbv4', array['1001']::text[], 208, null, 'segura', null),
(2457, 'movie', 'Les enfants du paradis', 'Los niños del paraíso', 'Les Enfants du Paradis', 1945, 'Marcel Carné', 'París, 1820. Dos jóvenes artistas, Baptiste Debureau y Frédéric Lemâitre, debutan en el teatro de los Funámbulos y entablan amistad. Un día, Garance, una misteriosa y atractiva mujer, irrumpe en sus vidas. Mientras que el tímido Baptiste no se atreve a declararle su amor, Frédéric la convierte en su amante. Sin embargo, al estar implicada en una serie de crímenes, la mujer desaparece.', '/5JdJCE93pWWx34UtHg62fj2qJ9g.jpg', '/ubERa5VEJlBRglxDSBSL0YBG7XB.jpg', 8.0, 'GfqRRYDLKS8', array['1001']::text[], 210, null, 'segura', null),
(307, 'movie', 'Roma, ciudad abierta', 'Roma. Ciudad abierta', 'Roma città aperta', 1945, 'Roberto Rossellini', 'Segunda Guerra Mundial (1939-1945). Estando Roma ocupada por los nazis, la temible Gestapo trata de arrestar a Manfredi, el líder del Comité Nacional de Liberación. Annie Marie ofrece refugio en su casa a Manfredi y a algunos de sus camaradas, pero los alemanes descubren su escondrijo y rodean la vivienda; algunos partisanos consiguen escapar por los tejados, pero Manfredi es apresado.', '/mgBiTwHjd9ILQXUCSS4v3eAaCIu.jpg', '/tt1YwEB5UVDKxCYwZEtpNUaDJIi.jpg', 8.0, '5uzXxXnGfVs', array['1001']::text[], 211, null, 'segura', null),
(28580, 'movie', 'Días sin huella', 'Días sin huella', 'The Lost Weekend', 1945, 'Billy Wilder', 'Don Birnam es un escritor fracasado a causa de su adicción al alcohol, adicción que lo ha destruido física y moralmente y lo ha convertido en un hombre desprovisto de voluntad. Con tal de seguir bebiendo es capaz de todo, incluso de robar. Tanto su novia como su hermano intentan por todos los medios regenerarlo, pero sus esfuerzos parecen estériles.', '/kNXR9S1XJ89EuAZnirDC8SVhI8y.jpg', '/vyINER8nv4kAJyCIq2Sr1xjOOjC.jpg', 7.6, 'eVb2LVcDfTQ', array['1001']::text[], 212, null, 'segura', null),
(20367, 'movie', 'El desvío', 'Desvío', 'Detour', 1945, 'Edgar G. Ulmer', 'La vida de Al Roberts, pianista en un club nocturno de Nueva York, se convierte en una pesadilla cuando decide hacer autostop hasta Los Ángeles para visitar a su novia.', '/gJb9HRAs1V4bA0VKsWpT6mhv2RT.jpg', '/uGOKN4VeCsf249zypWfaAzfTxAB.jpg', 7.2, 'iXnwMbC_bmQ', array['1001']::text[], 214, null, 'segura', null),
(56137, 'movie', 'I Know Where I''m Going!', 'Sé a dónde voy', 'I Know Where I''m Going!', 1945, 'Michael Powell, Emeric Pressburger', 'Joan siempre supo lo que quería desde que era una niña. Ahora está a punto de casarse con un millonario, pero las fuerzas de la naturaleza parecerán conspirar para que cambie de idea. (FILMAFFINITY)', '/woAOLgYVUmLBtWNxTJgAnqGwyuL.jpg', '/nDfHT9HvEyRFrjctodwqxZ7Yuem.jpg', 7.1, 'EVXs_bUXQ_8', array['1001']::text[], 214, null, 'segura', null),
(887, 'movie', 'Los mejores años de nuestra vida', 'Los mejores años de nuestra vida', 'The Best Years of Our Lives', 1946, 'William Wyler', 'Tras la Segunda Guerra Mundial (1939-1945), los soldados supervivientes, algunos con taras físicas, regresan a los Estados Unidos. Aunque al principio se les trata como héroes, poco tiempo después comienzan a verse marginados.', '/go8vB0DsCStVvr6vc1kv8LVmEep.jpg', '/n0og4mDtl08x9RLTWXt8zUKpqXQ.jpg', 7.7, 'X9lufYAOxes', array['1001']::text[], 215, null, 'segura', null),
(851, 'movie', 'Breve encuentro', 'Breve encuentro', 'Brief Encounter', 1945, 'David Lean', 'La casualidad hace que un hombre y una mujer ambos de edad madura y casados coincidan en una estación de tren. Su inicial amistad pronto se convertirá en un amor tan intenso como prohibido.', '/5ZJ7OrWNUdcgF4NnVX0xlkh1sTJ.jpg', '/vKvoOlhhaZCsiGQDvaZQqyGq1oA.jpg', 7.7, 'TtIN_HQHBdA', array['1001']::text[], 216, null, 'segura', null),
(25736, 'movie', 'El cartero siempre llama dos veces', 'El cartero siempre llama dos veces', 'The Postman Always Rings Twice', 1946, 'Tay Garnett', 'Durante la Gran Depresión, Frank Chambers, un hombre sin rumbo, comienza a trabajar en un bar de carretera, regentado por un hombre mayor y por Cora, su joven, bella e infeliz esposa.', '/vWr9h9Gt2KQHyRlRuF7oxMCdZXN.jpg', '/cXkA9CqkZyWufwPE0GSVj1SFwUW.jpg', 7.1, 'n2R4I84QS5M', array['1001']::text[], 217, null, 'segura', null),
(8429, 'movie', 'Paisà', 'Paisà (Camarada)', 'Paisà', 1946, 'Roberto Rossellini', 'Seis episodios independientes con el nexo común del avance de las tropas aliadas en Italia durante la Segunda Guerra Mundial.', '/4e931gfu6mqjA7iv0arOOxXToH9.jpg', '/zNjp6eolIcpGx11tDbE5eekeHEG.jpg', 7.5, 'JM_KpDmdF98', array['1001']::text[], 217, null, 'segura', null),
(3088, 'movie', 'Pasión de los fuertes', 'Pasión de los fuertes', 'My Darling Clementine', 1946, 'John Ford', 'A Wyatt Earp (Henry Fonda), antiguo sheriff de Dodge City, le ofrecen el puesto de comisario de la ciudad de Tombstone, pero lo rechaza porque le interesa más el negocio ganadero al que se dedica con sus hermanos. Sin embargo, cuando uno de ellos muere asesinado, acepta el puesto vacante y nombra ayudantes a sus hermanos. Contará también con la amistad y la colaboración de un jugador y pistolero llamado Doc Holliday (Victor Mature).', '/br9dcOFBM9hSZYZ4NPgooPMYfQy.jpg', '/q4OPVRS5a55BOcUtGcQh81Idsgt.jpg', 7.5, '2aF5QQoGgCE', array['1001']::text[], 218, null, 'segura', null),
(20246, 'movie', 'El extraño', 'El extraño', 'The Stranger', 1946, 'Orson Welles', 'Wilson, un agente de la comisión de crímenes de guerra, está buscando a Franz Kindler, uno de los cerebros de los campos de exterminio nazis, que ha conseguido huir sin dejar huellas. Siguiendo la pista de un antiguo camarada de Kindler llega hasta Harper (Connecticut), donde es asesinado antes de poder identificar al fugitivo. La única pista que le queda es la fascinación del criminal nazi por los relojes antiguos.', '/dCye4ohkdcIhbTH752gPKIpoQ5Q.jpg', '/osCupz9uxvUoca6aqSSkns1UnlQ.jpg', 7.2, 'ZbiLI6gfAiw', array['1001']::text[], 220, null, 'segura', null),
(648, 'movie', 'La bella y la bestia', 'La bella y la bestia', 'La Belle et la Bête', 1946, 'Jean Cocteau', 'Érase una vez un mercader arruinado que vivía con su hijo Ludovic y sus tres hijas. Dos de ellas, Felicie y Adelaide, son seres egoístas que explotan a su hermana pequeña Bella. Un día, el padre se pierde en el bosque y llega hasta un castillo. Allí encuentra una preciosa rosa y decide cogerla para Bella, entonces aparece el señor del castillo que le impondrá un duro castigo por su osadía.', '/yKeUh1AV24vueIyL6xozgS8frmo.jpg', '/2Ae0iV2HR3Raoras8G40MjBtJnn.jpg', 7.5, 'IsXkv1mpRUk', array['1001']::text[], 221, null, 'segura', null),
(910, 'movie', 'El sueño eterno', 'El sueño eterno', 'The Big Sleep', 1946, 'Howard Hawks', 'El detective Philip Marlowe  investiga qué ha ocurrido con un cadáver que ha sido rescatado en el muelle Lido. La familia que le ha contratado para resolver el caso tiene una hija muy atractiva de la que Marlowe se enamora sin remisión.', '/hkKuvY7u4cOFF3nfCSLewVKGRai.jpg', '/yxMgxS0NlmkG5RhatQE8MUjxT2C.jpg', 7.6, 'n-K49CUaeto', array['1001']::text[], 222, null, 'segura', null),
(28162, 'movie', 'A vida o muerte', 'A vida o muerte', 'A Matter of Life and Death', 1946, 'Emeric Pressburger, Michael Powell', 'El aviador británico Peter Carter, en su avión en llamas y a punto de estrellarse se enamora de la voz femenina que contesta a su mensaje de socorro. Parece que se ha salvado milagrosamente y encuentra a su interlocutora. Pero un enviado del más allá le notifica que está entre la vida y la muerte y que si quiere sobrevivir, tendrá que defender su caso ante un tribunal celestial. Simultaneamente a esta situación sobrenatural, un equipo de médicos lucha en el quirófano para curar a Peter una lesión en el cerebro.', '/c2Hs2NRkPJtnt7eA2VY6TOSGUyW.jpg', '/bY7DvsYsAODykqUJfkPZA3BHKOd.jpg', 7.7, 'S0veuSLLWZ0', array['1001']::text[], 223, null, 'segura', null),
(14638, 'movie', 'Forajidos', 'Forajidos', 'The Killers', 1946, 'Robert Siodmak', 'Una vez terminada la Segunda Guerra Mundial (1939-1945), Swede Lunn, un soldado veterano y boxeador en declive, encuentra dificultades para reincorporarse a la vida civil. Un día conoce a la novia de un gángster, la irresistible y misteriosa Kitty Collins.', '/ojf6epFQIfETydOPmGvSZB4GyFN.jpg', '/w6XdWl6L2WDHJGw2FKySbi86WDg.jpg', 7.4, 'Cq_gxqCaFms', array['1001']::text[], 223, null, 'segura', null),
(14320, 'movie', 'Cadenas rotas', 'Cadenas rotas', 'Great Expectations', 1946, 'David Lean', 'Adaptación de la novela "Grandes esperanzas" de Charles Dickens. El hijo de un humilde herrero es enviado a educarse a Londres gracias al dinero de un benefactor cuya identidad desconoce.', '/gUurlaJpyQLAgpkNTBKwJhNFWs.jpg', '/5SdVucbeGF5xAHT496uPRPZVJD6.jpg', 7.3, 'ueGOsCoG5b8', array['1001']::text[], 224, null, 'segura', null),
(303, 'movie', 'Encadenados', 'Encadenados', 'Notorious', 1946, 'Alfred Hitchcock', 'Tras la Segunda Guerra Mundial (1939-1945), el padre de Alicia Huberman, un espía nazi, es condenado por traición contra los Estados Unidos. Después del juicio, Alicia da una fiesta en la que aparece un apuesto desconocido llamado Devlin. Se trata de un agente de los servicios de Inteligencia que reclama su colaboración para atrapar a Alexander Sebastian, el cerebro de los nazis en Brasil. Al principio se muestra reacia, pero finalmente accede, sobre todo, porque se ha enamorado del atractivo agente americano. Una vez en Brasil, Alicia se gana la simpatía de Sebastian y se va a vivir a su casa. Pero su implicación en el asunto acaba poniendo en peligro su vida.', '/gHI8XPXkMspTIly1TcHAEHQo63A.jpg', '/6jRd6vT3NhwIeyqaiWCYzi64lSP.jpg', 7.7, 'H8f4UOtLf5Q', array['1001']::text[], 226, null, 'segura', null),
(16391, 'movie', 'Narciso negro', 'Narciso negro', 'Black Narcissus', 1947, 'Emeric Pressburger, Michael Powell', 'Un grupo de monjas occidentales abre un hospital en un antiquísimo templo del Himalaya. A las dificultades económicas y a la hostilidad de los nativos, pronto se suman las tensiones entre las propias monjas. Un agente británico intentará mediar entre ellas para solucionar sus problemas, pero su presencia acabará despertando, con consecuencias fatales, la sexualidad reprimida de algunas hermanas.', '/aUmLauQIQa2vkjjnlx7aeMozMZG.jpg', '/hAyWibhJjMHyWXrMVX8N2MrEqF8.jpg', 7.5, 'o7HQnwnUl1I', array['1001']::text[], 227, null, 'segura', null),
(1585, 'movie', 'Qué bello es vivir', '¡Qué bello es vivir!', 'It''s a Wonderful Life', 1946, 'Frank Capra', 'George Bailey es un honrado y modesto ciudadano que dirige y mantiene a flote un pequeño banco familiar, a pesar de los intentos de un poderoso banquero por arruinarlo. El dia de Nochebuena de 1945, abrumado por la repentina desaparición de una importante suma de dinero, que supondría no solo la quiebra de su banco sino también un gran escándalo, decide suicidarse, pero cuando está a punto de hacerlo ocurre algo extraordinario.', '/63W4MsB8e5whhPNyxhRVTzSsCje.jpg', '/ch3lDc4xQ9MpsNEpnRhvR8PIxxK.jpg', 8.3, 'iLR3gZrU2Xo', array['1001']::text[], 228, null, 'segura', null),
(3767, 'movie', 'Gilda', 'Gilda', 'Gilda', 1946, 'Charles Vidor', 'Johnny Farrell, un aventurero que vive de hacer trampas en el juego, recala en Buenos Aires. Allí le saca de un apuro un hombre llamado Ballin Mundson, propietario de un lujoso casino. El recién llegado termina convirtiéndose en el individuo de confianza de su anfitrión. Un día, su superior le presenta a su esposa, Gilda. Él reacciona con perplejidad, ya que ella lo convirtió en el ser amargado y cínico que es ahora.', '/zTYrR5zXBCtWPsBLg8QU1rSp1ii.jpg', '/2oQ9hnAYsoZH61PnjSkuX4Uvd2d.jpg', 7.5, '9hTdgygrlOg', array['1001']::text[], 230, null, 'segura', null),
(30588, 'movie', 'Monsieur Verdoux', 'Monsieur Verdoux', 'Monsieur Verdoux', 1947, 'Charlie Chaplin', 'Basada en hechos reales, esta obra maestra del genio Chaplin cuenta la historia de Henri Verdoux, un hombre de doble vida. Por un lado es un respetable hombre casado padre de un hijo, pero por otro es un seductor que, bajo otra identidad, se dedica a casarse con viudas ricas a las que posteriormente asesina para quedarse con su fortuna.', '/bqk56Z7Y8IiPNAMRflUl3FDxkrE.jpg', '/pXAudXOkmQSiI6sFQyEfkibQxZp.jpg', 7.7, 'eND72dzh7EU', array['1001']::text[], 230, null, 'segura', null),
(678, 'movie', 'Retorno al pasado', 'Retorno al pasado', 'Out of the Past', 1947, 'Jacques Tourneur', 'Jeff Bailey, un antiguo detective, regenta una gasolinera en un pequeño pueblo, donde lleva una vida tranquila y sencilla. Sus amores son la pesca y una jovencita con la que quiere casarse. Inesperadamente, recibe la visita de un viejo conocido que le anuncia que el jefe quiere verlo. Bailey se ve entonces obligado a contarle a su novia su turbio pasado.', '/lVrSynBqsFZVKbRKaaP0YQW2ccg.jpg', '/9qGWOflC5WNhaKk2UPYu55SjjNj.jpg', 7.7, 'tLMHIPMQmsM', array['1001']::text[], 231, null, 'segura', null),
(22292, 'movie', 'El fantasma y la señora Muir', 'El fantasma y la señora Muir', 'The Ghost and Mrs. Muir', 1947, 'Joseph L. Mankiewicz', 'Lucy Muir es una joven viuda que decide irse a vivir a orillas del mar, a una casa encantada que perteneció al capitán Gegg, un marinero cuyo fantasma se le aparece. Al principio, el capitán utiliza los mismos trucos que le sirvieron para librarse de otros inquilinos, pero con Lucy no funcionan.', '/t88Pgtl4tC6Dki0GNfT58QhgjUq.jpg', '/m1QTfbKD90j63Gh9bOJt0g67LvA.jpg', 7.5, 'n-X00-BoG9o', array['1001']::text[], 232, null, 'segura', null),
(43461, 'movie', 'Larga es la noche', 'Larga es la noche', 'Odd Man Out', 1947, 'Carol Reed', 'Irlanda, principios del siglo XX. Johnny McQueen es uno de los militantes más importantes del Sinn Fein, el brazo político del IRA (1905), cuyo objetivo es la independencia de Irlanda. La necesidad de conseguir fondos para financiar la lucha armada lo lleva a elaborar un plan para atracar un banco.', '/opROmwYB7AQYCaj0PyJ8pNnsHK7.jpg', '/eb4aHemLxnyjqTqPNAQA0q1oyCw.jpg', 7.3, 'EsLLfuNOvws', array['1001']::text[], 232, null, 'segura', null),
(5156, 'movie', 'Ladrón de bicicletas', 'Ladrón de bicicletas', 'Ladri di biciclette', 1948, 'Vittorio De Sica', 'En la Roma de posguerra, a un hombre le roban la bicicleta que necesita para trabajar. Junto a su hijo recorre la ciudad buscándola.', '/hjo6BPzCuhUkpSzxElOQ68mydrx.jpg', '/kTUUiKGKrdRhJsCcYT3Ivtfuuzh.jpg', 8.2, '1gngh-jQRpU', array['1001','clasicos']::text[], 233, null, 'segura', null),
(946, 'movie', 'Carta de una desconocida', 'Carta de una desconocida', 'Letter from an Unknown Woman', 1948, 'Max Ophüls', 'Un célebre pianista en el ocaso de su carrera, recibe un día una carta de una joven desconocida, Lisa Berndle, que le revela el amor que ha sentido por él en secreto desde la infancia. En ella le recuerda los pocos encuentros que han tenido y le comunica que, de ellos, nació un hijo, que murió de tifus siendo muy niño. También le cuenta que se casó con un diplomático, sin esconderle que su corazón estaba en otro lugar y que esta carta la está escribiendo en su lecho de muerte. En ese momento el pianista comprende por qué, el día anterior, le ha retado a duelo un diplomático vienés.', '/pW0Qv5ku8UoCCoNqESirzUuziA0.jpg', '/7amSQSipxgiQnEejWX6iQonFrZI.jpg', 7.8, 'lOtmlrHJfRU', array['1001']::text[], 234, null, 'segura', null),
(560, 'movie', 'Secreto tras la puerta', 'Secreto tras la puerta', 'Secret Beyond the Door', 1947, 'Fritz Lang', 'Celia, una rica heredera, conoce a Mark, un hombre atractivo y misterioso, se enamoran y pocos días después se casan. A medida que Celia va conociendo la vida de su marido, empieza a sospechar que oculta secretos que ella ni siquiera puede imaginar.', '/uVBEwjzXweHWjCFjAs7eJzH9in6.jpg', '/xMZJwdGMDEQWKavwMWB4Lpkuixg.jpg', 6.5, 'XmmgLoa6FNA', array['1001']::text[], 236, null, 'segura', null),
(26744, 'movie', 'La fuerza del destino', 'La fuerza del destino', 'Force of Evil', 1950, 'Abraham Polonsky', 'Joe Morse trabaja como abogado para Ben Tucker, un hombre que se ha enriquecido gracias a un negocio ilegal de apuestas. Para asegurar y ampliar sus maniobras necesitan dar un golpe que implique la desaparición de todos los pequeños bancos de apuestas clandestinos. Uno de ellos esta dirigido por el hermano de Joe Morse.', '/x33LVKf4yWdjMeczJkzE5sIw4VG.jpg', '/mo0NlwRLaV8DBUi6Tdn0ymIHe7K.jpg', 6.7, 'mL5HOk2TvPs', array['1001']::text[], 237, null, 'segura', null),
(21058, 'movie', 'Primavera en una pequeña ciudad (Xiao cheng zhi chun)', 'Primavera en un pequeño pueblo', '小城之春', 1948, 'Mu Fei', 'Tras ocho años de matrimonio con Liyan -anteriormente rico, pero ahora una sombra de sí mismo tras una larga y ruinosa guerra-, Yuwen apenas hace otra cosa que comprar víveres y medicamentos. Una visita sorpresa de Zhang, amigo de Liyan, revitaliza el hogar, pero también despierta sentimientos y resentimientos reprimidos durante mucho tiempo.', '/eCtv3xw44b3eUE2LGTgmfmQopKf.jpg', '/cr5fnofjFTKoUwgbyHzeZdkYMz4.jpg', 7.2, 'LiFkrKUbBd0', array['1001']::text[], 237, null, 'probable', '[{"tmdb_id": 21058, "titulo": "Spring in a Small Town", "original": "小城之春", "anio": 1948, "votos": 109, "poster_path": "/kRiHwa1p7FDkPBxjjFNMY8pjc1f.jpg", "sim": 0.341}]'::jsonb),
(3089, 'movie', 'Río Rojo', 'Río Rojo', 'Red River', 1948, 'Howard Hawks', 'Terminada la Guerra de Secesión (1861-1865) y después de haber sobrevivido a una matanza de los indios, el ganadero Tom Dunson (John Wayne) y su hijo adoptivo Matthew Garth (Montgomery Clift) proyectan trasladar diez mil cabezas de ganado desde Texas hasta Missouri. Nadie hasta entonces había intentado una operación de tal envergadura.', '/h3MNyRAce1QRdOuGT867xfkX7Zk.jpg', '/jnwIO4HasO9APdBaGeMcZi0JFXs.jpg', 7.3, 'ZxVCrIMPQXI', array['1001']::text[], 238, null, 'segura', null),
(1580, 'movie', 'La soga', 'La soga', 'Rope', 1948, 'Alfred Hitchcock', 'A casa de dos estudiantes van llegando los invitados a una especie de fiesta de fin de curso. El invitado que más temen es su tutor y profesor, un astuto criminólogo que sostiene que el crimen perfecto no existe, aunque ellos se han propuesto demostrar lo contrario. En efecto, con su llegada crece cada vez más la tensión y el nerviosismo de los jóvenes. Y no es para menos, porque tienen un cadáver encerrado en el arcón que sirve de mesa para la cena. Cuando, al final de la fiesta, profesor y alumnos se quedan solos, los errores y contradicciones en que éstos incurren son tales que el profesor empieza a comprender que han asesinado al joven invitado que han estado esperando en vano toda la noche.', '/25ScofCCdU4XtkiGv8nhbZ7nIX5.jpg', '/81LX4wktTXWEXjLNlkHTmJm7tRu.jpg', 7.9, 'mTmEraaEY20', array['1001']::text[], 239, null, 'segura', null),
(3766, 'movie', 'La dama de Shangai', 'La dama de Shanghai', 'The Lady from Shanghai', 1947, 'Orson Welles', 'Michael O''Hara (Orson Welles), un marinero irlandés, entra a trabajar en un yate a las órdenes de un inválido casado con una mujer fatal (Rita Hayworth) y queda atrapado en una maraña de intrigas y asesinatos.', '/uW5BCzJuYVgoSvQOC0bIYevUpXX.jpg', '/ehgX2eTBOgqB1Py3vSTKf3LXbEv.jpg', 7.3, 'il2aAU6LuXw', array['1001']::text[], 240, null, 'segura', null),
(62694, 'movie', 'Nido de víboras', 'Nido de víboras', 'The Snake Pit', 1948, 'Anatole Litvak', 'Una escritora recién casada acaba internada en un psiquiátrico debido a un recuerdo que le atormenta. El trato recibido en el hospital no hace sino empeorar su estado mental.', '/xanUC7cUMdCp6jcE8jZjc5r7C1w.jpg', '/xyPp8XpOozFfpZmYSlz0h9SpOpO.jpg', 7.1, '1CBLJoNETqU', array['1001']::text[], 240, null, 'segura', null),
(17804, 'movie', 'Rostro pálido', 'Rostro pálido', 'The Paleface', 1948, 'Norman Z. McLeod', 'Bob Hope es un nervioso dentista que se convierte en pistolero cuando se casa con Calamity Jane (Jane Russell), una mujer aficionada a crear problemas y que en realidad trabaja para el gobierno. (FILMAFFINITY)', '/nQxDVxEUSGyTtMHNUrVLAbIJBLH.jpg', '/dm8dfILA11OYR0usqQGJJZQMw93.jpg', 6.1, 'MbRVX3LT_g4', array['1001']::text[], 241, null, 'segura', null),
(19542, 'movie', 'Las zapatillas rojas', 'Las zapatillas rojas', 'The Red Shoes', 1948, 'Emeric Pressburger, Michael Powell', 'Drama ambientado en el mundo del ballet que trata sobre los sacrificios realizados para alcanzar el éxito profesional. Un empresario obliga a una bailarina a anteponer su carrera al amor.', '/5RZH2gXSFTWHvVTe2k5zQF6yKqi.jpg', '/Aa1jUhkenqspgGQlqbsXFax6iW.jpg', 8.0, '_mHgGU4AbOA', array['1001']::text[], 242, null, 'segura', null),
(3090, 'movie', 'El tesoro de Sierra Madre', 'El tesoro de Sierra Madre', 'The Treasure of the Sierra Madre', 1948, 'John Huston', 'Fred C. Dobbs (Humphrey Bogart) decide ir a Tampico en busca de oro con la intención de dejar atrás la miseria. Emprende el viaje en compañía de otros dos vagabundos (Walter Huston y Tim Holt), pero la codicia y la envidia que surge entre ellos les creará poco a poco más problemas que cualquier otra dificultad del camino.', '/6K9oljorPmH0UVxUdACazNBuAlg.jpg', '/osytHgkv86CTFKxo46l9P7ACEjm.jpg', 8.0, '1DwXNmorsa0', array['1001']::text[], 244, null, 'segura', null),
(70447, 'movie', 'Louisiana Story', 'Louisiana Story', 'Louisiana Story', 1948, 'Robert Flaherty', 'Cajun boy Alexander Napoleon Ulysses LaTour lives with his family and his beloved pet raccoon in the Louisiana bayou. When his father allows an oil barge to drill on their land, the boy questions the process and its safety.', '/kwEbsHAvdY9G2gJKRKYmxJ6IB6L.jpg', '/f5z01S7J9st1zUYLSocBUGqYpBK.jpg', 6.3, null, array['1001']::text[], 245, null, 'segura', null),
(28571, 'movie', 'La heredera', 'La heredera', 'The Heiress', 1949, 'William Wyler', 'Año 1849, en Nueva York. Catherine Sloper, una rica heredera, tímida, inocente, poco agraciada y no muy joven, es pretendida por un apuesto joven. Ella se enamora de él apasionadamente, pero su cruel y despótico padre se opone a la boda y amenaza con desheredarla...', '/aWERWFlHbr2X7rTGnaEmkcowx58.jpg', '/56eHAxXfZTz5pGiVDCFnuiHw2fp.jpg', 7.8, 'ltjOydHAO0M', array['1001']::text[], 246, null, 'segura', null),
(11898, 'movie', 'Ocho sentencias de muerte', 'Ocho sentencias de muerte', 'Kind Hearts and Coronets', 1949, 'Robert Hamer', 'Un joven ambicioso y sin escrúpulos (Dennis Price) proyecta vengar la afrenta que la aristocrática familia D''Ascoyne, a la cual pertenece, les ha infligido a él y a su madre. El plan consiste en eliminar a todos los miembros de la familia que le preceden en la sucesión al título de Duque.', '/fM27q6W6YAPUwJM0ApeE8vMtoWT.jpg', '/r7jtS16I3vgVvqapgCa7RMkZnvj.jpg', 7.6, 'fVli0y9bQoA', array['1001']::text[], 247, null, 'segura', null),
(18671, 'movie', 'El demonio de las armas', 'El demonio de las armas', 'Gun Crazy', 1950, 'Joseph H. Lewis', 'Bart Tare, un veterano de la Segunda Guerra Mundial (1939-1945), es un hombre emocionalmente desequilibrado que desde que era niño vive obsesionado con las armas. Cuando conoce a Annie, una mujer fatal, se deja arrastrar al mundo del crimen. Unidos por su afición a las armas, la relación de la pareja desemboca, entre atraco y atraco, en un torbellino de pasiones y situaciones peligrosas.', '/d8nwLaIrvG8DyR0LxpsTixDZCU6.jpg', '/eR9S6iMbk4ycV7DcqvVxFp8lNFV.jpg', 7.4, 'BD9Wn_Nr3qU', array['1001']::text[], 248, null, 'segura', null),
(25431, 'movie', 'La costilla de Adán', 'La costilla de Adán', 'Adam''s Rib', 1949, 'George Cukor', 'Amanda y Adam Bonner son un idílico matrimonio de abogados cuya paz conyugal se ve afectada cuando un caso los enfrenta en los tribunales como defensora y fiscal respectivamente: una mujer es juzgada por disparar contra su marido y la amante de éste. Adam no duda de la culpabilidad de la acusada, pero Amanda no es de la misma opinión.', '/aasp2GhdZzdjSImCLO7u9EL6MED.jpg', '/q9bDTKlHh5nURBo4VS0cVa0x4E1.jpg', 7.1, 'tQ5NpJ81AY4', array['1001']::text[], 249, null, 'segura', null),
(16665, 'movie', 'Whisky Galore', 'Whisky a gogó', 'Whisky Galore!', 1949, 'Alexander Mackendrick', 'Durante la II Guerra Mundial (1939-1945), un barco cargado de whisky naufraga en una isla de Escocia. Los isleños, que no han podido beber alcohol desde hace tiempo, empiezan a idear toda clase de estratagemas para burlar a las autoridades y apoderarse del cargamento.', '/1fE55Q3meuH7gSYesgpYpzqNj4w.jpg', '/y1siOoSCQ4oLBo05F3STFia7tVb.jpg', 6.8, 'THriYNnq7iQ', array['1001']::text[], 250, null, 'segura', null),
(15794, 'movie', 'Al rojo vivo', 'Al rojo vivo', 'White Heat', 1949, 'Raoul Walsh', 'Cody Jarrett y su banda asaltan un tren que transporta 300.000 dólares, asesinan a los conductores y huyen con el dinero. Poco después, los agentes federales inician la persecución, convencidos de que él es el autor del asalto. Cody se entrega a la policía y es condenado a sólo dos años de prisión, ya que ha preparado una coartada perfecta. Sin embargo, los agentes del tesoro están convencidos de que fue el cerebro del asalto y le tienden una trampa.', '/ih5QqEMXE6UwrbGEjRFGIcGri83.jpg', '/cap8458wFeRCJSKxL758dI82TRK.jpg', 7.7, '3bMtOABixrQ', array['1001']::text[], 251, null, 'segura', null),
(28007, 'movie', 'Almas desnudas', 'Almas desnudas', 'The Reckless Moment', 1949, 'Max Ophüls', 'Cuando descubre el cuerpo sin vida del amante de su hija, Lucia Harper decide esconderlo porque sospecha que la autora del crimen es su propia hija.', '/lP94jKA49lPful5xyUxg5lizVsH.jpg', '/c0gCHnvEqurJAbmp4Pk2kuUH2a6.jpg', 6.8, null, array['1001']::text[], 251, null, 'segura', null),
(1092, 'movie', 'El tercer hombre', 'El tercer hombre', 'The Third Man', 1949, 'Carol Reed', 'Orson Welles es Harry Lime y Joseph Cotten actúa como su amigo de la infancia, Holly Martins, en este clásico thriller de Graham Greene, dirigido por Carol Reed. Martins busca a Lime en la caótica postguerra de Viena, y se encuentra así mismo metido en un entorno de amores, decepción y asesinatos.', '/trsJPVYVnZMPhBrFhAx0jPEVrqa.jpg', '/rLLhOCgAjuvlKmjUqVb7P1UAbUI.jpg', 7.9, 'Y7nwySBGqCo', array['1001']::text[], 252, null, 'segura', null),
(31516, 'movie', 'Un día en Nueva York', 'Un día en Nueva York', 'On the Town', 1949, 'Stanley Donen, Gene Kelly', 'Tres marineros que gozan de un permiso de veinticuatro horas en New York aprovechan para conocer la ciudad y arreglar algunos asuntos pendientes. También quieren divertirse, y conocen a tres chicas que les hacen perder la cabeza.', '/bhVcoc82gpLOcfCRgwngfMxZ6cL.jpg', '/otY1rdFZ9XNsacvZHis9EkaxdnJ.jpg', 7.0, 'ri4OegFn3Jk', array['1001']::text[], 254, null, 'segura', null),
(16958, 'movie', 'La jungla de asfalto', 'La jungla de asfalto', 'The Asphalt Jungle', 1950, 'John Huston', 'La meticulosa planificación de un atraco a una joyería por parte de una banda de delincuentes le sirve a Huston para ofrecer un poderoso relato lleno de intensidad, amén de un realista e insuperable estudio de personajes y sus motivaciones. Sin lugar a dudas, una de los mejores películas del cine negro de todos los tiempos, con el gran Hayden y una seductora y sexy Marilyn Monroe.', '/7wBKTnTetx77UNy84ZlNqRzooF4.jpg', '/pDGkMdMHkl1qRAYmQjdLKVx3euQ.jpg', 7.5, 'tiH8mOrCNSI', array['1001']::text[], 255, null, 'segura', null),
(4558, 'movie', 'Orfeo', 'Orfeo', 'Orphée', 1950, 'Jean Cocteau', 'Orfeo es un poeta obsesionado con la Muerte (la Princesa) de la cual se enamora. Un día los esbirros de la Muerte matan a Eurídice, la esposa de Orfeo, y éste decide seguirla hasta el Inframundo para rescatarla.  Este film es la parte central de la trilogía órfica de Jean Cocteau: La sangre de un poeta (1932), Orfeo (1950) y El testamento de Orfeo (1960).', '/fmybmlklClrRIV6pK0ucuGGRYrn.jpg', '/zoWSiV6GZ7EJsEOnpyekJE1ceB1.jpg', 7.7, '9ciOWebRF3Y', array['1001']::text[], 255, null, 'segura', null),
(548, 'movie', 'Rashomon', 'Rashomon', '羅生門', 1950, 'Akira Kurosawa', 'Japón, siglo XII. En Kioto, bajo las puertas del derruido templo de Rashomon, se guarecen de la torrencial lluvia un leñador, un sacerdote budista y un peregrino. Los tres discuten sobre el juicio a un bandido, acusado de haber dado muerte a un señor feudal y violado a su esposa. Los detalles del crimen son narrados desde el punto de vista del bandido, de la mujer, del señor feudal -con la ayuda de un médium- y del leñador, único testigo de los hechos.', '/hTzw4ectHlJw1gZciFNsemTPARM.jpg', '/tDn1dA52bQH9B85vilHeU7C83W1.jpg', 8.0, 'L2E_DfExUmU', array['1001']::text[], 256, null, 'segura', null),
(11617, 'movie', 'Río Grande', 'Río Grande', 'Rio Grande', 1950, 'John Ford', 'El Coronel York combate a los apaches desde su fuerte cercano a la frontera con México. Su hijo, que ha fracasado en West Pont, se alista a su regimiento. Dispuesta a sacarlo de allí, también llega al fuerte la esposa de York. Es el reencuentro del matrimonio tras muchos años de separación. En medio de un agrio conflicto familiar, la lucha contra los indios se recrudece.', '/hQFicdajnGWn8bLrjGmLMbbkaf.jpg', '/bcZUdS133kwngC8CXJHD6sRAHDt.jpg', 6.8, 'oo7CHY544HY', array['1001']::text[], 258, null, 'segura', null),
(14551, 'movie', 'Winchester 73', 'Winchester 73', 'Winchester ''73', 1950, 'Anthony Mann', 'Dos jinetes llegan a Dodge City persiguiendo a un hombre. Es el Día de la Independencia, y la gente se arremolina en torno al premio del concurso de tiro, un rifle único: el Winchester 73. Lin McAdam, uno de los forasteros, gana el concurso y consigue el rifle, pero su contrincante Dutch Henry Brown se lo roba y huye. El rifle pasa a manos de un traficante de armas, luego a un jefe indio y más tarde a un forajido. Mientras tanto, continúa la persecución.', '/rOUQOJ0VR4MJwArDP3BJ8BMe757.jpg', '/f9dWvVRwJEcsK7PxCONRAl1DcZe.jpg', 7.3, 'eb7xOnMX1Qw', array['1001']::text[], 258, null, 'segura', null),
(705, 'movie', 'Eva al desnudo', 'Eva al desnudo', 'All About Eve', 1950, 'Joseph L. Mankiewicz', 'Una joven que aspira a convertirse en actriz y triunfar en los escenarios se las ingenia para introducirse en un grupo de actores de teatro y hacerse amiga y confidente de una famosa y veterana actriz. El deseo de actuar y los celos la consumen hasta el punto de traicionar a sus compañeros en su escalada hacia el éxito. Ella halaga, atrae, seduce, pero también pisotea a todo el que se cruza en su camino: escritores, directores, productores. Sólo un inteligente crítico teatral adivina lo que se esconde tras su dulce apariencia, sólo él es capaz de ver a Eva al desnudo.', '/or4l6YmNSQlkN5QRaAFsqxd0wWX.jpg', '/zAL3LOswagN9onjN8DPcNFTqKuD.jpg', 8.1, 'MILphnfj2mo', array['1001']::text[], 259, null, 'segura', null),
(599, 'movie', 'El crepúsculo de los dioses', 'El crepúsculo de los dioses', 'Sunset Boulevard', 1950, 'Billy Wilder', 'Joe Gillis es un joven escritor de segunda fila que, acosado por sus acreedores, se refugia casualmente en la mansión de Norma Desmond, antigua estrella del cine mudo, que vive fuera de la realidad, acompañada únicamente de su fiel criado Max. A partir de ese momento, la actriz pretende que Joe corrija un guión que ella ha escrito y que va a significar su regreso al cine.', '/sVILYytrnjsEXBcZyxHMJ5jP74t.jpg', '/p47ihFj4A7EpBjmPHdTj4ipyq1S.jpg', 8.3, 'yMhVPorOZ_I', array['1001']::text[], 260, null, 'segura', null),
(800, 'movie', 'Los olvidados', 'Los olvidados', 'Los olvidados', 1950, 'Luis Buñuel', 'Un grupo de delincuentes juveniles vive una vida violenta en los infectos barrios bajos de Ciudad de México; entre ellos Pedro, cuya moralidad es gradualmente corrompida y destruida por los demás.', '/4LJqMc5nM48O18iNSrbSbMCKQu7.jpg', '/5jewDz5RxdarX45djYc8kjGa5Ia.jpg', 8.1, 'HBDgOrB76Rk', array['1001']::text[], 262, null, 'segura', null),
(25364, 'movie', 'El gran carnaval', 'El gran carnaval', 'Ace in the Hole', 1951, 'Billy Wilder', 'Charles Tatum es un periodista sin escrúpulos que atraviesa una mala racha a causa de su adicción al alcohol, razón por la que se ha visto obligado a trabajar en un pequeño diario de Nuevo México. Cuando un minero indio se queda atrapado en un túnel, Tatum ve la oportunidad de volver a triunfar en el mundo del periodismo. Entonces, en connivencia con el sheriff del pueblo, no sólo convierte el caso en un espectáculo, sino que, además, retrasa cuanto puede el rescate.', '/tJNUItBnWB003o14WgBMHYxPfaZ.jpg', '/bG8EGUNGvZ6vNcBKlXa8Xkoe3kS.jpg', 7.8, 'AX8GLtyWpOY', array['1001']::text[], 263, null, 'segura', null),
(17057, 'movie', 'En un lugar solitario', 'En un lugar solitario', 'In a Lonely Place', 1950, 'Nicholas Ray', 'Steele, un guionista con fama de conflictivo y violento, tiene que afrontar la difícil tarea de adaptar un best-seller de nula calidad literaria. Casualmente se entera de que Mildred, la chica del guardarropa del club que frecuenta, ha leído la obra en cuestión. Decide entonces llevársela a su casa para que le cuente el argumento. Pero, a la mañana siguiente, la policía se presenta en su casa y le comunica que Mildred  ha sido asesinada, y Steele se convierte en el principal sospechoso.', '/taBbWy7bdDZR2iFzUOok7fkceXg.jpg', '/5fuZzGsUZtF9esFFBHPwysB6b6a.jpg', 7.6, '68C2IFX60CU', array['1001']::text[], 263, null, 'segura', null),
(702, 'movie', 'Un tranvía llamado deseo', 'Un tranvía llamado deseo', 'A Streetcar Named Desire', 1951, 'Elia Kazan', 'Blanche, que pertenece a una rancia pero arruinada familia sureña, es una mujer madura y decadente que vive anclada en el pasado. Ciertas circunstancias la obligan a ir a vivir a Nueva Orleáns con su hermana Stella y su cuñado Stanley (Marlon Brando), un hombre rudo y violento. A pesar de su actitud remilgada y arrogante, Blanche oculta un escabroso pasado que la ha conducido al desequilibrio mental. Su inestable conducta provoca conflictos que alteran la vida de la joven pareja.', '/21aAQ59swa68yYuI7XYyLTn0jqQ.jpg', '/or90vNrOVnYwi07fYYpQ3pbnjxP.jpg', 7.6, 'U3CXLHLFvyM', array['1001']::text[], 264, null, 'segura', null),
(845, 'movie', 'Extraños en un tren', 'Extraños en un tren', 'Strangers on a Train', 1951, 'Alfred Hitchcock', 'Inspirada en la novela homónima de Patricia Higsmith. Durante un viaje en tren, Guy, un joven campeón de tenis (Farley Granger), es abordado por Bruno (Walker), un joven que conoce su vida y milagros a través de la prensa y que, inesperadamente, le propone un doble asesinato, pero intercambiando las víctimas con el fin de garantizarse recíprocamente la impunidad. Así podrían resolver sus respectivos problemas: él suprimiría a la mujer de Guy (que no quiere concederle el divorcio) y, a cambio, Guy debería asesinar al padre de Bruno para que éste pudiera heredar una gran fortuna y vivir a su aire.', '/4o0mXvFkVBr7lzH5sOsHGKmsNI5.jpg', '/8Tnn2UOlecCKNLKG8ZK5Mu6bK94.jpg', 7.7, 'PC62NBWBkjM', array['1001']::text[], 265, null, 'segura', null),
(32961, 'movie', 'Oro en barras', 'Oro en barras', 'The Lavender Hill Mob', 1951, 'Charles Crichton', 'Hace veinte años que el tímido Henry Holland (Alec Guinness) se encarga de supervisar el traslado de los cargamentos de oro del banco inglés en el que trabaja; pero llega un momento en que, harto de su gris y anodina vida, idea un ingenioso plan para llevar a cabo un espectacular robo en el banco: se trata de trasladar el oro de Inglaterra a Francia en forma de souvenirs de la Torre Eiffel.', '/u4mZyim3CwXHu0zVhXjfK8fqoN7.jpg', '/vPA53RF6clLSWlpoCLgYvmygiOl.jpg', 7.2, '5jlyDZvCpCQ', array['1001']::text[], 266, null, 'segura', null),
(38688, 'movie', 'Pandora y el holandés errante', 'Pandora y el holandés errante', 'Pandora and the Flying Dutchman', 1951, 'Albert Lewin', 'Pandora Reynolds es una mujer de una belleza arrebatadora que destruye la vida de todos los hombres que se enamoran de ella. Parece incapaz de amar o de corresponder a sus sentimientos. Todo cambia cuando aparece en su vida Hendrick van der Zee, un misterioso marinero, cuyo espíritu está condenado a vagar sin rumbo alrededor del mundo hasta que encuentre una mujer que muera de amor por él.', '/wv5uA5ttDpkfUGKJIKZcsRWNUHI.jpg', '/oWbdLvqzWEMIxmSpHSjcwBlcCrj.jpg', 6.8, 'fcnLjk-hyP8', array['1001']::text[], 266, null, 'segura', null),
(488, 'movie', 'La reina de África', 'La reina de África', 'The African Queen', 1952, 'John Huston', 'Durante la Primera Guerra Mundial, un capitán de barco con tendencia a la bebida y una estirada misionera huyen de las tropas alemanas en una ruinosa embarcación y se ven obligados a remontar un peligroso río. Son, a primera vista, dos seres antagónicos, incompatibles, pero la convivencia y, sobre todo, las penalidades que tendrán que afrontar juntos para sobrevivir harán cambiar radicalmente su relación.', '/kKFqbL0Sz26hwTXC792TybDlCdi.jpg', '/wCJP24CYlsx632qYknoJkMRmvP7.jpg', 7.3, 'sFVu74-A6kI', array['1001']::text[], 267, null, 'segura', null),
(43376, 'movie', 'El diario de un cura de campaña', 'Diario de un cura rural', 'Journal d''un curé de campagne', 1951, 'Robert Bresson', 'Film inspirado en la novela homónima de Georges Bernanos. Un joven sacerdote llega a una pequeña localidad del norte de Francia, donde se hace cargo de su primera parroquia. A pesar de que desarrolla sus labores sacerdotales con diligencia y humildad, es ignorado e incluso rechazado por sus feligreses. Convencido de que ha fracasado como pastor de almas, sufre una profunda crisis de fe. En tales circunstancias, tendrá que afrontar, además, una grave enfermedad.', '/48EFEil3vdPJOpQ5WnfpFfTd6J9.jpg', '/luytZGyalDVIBy2jDk51EKV45T8.jpg', 7.5, 'hXLcNxG0OtM', array['1001']::text[], 268, null, 'probable', null),
(2769, 'movie', 'Un americano en París', 'Un americano en París', 'An American in Paris', 1951, 'Vincente Minnelli', 'Terminada la Segunda Guerra Mundial, Jerry Mulligan, un pintor americano, se queda en París y expone sus cuadros, que nadie compra, en Montparnasse. Un día tiene la suerte de conocer a una americana millonaria que decide promocionarlo. Al mismo tiempo, conoce a una dependienta y se enamora de ella.', '/32WWix2u7MSTm0WjC608ArsPBP8.jpg', '/hVvW015x8cD2X0KthGovw27EpF2.jpg', 7.0, '1XMXAleA1eQ', array['1001']::text[], 268, null, 'segura', null),
(25673, 'movie', 'Un lugar en el sol', 'Un lugar en el sol', 'A Place in the Sun', 1951, 'George Stevens', 'Un obrero se ve envuelto en una historia entre dos mujeres de distinta clase social, una aristócrata y una trabajadora. Cuando la segunda queda embarazada, el destino del joven da un vuelco inesperado.', '/3H0tJhxZa38duyrCvWw4lldaZZw.jpg', '/49LzDsuSefYnEOaNjsoYLMUDn0r.jpg', 7.3, 'sk7a9EyMGiY', array['1001']::text[], 269, null, 'segura', null),
(828, 'movie', 'Ultimátum a la Tierra', 'Ultimátum a la Tierra', 'The Day the Earth Stood Still', 1951, 'Robert Wise', 'El mundo entero queda conmocionado el día en que, sin previo aviso, un O.V.N.I. aterriza en Washington y de él sale Klaatu, un alienígena de aspecto humano, acompañado de Gort, un androide. Klaatu pide reunirse simultáneamente con todos los gobernantes de la Tierra, para entregarles un mensaje muy importante, pero su petición es rechazada. Klaatu se da cuenta de que necesita comprender mejor cómo viven los humanos y, para ello, se hospeda en la casa de una mujer, madre de un chico, con el que Klaatu traba amistad.', '/o9T3uBAUEoAykes1DTVedeloPrh.jpg', '/qwZRvb0DJ5IwDoRuKDRCBuHWzkw.jpg', 7.4, 'sU_wBld7FPo', array['1001']::text[], 270, null, 'segura', null),
(3109, 'movie', 'El hombre tranquilo', 'El hombre tranquilo', 'The Quiet Man', 1952, 'John Ford', 'Después de matar a su oponente durante un combate, un boxeador decide volver a su Irlanda natal para dejar atrás su pasado. Nada más llegar, se enamora de Mary Kate Danaher, una mujer muy temperamental, y decide casarse con ella a pesar de que su hermanastro se opone al matrimonio.', '/h2gCTz7JtldSnNbmDbDMaZ6y54y.jpg', '/phAfwFH41hNLbJjMjvEzMpdMZNl.jpg', 7.3, 'T-n873zZvMo', array['1001']::text[], 271, null, 'segura', null),
(5000, 'movie', 'Juegos prohibidos', 'Juegos prohibidos', 'Jeux interdits', 1952, 'René Clément', 'Junio de 1940. Centenares de franceses, entre los que se encuentran la pequeña Paulette y sus padres, se dirigen en un desesperado éxodo hacia el sur de Francia. Los aviones nazis sobrevuelan el camino y bombardean sin piedad a la multitud. Los padres de Paulette y su perro mueren durante el ataque. Alguien lanza el cadáver del animal al río, pero la niña, incapaz de separarse de él, decide seguirlo, lo que propicia su encuentro con Michel, un chico de once años, que la lleva a la granja de sus padres, donde es muy bien acogida.', '/9giNxXKhfLcDduidtr7VxVD6hX4.jpg', '/iNkgF4uBzcFTrY3NN6JrlCD5Ho.jpg', 7.8, 'JUwdB3PS8jg', array['1001']::text[], 272, null, 'segura', null),
(1938, 'movie', 'Cara de ángel', 'Cara de ángel', 'Angel Face', 1953, 'Otto Preminger', 'Frank Jessup es un enfermero de urgencias que acude a una mansión para atender a la señora Tremayne que, según parece, ha intentado suicidarse. Sin embargo él sospecha que en realidad alguien ha intentado asesinarla. Allí conoce también a Diane, la hijastra de la señora Tremayne, una joven delicada, sensual y un tanto inestable, ante la que cae rendido inmediatamente.', '/xuLPM1tavIaQ2miOIUVYY8O8yOq.jpg', '/4qTuhQTKWzHUx5tw3kE2TxW2cux.jpg', 7.1, 'da4jHmpKFU0', array['1001']::text[], 273, null, 'segura', null),
(872, 'movie', 'Cantando bajo la lluvia', 'Cantando bajo la lluvia', 'Singin'' in the Rain', 1952, 'Gene Kelly, Stanley Donen', 'Hollywood, fines de los años 20: una estrella del cine mudo tiene que adaptarse a la llegada del sonido, con una coprotagonista cuya voz es un desastre.', '/5r8jD5R6EzpQ5VLodbzTNhvKcGw.jpg', '/6qOyw4yfzbzTp5YsCX26C28Do0S.jpg', 8.1, 'lSE8sl2-PZg', array['1001','clasicos']::text[], 274, null, 'segura', null),
(3782, 'movie', 'Vivir', 'Vivir', '生きる', 1952, 'Akira Kurosawa', 'Kanji Watanabe es un viejo funcionario público que arrastra una vida monótona y gris; sin embargo, no es consciente del vacío de su existencia hasta que le diagnostican un cáncer incurable. Con la certeza de que el fin de sus días se acerca, surge en él la necesidad de buscarle un sentido a la vida. Y cuando lo consigue se produce un cambio radical en su actitud respecto a los demás.', '/waVPzQxWkvhqOsTsFnWGJ9ymvBE.jpg', '/fS4xXq5lVwu1V95qB4murKZgPFo.jpg', 8.3, 'geKhyNerWM8', array['1001']::text[], 276, null, 'segura', null),
(41464, 'movie', 'Europa ''51', 'Europa ''51', 'Europa ''51', 1952, 'Roberto Rossellini', 'Un rico matrimonio estadounidense que lleva en Roma una vida despreocupada, ve cómo su hijo se suicida. La madre, traumatizada y sintiéndose culpable por no haber atendido más a su hijo desde la infancia, decide ayudar a la gente más necesitada en los barrios más humildes de la ciudad. Sin embargo, su ayuda a un delincuente la pondrá bajo sospecha a ojos de la policía.', '/apOafcj1w3g1BROkRKyLqRy73bv.jpg', '/yo48a0FPvHwMDLKsnhQAIbkWVpH.jpg', 7.3, 'kjorQxtgyks', array['1001']::text[], 277, null, 'segura', null),
(32499, 'movie', 'Cautivos del mal', 'Cautivos del mal', 'The Bad and the Beautiful', 1952, 'Vincente Minnelli', 'Un tiránico y manipulador productor de cine que ha caído en desgracia pide ayuda a un director, a una actriz y a un guionista a los que ayudó a triunfar, pero que tienen sobradas razones para detestarlo. Los tres le reprochan su falta de escrúpulos para alcanzar el éxito sin reparar en las personas a las que traicionaba o engañaba.', '/tgq3zt2WBHwnFcBbdVy3ikUxCMX.jpg', '/jVyVSD0w4Bg3r67geP0LvkizfC5.jpg', 7.3, 'T4mG-4HBn1w', array['1001']::text[], 278, null, 'segura', null),
(43367, 'movie', 'Río de sangre', 'Río de sangre', 'The Big Sky', 1952, 'Howard Hawks', 'Jim y Boone son dos exploradores que participan en una expedición por el río Missouri cuyo fin es establecer un asentamiento en territorio indio. Les acompañan un comerciante de pieles, una guía india y un indio que ha renegado de su tribu. A los peligros de la expedición se sumará la tensión que se establece entre los hombres debido a la belleza de la mujer.', '/fFNzPlSe4mIvnXaTEvNQwVzYv1j.jpg', '/7mVxlq9ln4USELWdbmulSprVMAa.jpg', 6.6, 'LepAacvaEO4', array['1001']::text[], 279, null, 'segura', null),
(288, 'movie', 'Solo ante el peligro', 'Solo ante el peligro', 'High Noon', 1952, 'Fred Zinnemann', 'Will Kane, el sheriff del pequeño pueblo de Hadleyville, acaba de contraer matrimonio con Amy. Los recién casados proyectan trasladarse a la ciudad y abrir un pequeño negocio; pero, de repente, empieza a correr por el pueblo la noticia de que Frank Miller, un criminal que Kane había atrapado y llevado ante la justicia, ha salido de la cárcel y llegará al pueblo en el tren del mediodía para vengarse de Kane. El tiempo va pasando lentamente, pero nadie en el pueblo está dispuesto a ayudar al sheriff.', '/9wGUWTtUfCvW5qVv8kHkPZBikKd.jpg', '/raYHhtIDyh3qDS6WdyRzeqjLyIK.jpg', 7.7, 'vFRm6xPDLFc', array['1001']::text[], 279, null, 'segura', null),
(833, 'movie', 'Umberto D.', 'Umberto D.', 'Umberto D.', 1952, 'Vittorio De Sica', 'Umberto Doménico Ferrari es un jubilado que intenta sobrevivir con su miserable pensión. Sumido en la pobreza, vive en una pensión, cuya dueña lo maltrata porque no consigue reunir el dinero necesario para pagar el alquiler de su habitación. Los únicos amigos que tiene en este mundo son una joven criada y sobre todo su perro Flike.', '/1xn9TLPX5D2hAqCuMTenTmtT4ns.jpg', '/dop0CEPeeW3BXDUGL1oDt9ywgK.jpg', 7.9, 'uAgrq1_UOOc', array['1001']::text[], 280, null, 'segura', null),
(74122, 'movie', 'El bígamo', 'El bígamo', 'The Bigamist', 1953, 'Ida Lupino', 'Harry vive en San Francisco y como representante comercial debe viajar mucho. Está casado con Eve y ambos están intentando adoptar un bebé. Mr. Jordan, director de la agencia de adopción, comienza a hacer una serie de averiguaciones y sospecha de Harry, el cual guarda un secreto. Pronto descubre que éste tiene en Los Angeles una segunda esposa y un bebé.', '/fEPxJf6haz3EZqkyUlwD6kdCQ8N.jpg', '/bn63p4oxeOWSXwtAf1xCPv1ZQIo.jpg', 6.4, 'NF6qA0hGGeA', array['1001']::text[], 281, null, 'segura', null),
(56167, 'movie', 'La carroza de oro', 'La carroza de oro', 'Le Carrosse d''or', 1952, 'Jean Renoir', 'América española, siglo XVIII. A una pequeña ciudad llega una compañía italiana de teatro. Camilla, la estrella del espectáculo, debe elegir entre tres hombres: el Virrey, un joven oficial y un torero. Es un homenaje a la Comedia del Arte.', '/6x1JnbgsUarHnLRmqnprhzQwWlR.jpg', '/sCFbxavogjcE6xTnT71nZxTV5ia.jpg', 7.1, 'wn3EfdigfNI', array['1001']::text[], 281, null, 'segura', null),
(29376, 'movie', 'Melodías de Broadway', 'Melodías de Broadway 1955', 'The Band Wagon', 1953, 'Vincente Minnelli', 'Un cantante y bailarín de éxito, a pesar de que atraviesa una etapa muy crítica, está decidido a volver a Broadway, el escenario que le dio la gloria y la fama.', '/ffKBgB7RwmOl8v9G803CMeUDWhg.jpg', '/bud4H3I6X9b9HIcilAb33k6mNES.jpg', 7.2, 'rgvJPU8t6kE', array['1001']::text[], 282, null, 'segura', null),
(27030, 'movie', 'Madame de...', 'Madame de…', 'Madame de…', 1953, 'Max Ophüls', 'Urgida por la necesidad de dinero para cubrir sus cuantiosos gastos, una condesa vende unos pendientes que le regaló su marido, y a éste le dice que los ha extraviado. El joyero, indiscreto, le cuenta al conde lo sucedido, y le vende la joya que, tras distintos avatares, llegan a manos de un diplomático italiano.', '/wHi2vCHy8QdJPA00oAtahVRzd0b.jpg', '/msQMXYEBHQ7zPVu0TPEm7wUSGHQ.jpg', 7.5, 'al18feIPhPI', array['1001']::text[], 283, null, 'segura', null),
(11426, 'movie', 'De aquí a la eternidad', 'De aquí a la eternidad', 'From Here to Eternity', 1953, 'Fred Zinnemann', 'Al soldado Prewitt están a punto de concederle un traslado con el que abandonará Pearl Harbour. Pero el nuevo capitán Holmes le retiene con el pretexto de que es un gran boxeador. Los romances y los abusos están al orden del día en una base despreocupada por la Segunda Guerra Mundial. Sin embargo, el ataque japonés al enclave es inminente.', '/ea6NcYdlAsiaV1saXWKPLIHFDKx.jpg', '/kpTTUyVxWMTebmBkaxB2YAX8yyU.jpg', 7.3, 'gFqfmJXrgUc', array['1001']::text[], 284, null, 'segura', null),
(18148, 'movie', 'Cuentos de Tokio', 'Cuentos de Tokio', '東京物語', 1953, 'Yasujirō Ozu', 'Un matrimonio mayor viaja a Tokio a visitar a sus hijos, que están demasiado ocupados para atenderlos.', '/36G6HwEN3K9BrPEC8icOIOdCUb4.jpg', '/jLq0ol1f0ZKXni9R9GsPBcyPrNN.jpg', 8.2, 'xqO0d3328Do', array['1001','clasicos']::text[], 285, null, 'segura', null),
(804, 'movie', 'Vacaciones en Roma', 'Vacaciones en Roma', 'Roman Holiday', 1953, 'William Wyler', 'Durante una visita a Roma, Ana, la joven princesa de un pequeño país centroeuropeo que detesta sus obligaciones y desea pasar inadvertida, se escapa de palacio para visitar la ciudad de incógnito. Así conoce a Joe, un periodista americano que busca una exclusiva y finge desconocer su verdadera identidad. La pareja vivirá entonces unas jornadas inolvidables.', '/lZOF4rMqgeNR4IvrYRJzkoJp4d4.jpg', '/gzRISGjiDMj4xqYE9ES2KNIXxpo.jpg', 7.9, '2vm2FdHg7Io', array['1001']::text[], 286, null, 'segura', null),
(204, 'movie', 'El salario del miedo', 'El salario del miedo', 'Le Salaire de la peur', 1953, 'Henri Georges Clouzot', 'La tensión entre cuatro trabajadores de una compañía petrolífera estallará durante un peligroso viaje durante el cual transportan nitroglicerina.', '/lvKUfnwElQEKekHitpLi8CUD866.jpg', '/pYj2esro7xK6uqt7Kjk3Jicjigr.jpg', 8.0, 'ZYDZ3vNa-MQ', array['1001']::text[], 287, null, 'segura', null),
(20442, 'movie', 'Colorado Jim', 'Colorado Jim', 'The Naked Spur', 1953, 'Anthony Mann', 'Durante la guerra Civil (1861-1865), Howard Kemp (James Stewart) pierde su granja mientras lucha en el frente. Con el fin de reunir el dinero suficiente para recuperarla, trabaja como cazarrecompensas en el territorio de Colorado. Su primer objetivo será Ben Vandergroat (Robert Ryan), acusado de asesinar a un sherif. Tras acorralarlo en las Montañas Rocosas, se unen a él dos hombres que buscan compartir la jugosa recompensa: un viejo buscador de oro y un desertor del ejército de la Unión.', '/6XTY5esFlgfcNVc7IopBaU3SutA.jpg', '/AhBDWDu1NQ1UBqfedUsZvsmeHRA.jpg', 7.0, 'FtBtW1v6wuw', array['1001']::text[], 288, null, 'segura', null),
(25955, 'movie', 'Manos peligrosas', 'Manos peligrosas', 'Pickup on South Street', 1953, 'Samuel Fuller', 'Skip McCoy (Richard Widmark), un ratero de poca monta, atraca a una mujer llamada Candy (Jean Peters) y se apodera de un valioso microfilm que contiene secretos de estado. Pero Candy estaba bajo la vigilancia de agentes del gobierno, por lo que Skip se convertirá en sospechoso. Thelma Ritter fue nominada al Oscar a la mejor actriz secundaria.', '/ivDjP5NavnBQDzDsdaI8eWekzo5.jpg', '/wrX24LRWYGZyvPr3W3SSM35QOd7.jpg', 7.4, 'vEAURni5bIE', array['1001']::text[], 288, null, 'segura', null),
(759, 'movie', 'Los caballeros las prefieren rubias', 'Los caballeros las prefieren rubias', 'Gentlemen Prefer Blondes', 1953, 'Howard Hawks', 'Lorelei y Dorothy son dos cantantes que hacen un crucero desde los Estados Unidos a París. Una rubia y otra morena, con su belleza y encanto seducirán a todo el pasaje. Las dos tienen el mismo objetivo: casarse con un millonario. Pero hay un inconveniente: Lorelei tiene un novio, cuyo padre contrató un detective para que la siguiera.', '/vO6aAcPxQp6i6a2Zeh4zDvZrqiM.jpg', '/2clBxxclZJ4OK1xzhmCCXHEfy3r.jpg', 7.3, 'TOqfJEPB8rI', array['1001']::text[], 289, null, 'segura', null),
(14580, 'movie', 'Los sobornados', 'Los sobornados', 'The Big Heat', 1953, 'Fritz Lang', 'Dave Bannion es un honesto policía que investiga el suicidio de un compañero. Bertha, la viuda, le explica a Bannion que a su esposo le habían diagnosticado una grave enfermedad. Pero Lucy, la amante del difunto, le cuenta que, en realidad, el policía había descubierto un complejo entramado de corrupción en su departamento. Cuando Lucy aparece brutalmente asesinada, Bannion decide acusar a Lagana, el mayor mafioso de la ciudad. Al cabo de poco tiempo, el coche de Bannion explota y mata a su esposa, hecho que le llevará a iniciar una salvaje venganza.', '/3YPt74p6MtqYE2fyFdRXE5m2I9p.jpg', '/aqZookq6pJmIT9lVIjDsBY2MNpK.jpg', 7.7, 'ze6S3zZdSlA', array['1001']::text[], 290, null, 'segura', null),
(778, 'movie', 'Las vacaciones de monsieur Hulot', 'Las vacaciones del señor Hulot', 'Les vacances de Monsieur Hulot', 1953, 'Jacques Tati', 'En un balneario de la costa atlántica, los veraneantes son incapaces de apartarse de sus rutinarias costumbres urbanas. Hasta que llega monsieur Hulot al volante de su viejo cacharro y rompe la calma estival. Para gran alegría de los niños, Hulot ofrecerá a los huéspedes del hotel unas vacaciones inolvidables.', '/j0GAK1wTNs6kK09fwZoBkhqiiED.jpg', '/dK6s1EMpMcUwBHpiYVMBiTdgdvy.jpg', 7.0, 'BoQTEEmoZgM', array['1001']::text[], 291, null, 'segura', null),
(2748, 'movie', 'Te querré siempre', 'Te querré siempre', 'Viaggio in Italia', 1954, 'Roberto Rossellini', 'Un matrimonio inglés viaja a Italia para vender una villa que ha heredado cerca de Nápoles. Al alejarse del ambiente londinense y encontrarse en un paisaje y en un mundo ajenos, la pareja experimenta sentimientos olvidados, como los celos y el resentimiento.', '/iOmYcCMrQ3VYBqgvJqx1e3Qev56.jpg', '/5SDqKj8AfUazPqXvOCDL1nmE8Zb.jpg', 7.2, 'XXJM3shx8WU', array['1001']::text[], 292, null, 'segura', null),
(14696, 'movie', 'Cuentos de la luna pálida', 'Cuentos de la luna pálida', '雨月物語', 1953, 'Kenji Mizoguchi', 'En el Japón del siglo XVI, los campesinos Genjuro y Tobei venden sus vasijas de barro a un grupo de soldados en un pueblo cercano, desafiando la advertencia de un sabio local contra la búsqueda de ganancias en la guerra. La búsqueda de riquezas de Genjuro y de la misteriosa Lady Wakasa, así como el deseo de Tobei de convertirse en samurái, corren el riesgo de destruirlos a ellos mismos y a sus esposas, Miyagi y Ohama.', '/91moI7d2k2KSkixuecsfhf3gBh5.jpg', '/iB1tCWl4MKl6OO1kMBD5LxM5BmJ.jpg', 8.0, 'CLrlhu0XxdY', array['1001']::text[], 293, null, 'segura', null),
(3110, 'movie', 'Raíces profundas', 'Raíces profundas', 'Shane', 1953, 'George Stevens', 'Alabama, finales del siglo XIX. Shane, un hastiado pistolero, llega a la granja de los Starretts, un matrimonio con un hijo que, al igual que los demás campesinos del valle, se encuentra en graves dificultades, pues el poderoso ganadero Rufus Ryker pretende apoderarse de sus tierras. Cuando Ryker se entera de que Shane es un hábil pistolero, le propone que trabaje para él. Ante su negativa, contrata a Jack Wilson, un peligroso asesino a sueldo.', '/goDI3aR3Yncm0dWs1OLyhZpmfoX.jpg', '/mPzUzA0iK50gBdMuux4Dojb7VQL.jpg', 7.3, 'JMYo9FTcnck', array['1001']::text[], 294, null, 'segura', null),
(26596, 'movie', 'Johnny Guitar', 'Johnny Guitar', 'Johnny Guitar', 1954, 'Nicholas Ray', 'La relación sentimental entre Vienna, la propietaria de un salón situado en las afueras de una ciudad del Oeste, y Johnny Guitar, un pistolero con el que se vuelve a encontrar en un difícil momento, constituye todo un clásico que alcanzó un gran éxito de taquilla.', '/aImQC5wowLPOwutdsbN99ItaNCU.jpg', '/yiglnLtYEH6UGY1qFy4zacixCXf.jpg', 7.4, 'ACgSyxdV9vE', array['1001']::text[], 295, null, 'segura', null),
(22733, 'movie', 'La burla del diablo', 'La burla del diablo', 'Beat the Devil', 1953, 'John Huston', 'A un pequeño puerto italiano llegan cuatro estafadores que viajan en compañía de un matrimonio norteamericano (Billy y María) que les sirve de tapadera. Mientras esperan la reparación del barco que los llevará a África, le aclaran a Billy el verdadero motivo del viaje: adquirir unas tierras ricas en uranio. Durante su estancia en el pueblo, Billy y María conocen a otro matrimonio norteamericano, cuyas alusiones a unos yacimientos de uranio, hacen sospechar a los aventureros que su proyecto corre peligro. (FILMAFFINITY)', '/wjgdc0qC9T8tLrwXcpATI66zqUb.jpg', '/mGn28CazoJCNkrxxkCWKXHpmVXM.jpg', 6.1, 'y6X_KEGaG-A', array['1001']::text[], 295, null, 'segura', null),
(654, 'movie', 'La ley del silencio', 'La ley del silencio', 'On the Waterfront', 1954, 'Elia Kazan', 'El exboxeador Terry Malloy podría haber sido un serio aspirante al título, pero se ve obligado a ganarse la vida trabajando para Johnny Friendly, el jefe de la conflictiva banda de gánsteres de la ciudad. Cuando dos de los matones de Friendly asesinan brutalmente a un hombre, Terry comienza a sentirse culpable con la vida que lleva, iniciando una peligrosa lucha para derrocar el imperio del hampa', '/rf342b70NdNhZIIQWFKa8sSDyf6.jpg', '/j0qTehcyVVV1VEzrJ7YYtoFmWNw.jpg', 7.8, 'boekTHsOIY8', array['1001']::text[], 296, null, 'segura', null),
(827, 'movie', 'Las diabólicas', 'Las diabólicas', 'Les Diaboliques', 1955, 'Henri Georges Clouzot', 'El director de un colegio, el señor Delasalle, convive con su esposa y su amante, la profesora Horner. Pero las dos mujeres, cansadas de sufrir la constante tiranía y malos tratos del hombre que comparten, deciden que esa situación no puede continuar.', '/eX2SM3UECXJgrGknXHdYS2veReS.jpg', '/rcEUuRtr0dFL078bNeXL8pQqrMK.jpg', 7.9, 'BzbGtjtfZwA', array['1001']::text[], 298, null, 'segura', null),
(16563, 'movie', 'Siete novias para siete hermanos', 'Siete novias para siete hermanos', 'Seven Brides for Seven Brothers', 1954, 'Stanley Donen', 'Los hermanos Pontipee son siete rudos leñadores, todos solteros, que viven en una cabaña en las montañas. Su vida cambia radicalmente cuando Adam, el hermano mayor, encuentra novia en el pueblo y se la lleva a vivir a la cabaña. Los demás hermanos deciden, entonces, hacer lo mismo y van a la ciudad en busca de novia. Tan empeñados están en casarse que no dudan en secuestrar a siete chicas y se las llevan a vivir con ellos.', '/3zTsqmh1mDTHvIH4iTrvARt7yLs.jpg', '/5i2rmZ2Vwuzq6CPOaTLW0jjhJmB.jpg', 7.1, 'V5LfmwVWJ1k', array['1001']::text[], 298, null, 'segura', null),
(11848, 'movie', 'Rebelión en la granja', 'Rebelión en la granja', 'Animal Farm', 1954, 'Joy Batchelor, John Halas', 'Estamos en la Granja Manor, en la Inglaterra de los años cincuenta. Hartos de los maltratos que les da el brutal granjero Jones, todos los animales se unen en una violenta rebelión que excluye a todos los humanos: ha nacido la Granja Animal. Pero el entusiasmo se torna en decepción cuando los cerdos, con el dictatorial Napoleón a la cabeza, asuman el control de la revolución.', '/qkwoN87Dbos41yPEC2QUwpRyu8R.jpg', '/5MYD8Z76Bcbz55HzUTP4U6dH51V.jpg', 7.1, 'qBsQkZ-rRM8', array['1001']::text[], 299, null, 'segura', null),
(567, 'movie', 'La ventana indiscreta', 'La ventana indiscreta', 'Rear Window', 1954, 'Alfred Hitchcock', 'Un fotógrafo enyesado pasa los días espiando a sus vecinos desde la ventana, hasta que empieza a sospechar que uno de ellos cometió un crimen.', '/fH1MipE8PXGg0rlI5cUdzxKnyA2.jpg', '/5bN06p5OwRUEqcfrtNs5egV16yb.jpg', 8.3, 'iZOTTxwzyMU', array['1001','clasicos']::text[], 300, null, 'segura', null),
(3111, 'movie', 'Ha nacido una estrella', 'Ha nacido una estrella', 'A Star Is Born', 1954, 'George Cukor', 'Norman Maine, un famoso actor adicto al alcohol, descubre a Esther, una joven con un gran talento para la canción y decide impulsar su carrera cinematográfica. Ella consigue la fama y, a los pocos meses, la pareja contrae matrimonio. Pero, a medida que el éxito de Esther aumenta, decae el de Norman, y esta situación lo empuja a la autodestrucción.', '/fYkBlkUalcJRUqEFCcX2boAKTCj.jpg', '/AlvKqnxlkWWYE6ngRLOWfYY3QuI.jpg', 7.1, 'K48JkClgYIs', array['1001']::text[], 302, null, 'segura', null),
(34689, 'movie', 'La condesa descalza', 'La condesa descalza', 'The Barefoot Contessa', 1954, 'Joseph L. Mankiewicz', 'Tres cineastas estadounidenses descubren a una extraordinaria bailarina llamada María Vargas. Sin perder ni un minuto, se trasladan a Hollywood y lanzan a la desconocida al estrellato. Kirk, el productor de sus películas, corteja en vano a María. Ella, para humillarle, accede a acompañar al multimillonario Bravano en un crucero por la Riviera.', '/3yLO22umlz7q5sShU3AL1eBM1Pg.jpg', '/2yK59yDiP4P5hsENbGYSPc3YA5I.jpg', 6.8, 'GPqq6UZy4B8', array['1001']::text[], 302, null, 'segura', null),
(405, 'movie', 'La strada', 'La strada', 'La strada', 1954, 'Federico Fellini', 'Cuando Zampanó, un artista ambulante, enviuda, compra a Gelsomina, la hermana de su mujer, sin que la madre de la chica oponga la menor resistencia. Pese al carácter violento y agresivo de Zampanó, la muchacha se siente atraída por el estilo de vida nómada, siempre en la calle (la strada en italiano), sobre todo cuando su dueño la incluye en el espectáculo. Aunque varios de los pintorescos personajes que va conociendo en su deambular le proponen que se una a ellos, Gelsomina se mantendrá fiel a Zampanó hasta las últimas consecuencias.', '/kEbpEJeU1voZ21xzIcm2CUx9hFt.jpg', '/p6qM3hlviWYIgpPq4zNwrttn6Io.jpg', 7.9, 'GrE7syApSkA', array['1001']::text[], 303, null, 'segura', null),
(346, 'movie', 'Los siete samuráis', 'Los siete samuráis', '七人の侍', 1954, 'Akira Kurosawa', 'Un pueblo de campesinos, cansado de los saqueos, contrata a siete samuráis sin señor para defenderse de una banda de bandidos.', '/zr4DkzWIMjaWtj6hlsbN6dnNeTX.jpg', '/qvZ91FwMq6O47VViAr8vZNQz3WI.jpg', 8.5, 'RsRN65PlaIM', array['1001','clasicos']::text[], 304, null, 'segura', null),
(43195, 'movie', 'Senso', 'Senso', 'Senso', 1954, 'Luchino Visconti', 'Año 1866. Livia, una bella dama de una aristocrática familia italiana, vive un intenso romance con el teniente Franz Mahler, un oficial del ejército austriaco, en plena guerra de independencia italiana frente a Austria.', '/qLwENVUnmb6ULiUKAh6dzDTwxUI.jpg', '/q2ve97XH53hEUaWEUhD9AQcnn1A.jpg', 7.2, '6vJ3DEujOpI', array['1001']::text[], 306, null, 'segura', null),
(51044, 'movie', 'Carmen Jones', 'Carmen Jones', 'Carmen Jones', 1954, 'Otto Preminger', 'Carmen Jones, una mujer acostumbrada a manejar a los hombres a su antojo, asedia a Joe, un joven soldado que piensa contraer matrimonio con Cindy Lou y al que no consigue atrapar. Aprovechando una pelea de Carmen con una compañera de trabajo, el sargento Brown, al que Joe no le es simpático, ordena al soldado que la escolte hasta la prisión, al tiempo que hace creer a su novia que Joe se ha prestado voluntario a esa misión.', '/sgbGIiQiq4wK0qluR3HQKHpVWnu.jpg', '/nhbeAwC5NcvPIOVDkamICjdKIFN.jpg', 6.2, 'sohT0HTgP84', array['1001']::text[], 307, null, 'segura', null),
(27443, 'movie', 'Filón de plata', 'Filón de plata', 'Silver Lode', 1954, 'Allan Dwan', 'En la pequeña ciudad de Silver Lode, el sheriff McCart interrumpe bruscamente la boda entre Dan y Rose para detener al novio.', '/1l4HLFk81KEsWxNtaFVkz3q25kh.jpg', '/rWx3NHwnPRMH2w3TwRmZZip6SNp.jpg', 6.2, 'Ypuc3z7NJ1A', array['1001']::text[], 307, null, 'segura', null),
(20532, 'movie', 'El intendente Sansho', 'El intendente Sansho', '山椒大夫', 1954, 'Kenji Mizoguchi', 'A finales de la Era Heian en el siglo XII, el gobernador de un pueblo es enviado al exilio. A pesar de que su familia quiere ir con él, ninguno podrá acompañarle, pues, engañados por una vieja que se hace pasar por sacerdotisa, son vendidos como esclavos por separado: la madre por un lado y los hijos por otro.', '/z7IZYt4nsNig12RGtMhW4uPyRr7.jpg', '/wJfbBUiJH8C9PTAunn11Ms4KN8h.jpg', 8.1, 'JWlYxCDcxWA', array['1001']::text[], 308, null, 'segura', null),
(43317, 'movie', 'Cómicos en París', 'Cómicos en París (Artistas y modelos)', 'Artists and Models', 1955, 'Frank Tashlin', 'Eugene y Rick son dos cómicos que comparten piso. Rick no soporta a Eugene porque éste, que es un fanático de los cómics de Pulp Fiction, tiene constantes pesadillas. Pronto, la tolerancia de Rick aumenta, pues las pesadillas de Eugene son un material excelente para aprovechar en un nuevo cómic que tiene en mente.', '/1jx2gS2xCmxgERLcefhOFayqYTR.jpg', '/aOv5il3ZjsuC8hYiojsmtAH0txD.jpg', 6.6, 'p941L6cp1mw', array['1001']::text[], 310, null, 'segura', null),
(23620, 'movie', 'La sal de la tierra', 'La sal de la tierra', 'Salt of the Earth', 1954, 'Herbert J. Biberman', 'La sal de la tierra narra una huelga de mineros en el sur de Estados Unidos que, cansados de que sus condiciones de trabajo sean cada vez peores, deciden parar la actividad. Cuando la ley obliga a disolver los piquetes, entonces son las mujeres de los mineros las que se ponen al frente de la huelga, aprovechando un vacío legal. Sus demandas aumentan, ya que exigen, además de mejoras en el trabajo, mejoras en las condiciones de vida, y una igualdad no solo laboral sino sexual.', '/idMXQdttUKgtODDsZVXXt4epRie.jpg', '/uqh2tPWQzY2Bzi8Xg6keXv7XMTo.jpg', 7.0, 'NB3FGeUMoYk', array['1001']::text[], 310, null, 'segura', null),
(4825, 'movie', 'Ellos y ellas', 'Ellos y ellas', 'Guys and Dolls', 1955, 'Joseph L. Mankiewicz', 'Adaptación de un musical de Broadway basado en un cuento de Damon Runyon, gran maestro de la literatura picaresca americana. Nathan Detroit (Frank Sinatra), organizador de las partidas más selectas de dados de Nueva York, apuesta mil dólares con uno de los jugadores (Marlon Brando) a que no es capaz de enamorar a una joven puritana que pertenece al Ejército de Salvación (Jean Simmons).', '/x4V2efbQydkRBza926afNmCvDG5.jpg', '/wKCVht8Vivzub6i6blSK8SIuBvL.jpg', 6.6, 'ykzP_64l-xk', array['1001']::text[], 311, null, 'segura', null),
(5801, 'movie', 'Pather Panchali (El lamento del sendero)', 'Pather Panchali (La canción del camino)', 'পথের পাঁচালী', 1955, 'Satyajit Ray', 'Narra la historia de una familia bengalí acuciada por la mala suerte. El padre, Harihara, es un sacerdote seglar, curandero, soñador y poeta. Sabajaya, la madre, trabaja para alimentar a su familia, que recibe con alegría y esperanza la llegada de un nuevo hijo, Apu. Es el primer film de "La trilogía de Apu".', '/ashqMIq9OI9ibRsaRNckSOwGG59.jpg', '/wadoNHCMPElgYuOqLxqDQqXpTMx.jpg', 7.8, 'mgv68E_o6VM', array['1001']::text[], 312, null, 'segura', null),
(14554, 'movie', 'Conspiración de silencio', 'Conspiración de silencio', 'Bad Day at Black Rock', 1955, 'John Sturges', 'En 1945, un hombre con un solo brazo llega al desolado pueblo de Black Rock. Es John MacReedy (Spencer Tracy) y busca a Joe Komaco, un granjero japonés cuyo hijo le salvó la vida en la guerra. El comportamiento de los vecinos es extrañamente hostil y grosero, y las preguntas de MacReedy sobre Komaco no reciben respuesta. Es evidente que ocultan algo, lo que despierta la curiosidad del forastero, que no está dispuesto a irse antes de averiguar el terrible secreto que esconde Black Rock.', '/guu9SsJxcafP1LPg8XXo4kvsOKF.jpg', '/tQv32m6pufbJT2rKuKDzt0kVynQ.jpg', 7.3, '17nCYAayWMQ', array['1001']::text[], 314, null, 'segura', null),
(84850, 'movie', 'La colina 24 no contesta', 'גבעה 24 אינה עונה', 'גבעה 24 אינה עונה', 1955, 'Thorold Dickinson', 'In 1948, immediately before a ceasefire takes effect, four volunteers fighting for Israel are ordered to take Hill 24, overlooking the road to Jerusalem.', '/kmAKq5HdfZiYe3kNNtoMJGjfCzE.jpg', '/cDdLMZnYpgA0tM4jmjS0xeJukh7.jpg', 5.9, null, array['1001']::text[], 315, null, 'probable', null),
(84820, 'movie', 'Les maîtres fous', 'Los amos locos', 'Les Maîtres fous', 1955, 'Jean Rouch', 'La premisa de este documental es seguir los efectos del colonialismo de los indígenas africanos a través de varios rituales que estos desarrollaron a raíz del sistema colonial. (FILMAFFINITY)', '/7eM2JjsPhv1KJej3V0bhbuHkCn7.jpg', '/8MPT2UJ5r2nTLpLZy92JyopeRKi.jpg', 6.2, null, array['1001']::text[], 315, null, 'segura', null),
(5506, 'movie', 'El quinteto de la muerte', 'El quinteto de la muerte', 'The Ladykillers', 1955, 'Alexander Mackendrick', 'En una casa aislada y próxima a las vías del tren vive la señora Wilberforce, una venerable anciana que alquila dos habitaciones al misterioso profesor Marcus y a los cuatro miembros de su siniestra banda de música.', '/zv8Epyx1opCX2MLtzJT6pSxZlVB.jpg', '/4GLIDGOOzHSUYzwaFlxsbL9z5hY.jpg', 7.3, 'TdJGho9p-wA', array['1001']::text[], 316, null, 'segura', null),
(15919, 'movie', 'Marty', 'Marty', 'Marty', 1955, 'Delbert Mann', 'Marty es un carnicero solterón que todavía vive con su madre. Suele salir con frecuencia con sus amigos por la noche, intentando encontrar a alguna chica con la que compartir su vida y hacer planes para el futuro.', '/79aC4arR3hA6jJw5uBtW5NByDO3.jpg', '/zhZtaNcjtc6VgV8SC4VlokiaeNt.jpg', 7.5, 'nchN0nEsXnA', array['1001']::text[], 316, null, 'segura', null),
(48035, 'movie', 'La palabra', 'La palabra', 'Ordet', 1955, 'Carl Theodor Dreyer', 'Hacia 1930, en un pequeño pueblo de Jutlandia occidental, el viejo Morten Borgen dirige la granja de Borgensgaard. Tiene tres hijos: Mikkel, Johannes y Anders. El primero está casado con Inger y tiene dos hijas pequeñas, aunque en estos momentos Inger está embarazada y esperan el tercero. Johannnes es un antiguo estudiante de Teología que, por haberse imbuido de las ideas de Kierkegaard e identificarse con la figura de Jesucristo, es considerado por todos como un loco. El tercero, Anders, está enamorado de la hija del sastre, líder intransigente de un sector religioso rival. Tal circunstancia revitaliza la discordia que siempre ha existido entre las dos familias, ya que ninguna ve con muy buenos ojos que sus hijos contraigan matrimonio.', '/kd9z7SCv5Ps7E4Ry0udMNlQrRNV.jpg', '/62pTb3zkfE2860lIqQFlxQ5tUEL.jpg', 7.9, '-uQEPjRog84', array['1001']::text[], 317, null, 'segura', null),
(26030, 'movie', 'Bob le flambeur', 'Bob el jugador', 'Bob le flambeur', 1956, 'Jean Pierre Melville', 'Bob es un viejo gánster y un jugador empedernido que está casi a punto de arruinarse. Entonces, a pesar de las advertencias de sus amigos, decide atracar el casino de Dauville. Todo está planeado a la perfección, pero la policía está informada del atraco.', '/lUT3XFQe1hVuaiPY6KNLIWzafbf.jpg', '/sD3fYFWaoLzMPFDcKrGFPrXFJG3.jpg', 7.3, '1NJBRyUDeA4', array['1001']::text[], 318, null, 'segura', null),
(18030, 'movie', 'El beso mortal', 'El beso mortal', 'Kiss Me Deadly', 1955, 'Robert Aldrich', 'El detective Mike Hammer recoge en la carretera, en plena noche, a una muchacha que huye de un peligro mortal. Poco después son interceptados por los acosadores, unos despiadados matones que, tras torturar y matar a la muchacha y pegar una paliza al duro detective, les arrojan por un precipicio. Hammer logra salir indemne, y se dedicará a investigar este misterioso caso.', '/wzdeMzXPx4e18gb9nlrX527GYwM.jpg', '/znL0K0hPJndT7IAddNWBfAEYSRC.jpg', 7.2, 'ss4AF91KOFw', array['1001']::text[], 319, null, 'segura', null),
(18264, 'movie', 'El hombre de Laramie', 'El hombre de Laramie', 'The Man from Laramie', 1955, 'Anthony Mann', 'Will Lockhart llega a Coronado, un pueblo aislado situado en New Mexico, en busca de alguien que vende rifles a la tribu apache, y se ve involucrado a su pesar en la enrevesada vida de una familia local de rancheros cuyos miembros parecen tener mucho que ocultar.', '/xQKva7sKrBWcL0BlScos2a4uEK4.jpg', '/f2AknGbvyhFdeZUDcbq3ZqguQZT.jpg', 7.1, 'aQXZ8LYrmT4', array['1001']::text[], 319, null, 'segura', null),
(221, 'movie', 'Rebelde sin causa', 'Rebelde sin causa', 'Rebel Without a Cause', 1955, 'Nicholas Ray', 'Tres jóvenes, Jim Stark, Judy y Platón, coinciden en una comisaría. Cada uno está allí por un motivo distinto: Jim está borracho, Judy se ha escapado de su casa y Platón acababa de matar a tiros a unos cachorros. El inspector Ray descubre que los tres mantienen una relación conflictiva con sus familias. A Jim y a Judy los van a recoger sus padres, pero Platón, hijo de una pareja divorciada, tiene que conformarse con la visita de la criada negra que vive con él.', '/eGFnAAtyeLyHRGIfSfP1btWkK33.jpg', '/iRUBsjkPeK21nlHqH4szJCz2Ma1.jpg', 7.5, 'HWHH5TwEwtI', array['1001']::text[], 320, null, 'segura', null),
(35956, 'movie', 'El imperio del terror', 'El imperio del terror', 'The Phenix City Story', 1955, 'Phil Karlson', 'Un pueblo de Alabama está casi completamente dominado por el crimen organizado, que adquiere cada vez más poder a través de la prostitución y el juego ilegal. Un joven abogado (Richard Kiley) intenta contribuir a resolver el problema animando a su padre (McIntire) para que presente su candidatura a Fiscal de Distrito.', '/9VB4tGVtym2qXodfxQsCAJBKkSO.jpg', '/AgpNe0X1qluiYKC4t6IYlAsAdGZ.jpg', 6.5, 'XCcWkN8KPek', array['1001']::text[], 322, null, 'segura', null),
(11700, 'movie', 'Sonrisas de una noche de verano', 'Sonrisas de una noche de verano', 'Sommarnattens leende', 1955, 'Ingmar Bergman', 'El abogado Fredrik Egerman es un hombre maduro que vive una relación platónica con Anne, su joven y virginal esposa. Henrik, hijo de un matrimonio anterior, persigue a Petra, la doncella de la familia. Una actriz llamada Desiree, antigua amante de Fredrik, está en la ciudad y él la visita, pero ahora ella tiene un nuevo amante, el Conde Malcom, casado con Charlotte. Todos estan invitados a una fiesta durante un fin de semana en la propiedad de la madre de Desiree. Charlotte intenta seducir a Fredrik para vengarse de Desiree. Mientras tanto, Anne, la casta esposa de Fredrik, se da cuenta de lo mucho que le atrae su hijastro.', '/jf2IrlQdcnDSjGnFy46Xr1tKUU5.jpg', '/mPpEL0P0JSw8AdjB2fx4NzIUIFZ.jpg', 7.4, 'kacMgRPyNrs', array['1001']::text[], 322, null, 'segura', null),
(803, 'movie', 'Noche y niebla', 'Noche y niebla', 'Nuit et Brouillard', 1956, 'Alain Resnais', 'Doce años después de la Liberación y del descubrimiento de los campos de concentración nazis, Alain Resnais entra en el desierto y siniestro campo de Auschwitz. Lentos travellings en color sobre la arquitectura despoblada, donde la hierba crece de nuevo, alternan con imágenes de archivo (en blanco y negro, rodadas en 1944) que reconstruyen la inimaginable tragedia que sufrieron los prisioneros así como las causas y las consecuencias de esa tragedia: desde el advenimiento del nazismo y la deportación de los judíos hasta el juicio de Nuremberg.', '/c0eZtYCYOe4XV55dOZ016XesKg3.jpg', '/cnl95VtUon66J1PLRPpsgYgwHF7.jpg', 8.3, 'wTBwpKB16gA', array['1001']::text[], 323, null, 'segura', null),
(3112, 'movie', 'La noche del cazador', 'La noche del cazador', 'The Night of the Hunter', 1955, 'Charles Laughton', 'Tras realizar un atraco en el que han muerto dos personas, Ben Harper regresa a su casa y esconde el botín confiando el secreto a sus hijos. En la cárcel, antes de ser ejecutado, comparte celda con Harry Powell y en sueños habla del dinero. Tras ser puesto en libertad, Powell, obsesionado por apoderarse del botín, va al pueblo de Harper, enamora a su viuda y se casa con ella.', '/fpRmDxRLAKCSW3HiJSz3RnBb5GI.jpg', '/7cVEnb4Pth3STa7YfVOk9RtzDLB.jpg', 7.9, 'GAxs6tChiKo', array['1001']::text[], 324, null, 'segura', null);
